        PokedexSpeciesDefinition(nationalDexNumber: 60, generation: 1, slug: "poliwag", name: "Poliwag", genus: "Tadpole Pokémon", description: "Its slick black skin is thin and damp. A part of its internal organs can be seen through the skin as a spiral pattern.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/060", normalKey: "pokedex/normal/060", shinyKey: "pokedex/shiny/060", silhouetteKey: "pokedex/silhouette/060")),
        PokedexSpeciesDefinition(nationalDexNumber: 61, generation: 1, slug: "poliwhirl", name: "Poliwhirl", genus: "Tadpole Pokémon", description: "Its two legs are well developed. Even though it can live on the ground, it prefers living in water.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/061", normalKey: "pokedex/normal/061", shinyKey: "pokedex/shiny/061", silhouetteKey: "pokedex/silhouette/061")),
        PokedexSpeciesDefinition(nationalDexNumber: 62, generation: 1, slug: "poliwrath", name: "Poliwrath", genus: "Tadpole Pokémon", description: "An adept swimmer, it knows the front crawl, butterfly, and more. It is faster than the best human swimmers.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/062", normalKey: "pokedex/normal/062", shinyKey: "pokedex/shiny/062", silhouetteKey: "pokedex/silhouette/062")),
        PokedexSpeciesDefinition(nationalDexNumber: 63, generation: 1, slug: "abra", name: "Abra", genus: "Psi Pokémon", description: "It sleeps for 18 hours a day. It uses a variety of extrasensory powers even while asleep.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/063", normalKey: "pokedex/normal/063", shinyKey: "pokedex/shiny/063", silhouetteKey: "pokedex/silhouette/063")),
        PokedexSpeciesDefinition(nationalDexNumber: 64, generation: 1, slug: "kadabra", name: "Kadabra", genus: "Psi Pokémon", description: "It happened one morning - a boy with extrasensory powers awoke in bed transformed into KADABRA.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/064", normalKey: "pokedex/normal/064", shinyKey: "pokedex/shiny/064", silhouetteKey: "pokedex/silhouette/064")),
        PokedexSpeciesDefinition(nationalDexNumber: 65, generation: 1, slug: "alakazam", name: "Alakazam", genus: "Psi Pokémon", description: "It does not like physical attacks very much. Instead, it freely uses extra sensory powers to defeat foes.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/065", normalKey: "pokedex/normal/065", shinyKey: "pokedex/shiny/065", silhouetteKey: "pokedex/silhouette/065")),
        PokedexSpeciesDefinition(nationalDexNumber: 66, generation: 1, slug: "machop", name: "Machop", genus: "Superpower Pokémon", description: "Its whole body is composed of muscles. Even though it’s the size of a human child, it can hurl 100 grown-ups.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/066", normalKey: "pokedex/normal/066", shinyKey: "pokedex/shiny/066", silhouetteKey: "pokedex/silhouette/066")),
        PokedexSpeciesDefinition(nationalDexNumber: 67, generation: 1, slug: "machoke", name: "Machoke", genus: "Superpower Pokémon", description: "Its formidable body never gets tired. It helps people by doing work such as the moving of heavy goods.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/067", normalKey: "pokedex/normal/067", shinyKey: "pokedex/shiny/067", silhouetteKey: "pokedex/silhouette/067")),
        PokedexSpeciesDefinition(nationalDexNumber: 68, generation: 1, slug: "machamp", name: "Machamp", genus: "Superpower Pokémon", description: "Its four ruggedly developed arms can launch a flurry of 1,000 punches in just two seconds.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/068", normalKey: "pokedex/normal/068", shinyKey: "pokedex/shiny/068", silhouetteKey: "pokedex/silhouette/068")),
        PokedexSpeciesDefinition(nationalDexNumber: 69, generation: 1, slug: "bellsprout", name: "Bellsprout", genus: "Flower Pokémon", description: "Its bud looks like a human face. Because of the bud, it is rumored to be a type of legendary mandrake plant.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/069", normalKey: "pokedex/normal/069", shinyKey: "pokedex/shiny/069", silhouetteKey: "pokedex/silhouette/069")),
        PokedexSpeciesDefinition(nationalDexNumber: 70, generation: 1, slug: "weepinbell", name: "Weepinbell", genus: "Flycatcher Pokémon", description: "The leafy parts act as cutters for slashing foes. It spits a fluid that dissolves everything.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/070", normalKey: "pokedex/normal/070", shinyKey: "pokedex/shiny/070", silhouetteKey: "pokedex/silhouette/070")),
        PokedexSpeciesDefinition(nationalDexNumber: 71, generation: 1, slug: "victreebel", name: "Victreebel", genus: "Flycatcher Pokémon", description: "Lures prey into its mouth with a honeylike aroma. The helpless prey is melted with a dissolving fluid.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/071", normalKey: "pokedex/normal/071", shinyKey: "pokedex/shiny/071", silhouetteKey: "pokedex/silhouette/071")),
        PokedexSpeciesDefinition(nationalDexNumber: 72, generation: 1, slug: "tentacool", name: "Tentacool", genus: "Jellyfish Pokémon", description: "Its eyes are as transparent as crystals. From them, it shoots mysterious beams of light.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/072", normalKey: "pokedex/normal/072", shinyKey: "pokedex/shiny/072", silhouetteKey: "pokedex/silhouette/072")),
        PokedexSpeciesDefinition(nationalDexNumber: 73, generation: 1, slug: "tentacruel", name: "Tentacruel", genus: "Jellyfish Pokémon", description: "It has 80 tentacles that move about freely. They can sting, causing poisoning and sharp, stabbing pain.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/073", normalKey: "pokedex/normal/073", shinyKey: "pokedex/shiny/073", silhouetteKey: "pokedex/silhouette/073")),
        PokedexSpeciesDefinition(nationalDexNumber: 74, generation: 1, slug: "geodude", name: "Geodude", genus: "Rock Pokémon", description: "Its round form makes it easy to pick up. Some people have used them to hurl at each other in a snowball fight.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/074", normalKey: "pokedex/normal/074", shinyKey: "pokedex/shiny/074", silhouetteKey: "pokedex/silhouette/074")),
        PokedexSpeciesDefinition(nationalDexNumber: 75, generation: 1, slug: "graveler", name: "Graveler", genus: "Rock Pokémon", description: "Be careful while hiking on mountain trails. GRAVELER may come rolling down the path without slowing.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/075", normalKey: "pokedex/normal/075", shinyKey: "pokedex/shiny/075", silhouetteKey: "pokedex/silhouette/075")),
        PokedexSpeciesDefinition(nationalDexNumber: 76, generation: 1, slug: "golem", name: "Golem", genus: "Megaton Pokémon", description: "It is enclosed in a hard shell that is as rugged as slabs of rock. It sheds skin once a year to grow larger.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/076", normalKey: "pokedex/normal/076", shinyKey: "pokedex/shiny/076", silhouetteKey: "pokedex/silhouette/076")),
        PokedexSpeciesDefinition(nationalDexNumber: 77, generation: 1, slug: "ponyta", name: "Ponyta", genus: "Fire Horse Pokémon", description: "Its body is light, and its legs are incredibly powerful. It can clear Ayers Rock in one leap.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/077", normalKey: "pokedex/normal/077", shinyKey: "pokedex/shiny/077", silhouetteKey: "pokedex/silhouette/077")),
        PokedexSpeciesDefinition(nationalDexNumber: 78, generation: 1, slug: "rapidash", name: "Rapidash", genus: "Fire Horse Pokémon", description: "It can gallop at a top speed of 150 miles per hour. It can race as fast as a bullet train while ablaze.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/078", normalKey: "pokedex/normal/078", shinyKey: "pokedex/shiny/078", silhouetteKey: "pokedex/silhouette/078")),
        PokedexSpeciesDefinition(nationalDexNumber: 79, generation: 1, slug: "slowpoke", name: "Slowpoke", genus: "Dopey Pokémon", description: "It is always vacantly lost in thought, but no one knows what it is thinking about. It is good at fishing with its tail.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/079", normalKey: "pokedex/normal/079", shinyKey: "pokedex/shiny/079", silhouetteKey: "pokedex/silhouette/079")),
        PokedexSpeciesDefinition(nationalDexNumber: 80, generation: 1, slug: "slowbro", name: "Slowbro", genus: "Hermit Crab Pokémon", description: "When a SLOWPOKE went hunting in the sea, its tail was bitten by a SHELLDER. That made it evolve into SLOWBRO.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/080", normalKey: "pokedex/normal/080", shinyKey: "pokedex/shiny/080", silhouetteKey: "pokedex/silhouette/080")),
        PokedexSpeciesDefinition(nationalDexNumber: 81, generation: 1, slug: "magnemite", name: "Magnemite", genus: "Magnet Pokémon", description: "It moves while constantly hovering. It discharges THUNDER WAVE and so on from the units at its sides.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/081", normalKey: "pokedex/normal/081", shinyKey: "pokedex/shiny/081", silhouetteKey: "pokedex/silhouette/081")),
        PokedexSpeciesDefinition(nationalDexNumber: 82, generation: 1, slug: "magneton", name: "Magneton", genus: "Magnet Pokémon", description: "A linked cluster formed of several MAGNEMITE. It discharges powerful magnetic waves at high voltage.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/082", normalKey: "pokedex/normal/082", shinyKey: "pokedex/shiny/082", silhouetteKey: "pokedex/silhouette/082")),
        PokedexSpeciesDefinition(nationalDexNumber: 83, generation: 1, slug: "farfetchd", name: "Farfetch’d", genus: "Wild Duck Pokémon", description: "It always walks about with a plant stalk clamped in its beak. The stalk is used for building its nest.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/083", normalKey: "pokedex/normal/083", shinyKey: "pokedex/shiny/083", silhouetteKey: "pokedex/silhouette/083")),
        PokedexSpeciesDefinition(nationalDexNumber: 84, generation: 1, slug: "doduo", name: "Doduo", genus: "Twin Bird Pokémon", description: "A two-headed Pokémon that was discovered as a sudden mutation. It runs at a pace of over 60 miles per hour.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/084", normalKey: "pokedex/normal/084", shinyKey: "pokedex/shiny/084", silhouetteKey: "pokedex/silhouette/084")),
        PokedexSpeciesDefinition(nationalDexNumber: 85, generation: 1, slug: "dodrio", name: "Dodrio", genus: "Triple Bird Pokémon", description: "An odd species that is rarely found. The three heads respectively represent joy, sadness, and anger.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/085", normalKey: "pokedex/normal/085", shinyKey: "pokedex/shiny/085", silhouetteKey: "pokedex/silhouette/085")),
        PokedexSpeciesDefinition(nationalDexNumber: 86, generation: 1, slug: "seel", name: "Seel", genus: "Sea Lion Pokémon", description: "Covered with light blue fur, its hide is thick and tough. It is active in bitter cold of minus 40 degrees Fahrenheit.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/086", normalKey: "pokedex/normal/086", shinyKey: "pokedex/shiny/086", silhouetteKey: "pokedex/silhouette/086")),
        PokedexSpeciesDefinition(nationalDexNumber: 87, generation: 1, slug: "dewgong", name: "Dewgong", genus: "Sea Lion Pokémon", description: "Its body is covered with a pure white fur. The colder the weather, the more active it becomes.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/087", normalKey: "pokedex/normal/087", shinyKey: "pokedex/shiny/087", silhouetteKey: "pokedex/silhouette/087")),
        PokedexSpeciesDefinition(nationalDexNumber: 88, generation: 1, slug: "grimer", name: "Grimer", genus: "Sludge Pokémon", description: "Sludge exposed to X rays from the moon transformed into GRIMER. It loves feeding on filthy things.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/088", normalKey: "pokedex/normal/088", shinyKey: "pokedex/shiny/088", silhouetteKey: "pokedex/silhouette/088")),
        PokedexSpeciesDefinition(nationalDexNumber: 89, generation: 1, slug: "muk", name: "Muk", genus: "Sludge Pokémon", description: "It is usually undetectable because it blends in with the ground. Touching it can cause terrible poisoning.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/089", normalKey: "pokedex/normal/089", shinyKey: "pokedex/shiny/089", silhouetteKey: "pokedex/silhouette/089")),
        PokedexSpeciesDefinition(nationalDexNumber: 90, generation: 1, slug: "shellder", name: "Shellder", genus: "Bivalve Pokémon", description: "It is encased in a shell that is harder than diamond. Inside, however, it is surprisingly tender.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/090", normalKey: "pokedex/normal/090", shinyKey: "pokedex/shiny/090", silhouetteKey: "pokedex/silhouette/090")),
        PokedexSpeciesDefinition(nationalDexNumber: 91, generation: 1, slug: "cloyster", name: "Cloyster", genus: "Bivalve Pokémon", description: "Its shell is extremely hard. It cannot be shattered, even with a bomb. The shell opens only when it is attacking.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/091", normalKey: "pokedex/normal/091", shinyKey: "pokedex/shiny/091", silhouetteKey: "pokedex/silhouette/091")),
        PokedexSpeciesDefinition(nationalDexNumber: 92, generation: 1, slug: "gastly", name: "Gastly", genus: "Gas Pokémon", description: "A being that exists as a thin gas. It can topple an Indian elephant by enveloping the prey in two seconds.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/092", normalKey: "pokedex/normal/092", shinyKey: "pokedex/shiny/092", silhouetteKey: "pokedex/silhouette/092")),
        PokedexSpeciesDefinition(nationalDexNumber: 93, generation: 1, slug: "haunter", name: "Haunter", genus: "Gas Pokémon", description: "If you get the feeling of being watched in darkness when nobody is around, HAUNTER is there.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/093", normalKey: "pokedex/normal/093", shinyKey: "pokedex/shiny/093", silhouetteKey: "pokedex/silhouette/093")),
        PokedexSpeciesDefinition(nationalDexNumber: 94, generation: 1, slug: "gengar", name: "Gengar", genus: "Shadow Pokémon", description: "It is said to emerge from darkness to steal the lives of those who become lost in mountains.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/094", normalKey: "pokedex/normal/094", shinyKey: "pokedex/shiny/094", silhouetteKey: "pokedex/silhouette/094")),
        PokedexSpeciesDefinition(nationalDexNumber: 95, generation: 1, slug: "onix", name: "Onix", genus: "Rock Snake Pokémon", description: "It usually lives underground. It searches for food while boring its way through the ground at 50 miles per hour.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/095", normalKey: "pokedex/normal/095", shinyKey: "pokedex/shiny/095", silhouetteKey: "pokedex/silhouette/095")),
        PokedexSpeciesDefinition(nationalDexNumber: 96, generation: 1, slug: "drowzee", name: "Drowzee", genus: "Hypnosis Pokémon", description: "A descendent of the legendary animal baku, which is said to eat dreams. It is skilled at hypnotism.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/096", normalKey: "pokedex/normal/096", shinyKey: "pokedex/shiny/096", silhouetteKey: "pokedex/silhouette/096")),
        PokedexSpeciesDefinition(nationalDexNumber: 97, generation: 1, slug: "hypno", name: "Hypno", genus: "Hypnosis Pokémon", description: "It carries a pendulum-like device. There once was an incident in which it took away a child it hypnotized.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/097", normalKey: "pokedex/normal/097", shinyKey: "pokedex/shiny/097", silhouetteKey: "pokedex/silhouette/097")),
        PokedexSpeciesDefinition(nationalDexNumber: 98, generation: 1, slug: "krabby", name: "Krabby", genus: "River Crab Pokémon", description: "It can be found near the sea. The large pincers grow back if they are torn out of their sockets.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/098", normalKey: "pokedex/normal/098", shinyKey: "pokedex/shiny/098", silhouetteKey: "pokedex/silhouette/098")),
        PokedexSpeciesDefinition(nationalDexNumber: 99, generation: 1, slug: "kingler", name: "Kingler", genus: "Pincer Pokémon", description: "Its large and hard pincer has 10,000- horsepower strength. However, being so big, it is unwieldy to move.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/099", normalKey: "pokedex/normal/099", shinyKey: "pokedex/shiny/099", silhouetteKey: "pokedex/silhouette/099")),
        PokedexSpeciesDefinition(nationalDexNumber: 100, generation: 1, slug: "voltorb", name: "Voltorb", genus: "Ball Pokémon", description: "A life-form whose identity is unknown. It is said to SCREECH or suddenly SELFDESTRUCT.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/100", normalKey: "pokedex/normal/100", shinyKey: "pokedex/shiny/100", silhouetteKey: "pokedex/silhouette/100")),
        PokedexSpeciesDefinition(nationalDexNumber: 101, generation: 1, slug: "electrode", name: "Electrode", genus: "Ball Pokémon", description: "It explodes in response to even minor stimuli. It is feared, with the nickname of “The Bomb Ball.”", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/101", normalKey: "pokedex/normal/101", shinyKey: "pokedex/shiny/101", silhouetteKey: "pokedex/silhouette/101")),
        PokedexSpeciesDefinition(nationalDexNumber: 102, generation: 1, slug: "exeggcute", name: "Exeggcute", genus: "Egg Pokémon", description: "Even though it appears to be eggs of some sort, it was discovered to be a life- form more like plant seeds.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/102", normalKey: "pokedex/normal/102", shinyKey: "pokedex/shiny/102", silhouetteKey: "pokedex/silhouette/102")),
        PokedexSpeciesDefinition(nationalDexNumber: 103, generation: 1, slug: "exeggutor", name: "Exeggutor", genus: "Coconut Pokémon", description: "It is called “The Walking Tropical Rainforest.” Each of the nuts has a face and a will of its own.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/103", normalKey: "pokedex/normal/103", shinyKey: "pokedex/shiny/103", silhouetteKey: "pokedex/silhouette/103")),
        PokedexSpeciesDefinition(nationalDexNumber: 104, generation: 1, slug: "cubone", name: "Cubone", genus: "Lonely Pokémon", description: "It wears the skull of its dead mother on its head. When it becomes lonesome, it is said to cry loudly.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/104", normalKey: "pokedex/normal/104", shinyKey: "pokedex/shiny/104", silhouetteKey: "pokedex/silhouette/104")),
        PokedexSpeciesDefinition(nationalDexNumber: 105, generation: 1, slug: "marowak", name: "Marowak", genus: "Bone Keeper Pokémon", description: "It is small and was originally very weak. Its temperament turned ferocious when it began using bones.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/105", normalKey: "pokedex/normal/105", shinyKey: "pokedex/shiny/105", silhouetteKey: "pokedex/silhouette/105")),
        PokedexSpeciesDefinition(nationalDexNumber: 106, generation: 1, slug: "hitmonlee", name: "Hitmonlee", genus: "Kicking Pokémon", description: "The legs freely contract and stretch. The stretchy legs allow it to hit a distant foe with a rising kick.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/106", normalKey: "pokedex/normal/106", shinyKey: "pokedex/shiny/106", silhouetteKey: "pokedex/silhouette/106")),
        PokedexSpeciesDefinition(nationalDexNumber: 107, generation: 1, slug: "hitmonchan", name: "Hitmonchan", genus: "Punching Pokémon", description: "The spirit of a pro boxer has infused this Pokémon. It throws punches that are faster than a bullet train.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/107", normalKey: "pokedex/normal/107", shinyKey: "pokedex/shiny/107", silhouetteKey: "pokedex/silhouette/107")),
        PokedexSpeciesDefinition(nationalDexNumber: 108, generation: 1, slug: "lickitung", name: "Lickitung", genus: "Licking Pokémon", description: "Its tongue is twice the length of its body. It can be moved like an arm for grabbing food and attacking.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/108", normalKey: "pokedex/normal/108", shinyKey: "pokedex/shiny/108", silhouetteKey: "pokedex/silhouette/108")),
        PokedexSpeciesDefinition(nationalDexNumber: 109, generation: 1, slug: "koffing", name: "Koffing", genus: "Poison Gas Pokémon", description: "Its thin, balloon-like body is inflated by horribly toxic gases. It reeks when it is nearby.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/109", normalKey: "pokedex/normal/109", shinyKey: "pokedex/shiny/109", silhouetteKey: "pokedex/silhouette/109")),
        PokedexSpeciesDefinition(nationalDexNumber: 110, generation: 1, slug: "weezing", name: "Weezing", genus: "Poison Gas Pokémon", description: "Very rarely, a sudden mutation can result in two small KOFFING twins becoming conjoined as a WEEZING.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/110", normalKey: "pokedex/normal/110", shinyKey: "pokedex/shiny/110", silhouetteKey: "pokedex/silhouette/110")),
        PokedexSpeciesDefinition(nationalDexNumber: 111, generation: 1, slug: "rhyhorn", name: "Rhyhorn", genus: "Spikes Pokémon", description: "Strong, but not too bright, this Pokémon can shatter even a skyscraper with its charging TACKLES.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/111", normalKey: "pokedex/normal/111", shinyKey: "pokedex/shiny/111", silhouetteKey: "pokedex/silhouette/111")),
        PokedexSpeciesDefinition(nationalDexNumber: 112, generation: 1, slug: "rhydon", name: "Rhydon", genus: "Drill Pokémon", description: "It begins walking on its hind legs after evolution. It can punch holes through boulders with its horn.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/112", normalKey: "pokedex/normal/112", shinyKey: "pokedex/shiny/112", silhouetteKey: "pokedex/silhouette/112")),
        PokedexSpeciesDefinition(nationalDexNumber: 113, generation: 1, slug: "chansey", name: "Chansey", genus: "Egg Pokémon", description: "It lays several eggs a day. The eggs are apparently rich in nutrients and extremely delicious.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/113", normalKey: "pokedex/normal/113", shinyKey: "pokedex/shiny/113", silhouetteKey: "pokedex/silhouette/113")),
        PokedexSpeciesDefinition(nationalDexNumber: 114, generation: 1, slug: "tangela", name: "Tangela", genus: "Vine Pokémon", description: "Blue plant vines cloak the Pokémon’s identity in a tangled mass. It entangles anything that gets close.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/114", normalKey: "pokedex/normal/114", shinyKey: "pokedex/shiny/114", silhouetteKey: "pokedex/silhouette/114")),
        PokedexSpeciesDefinition(nationalDexNumber: 115, generation: 1, slug: "kangaskhan", name: "Kangaskhan", genus: "Parent Pokémon", description: "The female raises its offspring in a pouch on its belly. It is skilled at attacking using COMET PUNCH.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/115", normalKey: "pokedex/normal/115", shinyKey: "pokedex/shiny/115", silhouetteKey: "pokedex/silhouette/115")),
        PokedexSpeciesDefinition(nationalDexNumber: 116, generation: 1, slug: "horsea", name: "Horsea", genus: "Dragon Pokémon", description: "It maintains balance using its tail, which is wound up like a coil. It may spray ink from its mouth.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/116", normalKey: "pokedex/normal/116", shinyKey: "pokedex/shiny/116", silhouetteKey: "pokedex/silhouette/116")),
        PokedexSpeciesDefinition(nationalDexNumber: 117, generation: 1, slug: "seadra", name: "Seadra", genus: "Dragon Pokémon", description: "Its body bristles with sharp spikes. Carelessly trying to touch it could cause fainting from the spikes.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/117", normalKey: "pokedex/normal/117", shinyKey: "pokedex/shiny/117", silhouetteKey: "pokedex/silhouette/117")),
        PokedexSpeciesDefinition(nationalDexNumber: 118, generation: 1, slug: "goldeen", name: "Goldeen", genus: "Goldfish Pokémon", description: "Its dorsal and pectoral fins are strongly developed like muscles. It can swim at a speed of five knots.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/118", normalKey: "pokedex/normal/118", shinyKey: "pokedex/shiny/118", silhouetteKey: "pokedex/silhouette/118")),
        PokedexSpeciesDefinition(nationalDexNumber: 119, generation: 1, slug: "seaking", name: "Seaking", genus: "Goldfish Pokémon", description: "The horn on its head is sharp like a drill. It bores a hole in a boulder to make its nest.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/119", normalKey: "pokedex/normal/119", shinyKey: "pokedex/shiny/119", silhouetteKey: "pokedex/silhouette/119")),
        PokedexSpeciesDefinition(nationalDexNumber: 120, generation: 1, slug: "staryu", name: "Staryu", genus: "Star Shape Pokémon", description: "It appears in large numbers by seashores. At night, its central core flashes with a red light.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/120", normalKey: "pokedex/normal/120", shinyKey: "pokedex/shiny/120", silhouetteKey: "pokedex/silhouette/120")),
        PokedexSpeciesDefinition(nationalDexNumber: 121, generation: 1, slug: "starmie", name: "Starmie", genus: "Mysterious Pokémon", description: "This Pokémon has a geometric body. Because of its body, the locals suspect that it is an alien creature.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/121", normalKey: "pokedex/normal/121", shinyKey: "pokedex/shiny/121", silhouetteKey: "pokedex/silhouette/121")),
        PokedexSpeciesDefinition(nationalDexNumber: 122, generation: 1, slug: "mr-mime", name: "Mr. Mime", genus: "Barrier Pokémon", description: "It is adept at conning people. It is said to be able to create walls out of thin air by miming.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/122", normalKey: "pokedex/normal/122", shinyKey: "pokedex/shiny/122", silhouetteKey: "pokedex/silhouette/122")),
        PokedexSpeciesDefinition(nationalDexNumber: 123, generation: 1, slug: "scyther", name: "Scyther", genus: "Mantis Pokémon", description: "It tears and shreds prey with its wickedly sharp scythes. It very rarely spreads its wings to fly.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/123", normalKey: "pokedex/normal/123", shinyKey: "pokedex/shiny/123", silhouetteKey: "pokedex/silhouette/123")),
        PokedexSpeciesDefinition(nationalDexNumber: 124, generation: 1, slug: "jynx", name: "Jynx", genus: "Human Shape Pokémon", description: "It speaks using a language that sounds human. Research is under way to determine what is being said.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/124", normalKey: "pokedex/normal/124", shinyKey: "pokedex/shiny/124", silhouetteKey: "pokedex/silhouette/124")),
        PokedexSpeciesDefinition(nationalDexNumber: 125, generation: 1, slug: "electabuzz", name: "Electabuzz", genus: "Electric Pokémon", description: "It loves to feed on strong electricity. It occasionally appears around large power plants and so on.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/125", normalKey: "pokedex/normal/125", shinyKey: "pokedex/shiny/125", silhouetteKey: "pokedex/silhouette/125")),
        PokedexSpeciesDefinition(nationalDexNumber: 126, generation: 1, slug: "magmar", name: "Magmar", genus: "Spitfire Pokémon", description: "Found near the mouth of a volcano. This fire-breather’s body temperature is nearly 2,200 degrees Fahrenheit.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/126", normalKey: "pokedex/normal/126", shinyKey: "pokedex/shiny/126", silhouetteKey: "pokedex/silhouette/126")),
        PokedexSpeciesDefinition(nationalDexNumber: 127, generation: 1, slug: "pinsir", name: "Pinsir", genus: "Stag Beetle Pokémon", description: "Its two long pincer horns are powerful. Once they grip an enemy, they won’t release until the foe is torn.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/127", normalKey: "pokedex/normal/127", shinyKey: "pokedex/shiny/127", silhouetteKey: "pokedex/silhouette/127")),
        PokedexSpeciesDefinition(nationalDexNumber: 128, generation: 1, slug: "tauros", name: "Tauros", genus: "Wild Bull Pokémon", description: "When it is about to TACKLE, it whips its body repeatedly with its three long tails.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/128", normalKey: "pokedex/normal/128", shinyKey: "pokedex/shiny/128", silhouetteKey: "pokedex/silhouette/128")),
        PokedexSpeciesDefinition(nationalDexNumber: 129, generation: 1, slug: "magikarp", name: "Magikarp", genus: "Fish Pokémon", description: "It is virtually worthless in terms of both power and speed. It is the most weak and pathetic Pokémon in the world.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/129", normalKey: "pokedex/normal/129", shinyKey: "pokedex/shiny/129", silhouetteKey: "pokedex/silhouette/129")),
        PokedexSpeciesDefinition(nationalDexNumber: 130, generation: 1, slug: "gyarados", name: "Gyarados", genus: "Atrocious Pokémon", description: "It has an extremely aggressive nature. The HYPER BEAM it shoots from its mouth totally incinerates all targets.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/130", normalKey: "pokedex/normal/130", shinyKey: "pokedex/shiny/130", silhouetteKey: "pokedex/silhouette/130")),
        PokedexSpeciesDefinition(nationalDexNumber: 131, generation: 1, slug: "lapras", name: "Lapras", genus: "Transport Pokémon", description: "Its high intelligence enables it to understand human speech. It likes to ferry people on its back.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/131", normalKey: "pokedex/normal/131", shinyKey: "pokedex/shiny/131", silhouetteKey: "pokedex/silhouette/131")),
        PokedexSpeciesDefinition(nationalDexNumber: 132, generation: 1, slug: "ditto", name: "Ditto", genus: "Transform Pokémon", description: "It can freely recombine its own cellular structure to transform into other life- forms.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/132", normalKey: "pokedex/normal/132", shinyKey: "pokedex/shiny/132", silhouetteKey: "pokedex/silhouette/132")),
        PokedexSpeciesDefinition(nationalDexNumber: 133, generation: 1, slug: "eevee", name: "Eevee", genus: "Evolution Pokémon", description: "An extremely rare Pokémon that may evolve in a number of different ways depending on stimuli.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/133", normalKey: "pokedex/normal/133", shinyKey: "pokedex/shiny/133", silhouetteKey: "pokedex/silhouette/133")),
        PokedexSpeciesDefinition(nationalDexNumber: 134, generation: 1, slug: "vaporeon", name: "Vaporeon", genus: "Bubble Jet Pokémon", description: "Its body’s cellular structure is similar to the molecular composition of water. It can melt invisibly in water.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/134", normalKey: "pokedex/normal/134", shinyKey: "pokedex/shiny/134", silhouetteKey: "pokedex/silhouette/134")),
        PokedexSpeciesDefinition(nationalDexNumber: 135, generation: 1, slug: "jolteon", name: "Jolteon", genus: "Lightning Pokémon", description: "If it is angered or startled, the fur all over its body bristles like sharp needles that pierce foes.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/135", normalKey: "pokedex/normal/135", shinyKey: "pokedex/shiny/135", silhouetteKey: "pokedex/silhouette/135")),
        PokedexSpeciesDefinition(nationalDexNumber: 136, generation: 1, slug: "flareon", name: "Flareon", genus: "Flame Pokémon", description: "It has a flame bag inside its body. After inhaling deeply, it blows out flames of nearly 3,100 degrees Fahrenheit.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/136", normalKey: "pokedex/normal/136", shinyKey: "pokedex/shiny/136", silhouetteKey: "pokedex/silhouette/136")),
        PokedexSpeciesDefinition(nationalDexNumber: 137, generation: 1, slug: "porygon", name: "Porygon", genus: "Virtual Pokémon", description: "Using the most advanced technologies, scientists finally succeeded in making the first artificial Pokémon.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/137", normalKey: "pokedex/normal/137", shinyKey: "pokedex/shiny/137", silhouetteKey: "pokedex/silhouette/137")),
        PokedexSpeciesDefinition(nationalDexNumber: 138, generation: 1, slug: "omanyte", name: "Omanyte", genus: "Spiral Pokémon", description: "A prehistoric Pokémon that lived in the primordial sea, it swims by twisting its 10 tentacles about.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/138", normalKey: "pokedex/normal/138", shinyKey: "pokedex/shiny/138", silhouetteKey: "pokedex/silhouette/138")),
        PokedexSpeciesDefinition(nationalDexNumber: 139, generation: 1, slug: "omastar", name: "Omastar", genus: "Spiral Pokémon", description: "Its tentacles are highly developed as if they are hands and feet. As soon as it ensnares prey, it bites.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/139", normalKey: "pokedex/normal/139", shinyKey: "pokedex/shiny/139", silhouetteKey: "pokedex/silhouette/139")),
        PokedexSpeciesDefinition(nationalDexNumber: 140, generation: 1, slug: "kabuto", name: "Kabuto", genus: "Shellfish Pokémon", description: "This Pokémon was regenerated from the fossil of an ancient creature. It protects itself with a hard shell.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/140", normalKey: "pokedex/normal/140", shinyKey: "pokedex/shiny/140", silhouetteKey: "pokedex/silhouette/140")),
        PokedexSpeciesDefinition(nationalDexNumber: 141, generation: 1, slug: "kabutops", name: "Kabutops", genus: "Shellfish Pokémon", description: "It swims freely through water. It catches prey with its scythe-like arms and drains the victim’s fluids.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/141", normalKey: "pokedex/normal/141", shinyKey: "pokedex/shiny/141", silhouetteKey: "pokedex/silhouette/141")),
        PokedexSpeciesDefinition(nationalDexNumber: 142, generation: 1, slug: "aerodactyl", name: "Aerodactyl", genus: "Fossil Pokémon", description: "It was regenerated from a dinosaur’s genetic matter that was found in amber. It flies with high-pitched cries.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/142", normalKey: "pokedex/normal/142", shinyKey: "pokedex/shiny/142", silhouetteKey: "pokedex/silhouette/142")),
        PokedexSpeciesDefinition(nationalDexNumber: 143, generation: 1, slug: "snorlax", name: "Snorlax", genus: "Sleeping Pokémon", description: "It is not satisfied unless it eats over 880 pounds of food every day. When it is done eating, it goes promptly to sleep.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/143", normalKey: "pokedex/normal/143", shinyKey: "pokedex/shiny/143", silhouetteKey: "pokedex/silhouette/143")),
        PokedexSpeciesDefinition(nationalDexNumber: 144, generation: 1, slug: "articuno", name: "Articuno", genus: "Freeze Pokémon", description: "One of the legendary bird Pokémon. With its long tail trailing behind, its flying form is magnificent.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/144", normalKey: "pokedex/normal/144", shinyKey: "pokedex/shiny/144", silhouetteKey: "pokedex/silhouette/144")),
        PokedexSpeciesDefinition(nationalDexNumber: 145, generation: 1, slug: "zapdos", name: "Zapdos", genus: "Electric Pokémon", description: "One of the legendary bird Pokémon. While it is flying, it makes crackling and snapping sounds.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/145", normalKey: "pokedex/normal/145", shinyKey: "pokedex/shiny/145", silhouetteKey: "pokedex/silhouette/145")),
        PokedexSpeciesDefinition(nationalDexNumber: 146, generation: 1, slug: "moltres", name: "Moltres", genus: "Flame Pokémon", description: "One of the legendary bird Pokémon. Those seeing it are overwhelmed by its orange wings that seem to be on fire.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/146", normalKey: "pokedex/normal/146", shinyKey: "pokedex/shiny/146", silhouetteKey: "pokedex/silhouette/146")),
        PokedexSpeciesDefinition(nationalDexNumber: 147, generation: 1, slug: "dratini", name: "Dratini", genus: "Dragon Pokémon", description: "Even the young can exceed 6.5 feet in length. It grows larger by repeatedly shedding skin.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/147", normalKey: "pokedex/normal/147", shinyKey: "pokedex/shiny/147", silhouetteKey: "pokedex/silhouette/147")),
        PokedexSpeciesDefinition(nationalDexNumber: 148, generation: 1, slug: "dragonair", name: "Dragonair", genus: "Dragon Pokémon", description: "It is said to live in seas and lakes. Even though it has no wings, it has been seen flying occasionally.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/148", normalKey: "pokedex/normal/148", shinyKey: "pokedex/shiny/148", silhouetteKey: "pokedex/silhouette/148")),
        PokedexSpeciesDefinition(nationalDexNumber: 149, generation: 1, slug: "dragonite", name: "Dragonite", genus: "Dragon Pokémon", description: "It can fly in spite of its big and bulky physique. It circles the globe in just 16 hours.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/149", normalKey: "pokedex/normal/149", shinyKey: "pokedex/shiny/149", silhouetteKey: "pokedex/silhouette/149")),
        PokedexSpeciesDefinition(nationalDexNumber: 150, generation: 1, slug: "mewtwo", name: "Mewtwo", genus: "Genetic Pokémon", description: "A Pokémon whose genetic code was repeatedly recombined for research. It turned vicious as a result.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/150", normalKey: "pokedex/normal/150", shinyKey: "pokedex/shiny/150", silhouetteKey: "pokedex/silhouette/150")),
        PokedexSpeciesDefinition(nationalDexNumber: 151, generation: 1, slug: "mew", name: "Mew", genus: "New Species Pokémon", description: "A Pokémon of South America that was thought to have been extinct. It is very intelligent and learns any move.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/151", normalKey: "pokedex/normal/151", shinyKey: "pokedex/shiny/151", silhouetteKey: "pokedex/silhouette/151")),
        PokedexSpeciesDefinition(nationalDexNumber: 152, generation: 2, slug: "chikorita", name: "Chikorita", genus: "Leaf Pokémon", description: "Its pleasantly aromatic leaves have the ability to check the humidity and temperature.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/152", normalKey: "pokedex/normal/152", shinyKey: "pokedex/shiny/152", silhouetteKey: "pokedex/silhouette/152")),
        PokedexSpeciesDefinition(nationalDexNumber: 153, generation: 2, slug: "bayleef", name: "Bayleef", genus: "Leaf Pokémon", description: "A spicy aroma emanates from around its neck. The aroma acts as a stimulant to restore health.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/153", normalKey: "pokedex/normal/153", shinyKey: "pokedex/shiny/153", silhouetteKey: "pokedex/silhouette/153")),
        PokedexSpeciesDefinition(nationalDexNumber: 154, generation: 2, slug: "meganium", name: "Meganium", genus: "Herb Pokémon", description: "MEGANIUM’s breath has the power to revive dead grass and plants. It can make them healthy again.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/154", normalKey: "pokedex/normal/154", shinyKey: "pokedex/shiny/154", silhouetteKey: "pokedex/silhouette/154")),
        PokedexSpeciesDefinition(nationalDexNumber: 155, generation: 2, slug: "cyndaquil", name: "Cyndaquil", genus: "Fire Mouse Pokémon", description: "It usually stays hunched over. If it is angry or surprised, it shoots flames out of its back.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/155", normalKey: "pokedex/normal/155", shinyKey: "pokedex/shiny/155", silhouetteKey: "pokedex/silhouette/155")),
        PokedexSpeciesDefinition(nationalDexNumber: 156, generation: 2, slug: "quilava", name: "Quilava", genus: "Volcano Pokémon", description: "This Pokémon is fully covered by nonflammable fur. It can withstand any kind of fire attack.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/156", normalKey: "pokedex/normal/156", shinyKey: "pokedex/shiny/156", silhouetteKey: "pokedex/silhouette/156")),
        PokedexSpeciesDefinition(nationalDexNumber: 157, generation: 2, slug: "typhlosion", name: "Typhlosion", genus: "Volcano Pokémon", description: "It has a secret, devastating move. It rubs its blazing fur together to cause huge explosions.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/157", normalKey: "pokedex/normal/157", shinyKey: "pokedex/shiny/157", silhouetteKey: "pokedex/silhouette/157")),
        PokedexSpeciesDefinition(nationalDexNumber: 158, generation: 2, slug: "totodile", name: "Totodile", genus: "Big Jaw Pokémon", description: "It is small but rough and tough. It won’t hesitate to take a bite out of anything that moves.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/158", normalKey: "pokedex/normal/158", shinyKey: "pokedex/shiny/158", silhouetteKey: "pokedex/silhouette/158")),
        PokedexSpeciesDefinition(nationalDexNumber: 159, generation: 2, slug: "croconaw", name: "Croconaw", genus: "Big Jaw Pokémon", description: "It opens its huge jaws wide when attacking. If it loses any fangs while biting, they grow back in.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/159", normalKey: "pokedex/normal/159", shinyKey: "pokedex/shiny/159", silhouetteKey: "pokedex/silhouette/159")),
        PokedexSpeciesDefinition(nationalDexNumber: 160, generation: 2, slug: "feraligatr", name: "Feraligatr", genus: "Big Jaw Pokémon", description: "It is hard for it to support its own weight out of water, so it gets down on all fours. But it moves fast.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/160", normalKey: "pokedex/normal/160", shinyKey: "pokedex/shiny/160", silhouetteKey: "pokedex/silhouette/160")),
        PokedexSpeciesDefinition(nationalDexNumber: 161, generation: 2, slug: "sentret", name: "Sentret", genus: "Scout Pokémon", description: "It stands on its tail so it can see a long way. If it spots an enemy, it cries loudly to warn its kind.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/161", normalKey: "pokedex/normal/161", shinyKey: "pokedex/shiny/161", silhouetteKey: "pokedex/silhouette/161")),
        PokedexSpeciesDefinition(nationalDexNumber: 162, generation: 2, slug: "furret", name: "Furret", genus: "Long Body Pokémon", description: "There is no telling where its tail begins. Despite its short legs, it is quick at hunting RATTATA.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/162", normalKey: "pokedex/normal/162", shinyKey: "pokedex/shiny/162", silhouetteKey: "pokedex/silhouette/162")),
        PokedexSpeciesDefinition(nationalDexNumber: 163, generation: 2, slug: "hoothoot", name: "Hoothoot", genus: "Owl Pokémon", description: "It has a perfect sense of time. Whatever happens, it keeps rhythm by precisely tilting its head in time.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/163", normalKey: "pokedex/normal/163", shinyKey: "pokedex/shiny/163", silhouetteKey: "pokedex/silhouette/163")),
        PokedexSpeciesDefinition(nationalDexNumber: 164, generation: 2, slug: "noctowl", name: "Noctowl", genus: "Owl Pokémon", description: "When it needs to think, it rotates its head 180 degrees to sharpen its intellectual power.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/164", normalKey: "pokedex/normal/164", shinyKey: "pokedex/shiny/164", silhouetteKey: "pokedex/silhouette/164")),
        PokedexSpeciesDefinition(nationalDexNumber: 165, generation: 2, slug: "ledyba", name: "Ledyba", genus: "Five Star Pokémon", description: "When the weather turns cold, numerous LEDYBA gather from everywhere to cluster and keep each other warm.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/165", normalKey: "pokedex/normal/165", shinyKey: "pokedex/shiny/165", silhouetteKey: "pokedex/silhouette/165")),
        PokedexSpeciesDefinition(nationalDexNumber: 166, generation: 2, slug: "ledian", name: "Ledian", genus: "Five Star Pokémon", description: "The star patterns on its back grow larger or smaller depending on the number of stars in the night sky.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/166", normalKey: "pokedex/normal/166", shinyKey: "pokedex/shiny/166", silhouetteKey: "pokedex/silhouette/166")),
        PokedexSpeciesDefinition(nationalDexNumber: 167, generation: 2, slug: "spinarak", name: "Spinarak", genus: "String Spit Pokémon", description: "It spins a web using fine--but durable-- thread. It then waits patiently for prey to be trapped.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/167", normalKey: "pokedex/normal/167", shinyKey: "pokedex/shiny/167", silhouetteKey: "pokedex/silhouette/167")),
        PokedexSpeciesDefinition(nationalDexNumber: 168, generation: 2, slug: "ariados", name: "Ariados", genus: "Long Leg Pokémon", description: "A single strand of a special string is endlessly spun out of its rear. The string leads back to its nest.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/168", normalKey: "pokedex/normal/168", shinyKey: "pokedex/shiny/168", silhouetteKey: "pokedex/silhouette/168")),
        PokedexSpeciesDefinition(nationalDexNumber: 169, generation: 2, slug: "crobat", name: "Crobat", genus: "Bat Pokémon", description: "The development of wings on its legs enables it to fly fast but also makes it tough to stop and rest.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/169", normalKey: "pokedex/normal/169", shinyKey: "pokedex/shiny/169", silhouetteKey: "pokedex/silhouette/169")),
        PokedexSpeciesDefinition(nationalDexNumber: 170, generation: 2, slug: "chinchou", name: "Chinchou", genus: "Angler Pokémon", description: "On the dark ocean floor, its only means of communication is its constantly flashing lights.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/170", normalKey: "pokedex/normal/170", shinyKey: "pokedex/shiny/170", silhouetteKey: "pokedex/silhouette/170")),
        PokedexSpeciesDefinition(nationalDexNumber: 171, generation: 2, slug: "lanturn", name: "Lanturn", genus: "Light Pokémon", description: "It blinds prey with an intense burst of light, then swallows the immobilized prey in a single gulp.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/171", normalKey: "pokedex/normal/171", shinyKey: "pokedex/shiny/171", silhouetteKey: "pokedex/silhouette/171")),
        PokedexSpeciesDefinition(nationalDexNumber: 172, generation: 2, slug: "pichu", name: "Pichu", genus: "Tiny Mouse Pokémon", description: "Despite its small size, it can zap even adult humans. However, if it does so, it also surprises itself.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/172", normalKey: "pokedex/normal/172", shinyKey: "pokedex/shiny/172", silhouetteKey: "pokedex/silhouette/172")),
        PokedexSpeciesDefinition(nationalDexNumber: 173, generation: 2, slug: "cleffa", name: "Cleffa", genus: "Star Shape Pokémon", description: "When numerous meteors illuminate the night sky, sightings of CLEFFA strangely increase.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/173", normalKey: "pokedex/normal/173", shinyKey: "pokedex/shiny/173", silhouetteKey: "pokedex/silhouette/173")),
        PokedexSpeciesDefinition(nationalDexNumber: 174, generation: 2, slug: "igglybuff", name: "Igglybuff", genus: "Balloon Pokémon", description: "Its extremely flexible and elastic body makes it bounce continuously--anytime, anywhere.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/174", normalKey: "pokedex/normal/174", shinyKey: "pokedex/shiny/174", silhouetteKey: "pokedex/silhouette/174")),
        PokedexSpeciesDefinition(nationalDexNumber: 175, generation: 2, slug: "togepi", name: "Togepi", genus: "Spike Ball Pokémon", description: "A proverb claims that happiness will come to anyone who can make a sleeping TOGEPI stand up.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/175", normalKey: "pokedex/normal/175", shinyKey: "pokedex/shiny/175", silhouetteKey: "pokedex/silhouette/175")),
        PokedexSpeciesDefinition(nationalDexNumber: 176, generation: 2, slug: "togetic", name: "Togetic", genus: "Happiness Pokémon", description: "It grows dispirited if it is not with kind people. It can float in midair without moving its wings.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/176", normalKey: "pokedex/normal/176", shinyKey: "pokedex/shiny/176", silhouetteKey: "pokedex/silhouette/176")),
        PokedexSpeciesDefinition(nationalDexNumber: 177, generation: 2, slug: "natu", name: "Natu", genus: "Tiny Bird Pokémon", description: "It usually forages for food on the ground but may, on rare occasions, hop onto branches to peck at shoots.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/177", normalKey: "pokedex/normal/177", shinyKey: "pokedex/shiny/177", silhouetteKey: "pokedex/silhouette/177")),
        PokedexSpeciesDefinition(nationalDexNumber: 178, generation: 2, slug: "xatu", name: "Xatu", genus: "Mystic Pokémon", description: "In South America, it is said that its right eye sees the future and its left eye views the past.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/178", normalKey: "pokedex/normal/178", shinyKey: "pokedex/shiny/178", silhouetteKey: "pokedex/silhouette/178")),
        PokedexSpeciesDefinition(nationalDexNumber: 179, generation: 2, slug: "mareep", name: "Mareep", genus: "Wool Pokémon", description: "Its fleece grows continually. In the summer, the fleece is fully shed, but it grows back in a week.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/179", normalKey: "pokedex/normal/179", shinyKey: "pokedex/shiny/179", silhouetteKey: "pokedex/silhouette/179")),
        PokedexSpeciesDefinition(nationalDexNumber: 180, generation: 2, slug: "flaaffy", name: "Flaaffy", genus: "Wool Pokémon", description: "Its fluffy fleece easily stores electricity. Its rubbery hide keeps it from being electrocuted.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/180", normalKey: "pokedex/normal/180", shinyKey: "pokedex/shiny/180", silhouetteKey: "pokedex/silhouette/180")),
        PokedexSpeciesDefinition(nationalDexNumber: 181, generation: 2, slug: "ampharos", name: "Ampharos", genus: "Light Pokémon", description: "The bright light on its tail can be seen far away. It has been treasured since ancient times as a beacon.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/181", normalKey: "pokedex/normal/181", shinyKey: "pokedex/shiny/181", silhouetteKey: "pokedex/silhouette/181")),
        PokedexSpeciesDefinition(nationalDexNumber: 182, generation: 2, slug: "bellossom", name: "Bellossom", genus: "Flower Pokémon", description: "Plentiful in the tropics. When it dances, its petals rub together and make a pleasant ringing sound.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/182", normalKey: "pokedex/normal/182", shinyKey: "pokedex/shiny/182", silhouetteKey: "pokedex/silhouette/182")),
        PokedexSpeciesDefinition(nationalDexNumber: 183, generation: 2, slug: "marill", name: "Marill", genus: "Aqua Mouse Pokémon", description: "The end of its tail serves as a buoy that keeps it from drowning, even in a vicious current.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/183", normalKey: "pokedex/normal/183", shinyKey: "pokedex/shiny/183", silhouetteKey: "pokedex/silhouette/183")),
        PokedexSpeciesDefinition(nationalDexNumber: 184, generation: 2, slug: "azumarill", name: "Azumarill", genus: "Aqua Rabbit Pokémon", description: "When it plays in water, it rolls up its elongated ears to prevent their insides from getting wet.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/184", normalKey: "pokedex/normal/184", shinyKey: "pokedex/shiny/184", silhouetteKey: "pokedex/silhouette/184")),
        PokedexSpeciesDefinition(nationalDexNumber: 185, generation: 2, slug: "sudowoodo", name: "Sudowoodo", genus: "Imitation Pokémon", description: "It disguises itself as a tree to avoid attack. It hates water, so it will disappear if it starts raining.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/185", normalKey: "pokedex/normal/185", shinyKey: "pokedex/shiny/185", silhouetteKey: "pokedex/silhouette/185")),
        PokedexSpeciesDefinition(nationalDexNumber: 186, generation: 2, slug: "politoed", name: "Politoed", genus: "Frog Pokémon", description: "Whenever three or more of these get together, they sing in a loud voice that sounds like bellowing.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/186", normalKey: "pokedex/normal/186", shinyKey: "pokedex/shiny/186", silhouetteKey: "pokedex/silhouette/186")),
        PokedexSpeciesDefinition(nationalDexNumber: 187, generation: 2, slug: "hoppip", name: "Hoppip", genus: "Cottonweed Pokémon", description: "Its body is so light, it must grip the ground firmly with its feet to keep from being blown away.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/187", normalKey: "pokedex/normal/187", shinyKey: "pokedex/shiny/187", silhouetteKey: "pokedex/silhouette/187")),
        PokedexSpeciesDefinition(nationalDexNumber: 188, generation: 2, slug: "skiploom", name: "Skiploom", genus: "Cottonweed Pokémon", description: "It spreads its petals to absorb sunlight. It also floats in the air to get closer to the sun.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/188", normalKey: "pokedex/normal/188", shinyKey: "pokedex/shiny/188", silhouetteKey: "pokedex/silhouette/188")),
        PokedexSpeciesDefinition(nationalDexNumber: 189, generation: 2, slug: "jumpluff", name: "Jumpluff", genus: "Cottonweed Pokémon", description: "It drifts on seasonal winds and spreads its cotton-like spores all over the world to make more offspring.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/189", normalKey: "pokedex/normal/189", shinyKey: "pokedex/shiny/189", silhouetteKey: "pokedex/silhouette/189")),
        PokedexSpeciesDefinition(nationalDexNumber: 190, generation: 2, slug: "aipom", name: "Aipom", genus: "Long Tail Pokémon", description: "It lives atop tall trees. When leaping from branch to branch, it deftly uses its tail for balance.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/190", normalKey: "pokedex/normal/190", shinyKey: "pokedex/shiny/190", silhouetteKey: "pokedex/silhouette/190")),
        PokedexSpeciesDefinition(nationalDexNumber: 191, generation: 2, slug: "sunkern", name: "Sunkern", genus: "Seed Pokémon", description: "It lives by drinking only dewdrops from under the leaves of plants. It is said that it eats nothing else.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/191", normalKey: "pokedex/normal/191", shinyKey: "pokedex/shiny/191", silhouetteKey: "pokedex/silhouette/191")),
        PokedexSpeciesDefinition(nationalDexNumber: 192, generation: 2, slug: "sunflora", name: "Sunflora", genus: "Sun Pokémon", description: "In the daytime, it rushes about in a hectic manner, but it comes to a complete stop when the sun sets.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/192", normalKey: "pokedex/normal/192", shinyKey: "pokedex/shiny/192", silhouetteKey: "pokedex/silhouette/192")),
        PokedexSpeciesDefinition(nationalDexNumber: 193, generation: 2, slug: "yanma", name: "Yanma", genus: "Clear Wing Pokémon", description: "Its large eyes can scan 360 degrees. It looks in all directions to seek out insects as its prey.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/193", normalKey: "pokedex/normal/193", shinyKey: "pokedex/shiny/193", silhouetteKey: "pokedex/silhouette/193")),
        PokedexSpeciesDefinition(nationalDexNumber: 194, generation: 2, slug: "wooper", name: "Wooper", genus: "Water Fish Pokémon", description: "When it walks around on the ground, it coats its body with a slimy, poisonous film.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/194", normalKey: "pokedex/normal/194", shinyKey: "pokedex/shiny/194", silhouetteKey: "pokedex/silhouette/194")),
        PokedexSpeciesDefinition(nationalDexNumber: 195, generation: 2, slug: "quagsire", name: "Quagsire", genus: "Water Fish Pokémon", description: "Due to its relaxed and carefree attitude, it often bumps its head on boulders and boat hulls as it swims.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/195", normalKey: "pokedex/normal/195", shinyKey: "pokedex/shiny/195", silhouetteKey: "pokedex/silhouette/195")),
        PokedexSpeciesDefinition(nationalDexNumber: 196, generation: 2, slug: "espeon", name: "Espeon", genus: "Sun Pokémon", description: "By reading air currents, it can predict things such as the weather or its foe’s next move.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/196", normalKey: "pokedex/normal/196", shinyKey: "pokedex/shiny/196", silhouetteKey: "pokedex/silhouette/196")),
        PokedexSpeciesDefinition(nationalDexNumber: 197, generation: 2, slug: "umbreon", name: "Umbreon", genus: "Moonlight Pokémon", description: "When darkness falls, the rings on its body begin to glow, striking fear in the hearts of anyone nearby.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/197", normalKey: "pokedex/normal/197", shinyKey: "pokedex/shiny/197", silhouetteKey: "pokedex/silhouette/197")),
        PokedexSpeciesDefinition(nationalDexNumber: 198, generation: 2, slug: "murkrow", name: "Murkrow", genus: "Darkness Pokémon", description: "It is said that when chased, it lures its attacker onto dark mountain trails where the foe will get lost.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/198", normalKey: "pokedex/normal/198", shinyKey: "pokedex/shiny/198", silhouetteKey: "pokedex/silhouette/198")),
        PokedexSpeciesDefinition(nationalDexNumber: 199, generation: 2, slug: "slowking", name: "Slowking", genus: "Royal Pokémon", description: "When its head was bitten, toxins entered SLOWPOKE’s head and unlocked an extraordinary power.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/199", normalKey: "pokedex/normal/199", shinyKey: "pokedex/shiny/199", silhouetteKey: "pokedex/silhouette/199")),
        PokedexSpeciesDefinition(nationalDexNumber: 200, generation: 2, slug: "misdreavus", name: "Misdreavus", genus: "Screech Pokémon", description: "It loves to bite and yank people’s hair from behind without warning, just to see their shocked reactions.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/200", normalKey: "pokedex/normal/200", shinyKey: "pokedex/shiny/200", silhouetteKey: "pokedex/silhouette/200")),
        PokedexSpeciesDefinition(nationalDexNumber: 201, generation: 2, slug: "unown", name: "Unown", genus: "Symbol Pokémon", description: "Its flat, thin body is always stuck on walls. Its shape appears to have some meaning.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/201", normalKey: "pokedex/normal/201", shinyKey: "pokedex/shiny/201", silhouetteKey: "pokedex/silhouette/201")),
        PokedexSpeciesDefinition(nationalDexNumber: 202, generation: 2, slug: "wobbuffet", name: "Wobbuffet", genus: "Patient Pokémon", description: "To keep its pitch-black tail hidden, it lives quietly in the darkness. It is never first to attack.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/202", normalKey: "pokedex/normal/202", shinyKey: "pokedex/shiny/202", silhouetteKey: "pokedex/silhouette/202")),
        PokedexSpeciesDefinition(nationalDexNumber: 203, generation: 2, slug: "girafarig", name: "Girafarig", genus: "Long Neck Pokémon", description: "Its tail, which also contains a small brain, may bite on its own if it notices an alluring smell.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/203", normalKey: "pokedex/normal/203", shinyKey: "pokedex/shiny/203", silhouetteKey: "pokedex/silhouette/203")),
        PokedexSpeciesDefinition(nationalDexNumber: 204, generation: 2, slug: "pineco", name: "Pineco", genus: "Bagworm Pokémon", description: "It hangs and waits for flying-insect prey to come near. It does not move about much on its own.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/204", normalKey: "pokedex/normal/204", shinyKey: "pokedex/shiny/204", silhouetteKey: "pokedex/silhouette/204")),
        PokedexSpeciesDefinition(nationalDexNumber: 205, generation: 2, slug: "forretress", name: "Forretress", genus: "Bagworm Pokémon", description: "It remains immovably rooted to its tree. It scatters pieces of its hard shell to drive its enemies away.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/205", normalKey: "pokedex/normal/205", shinyKey: "pokedex/shiny/205", silhouetteKey: "pokedex/silhouette/205")),
        PokedexSpeciesDefinition(nationalDexNumber: 206, generation: 2, slug: "dunsparce", name: "Dunsparce", genus: "Land Snake Pokémon", description: "If spotted, it escapes by burrowing with its tail. It can hover just slightly using its wings.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/206", normalKey: "pokedex/normal/206", shinyKey: "pokedex/shiny/206", silhouetteKey: "pokedex/silhouette/206")),
        PokedexSpeciesDefinition(nationalDexNumber: 207, generation: 2, slug: "gligar", name: "Gligar", genus: "Fly Scorpion Pokémon", description: "It usually clings to cliffs. When it spots its prey, it spreads its wings and glides down to attack.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/207", normalKey: "pokedex/normal/207", shinyKey: "pokedex/shiny/207", silhouetteKey: "pokedex/silhouette/207")),
        PokedexSpeciesDefinition(nationalDexNumber: 208, generation: 2, slug: "steelix", name: "Steelix", genus: "Iron Snake Pokémon", description: "It is said that if an ONIX lives for over 100 years, its composition changes to become diamond-like.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/208", normalKey: "pokedex/normal/208", shinyKey: "pokedex/shiny/208", silhouetteKey: "pokedex/silhouette/208")),
        PokedexSpeciesDefinition(nationalDexNumber: 209, generation: 2, slug: "snubbull", name: "Snubbull", genus: "Fairy Pokémon", description: "It has an active, playful nature. Many women like to frolic with it because of its affectionate ways.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/209", normalKey: "pokedex/normal/209", shinyKey: "pokedex/shiny/209", silhouetteKey: "pokedex/silhouette/209")),
        PokedexSpeciesDefinition(nationalDexNumber: 210, generation: 2, slug: "granbull", name: "Granbull", genus: "Fairy Pokémon", description: "Because its fangs are too heavy, it always keeps its head tilted down. However, its BITE is powerful.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/210", normalKey: "pokedex/normal/210", shinyKey: "pokedex/shiny/210", silhouetteKey: "pokedex/silhouette/210")),
        PokedexSpeciesDefinition(nationalDexNumber: 211, generation: 2, slug: "qwilfish", name: "Qwilfish", genus: "Balloon Pokémon", description: "The small spikes covering its body developed from scales. They inject a toxin that causes fainting.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/211", normalKey: "pokedex/normal/211", shinyKey: "pokedex/shiny/211", silhouetteKey: "pokedex/silhouette/211")),
        PokedexSpeciesDefinition(nationalDexNumber: 212, generation: 2, slug: "scizor", name: "Scizor", genus: "Pincer Pokémon", description: "Its wings are not used for flying. They are flapped at high speed to adjust its body temperature.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/212", normalKey: "pokedex/normal/212", shinyKey: "pokedex/shiny/212", silhouetteKey: "pokedex/silhouette/212")),
        PokedexSpeciesDefinition(nationalDexNumber: 213, generation: 2, slug: "shuckle", name: "Shuckle", genus: "Mold Pokémon", description: "It stores BERRIES inside its shell. To avoid attacks, it hides beneath rocks and remains completely still.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/213", normalKey: "pokedex/normal/213", shinyKey: "pokedex/shiny/213", silhouetteKey: "pokedex/silhouette/213")),
        PokedexSpeciesDefinition(nationalDexNumber: 214, generation: 2, slug: "heracross", name: "Heracross", genus: "Single Horn Pokémon", description: "Usually docile, but if disturbed while sipping honey, it chases off the intruder with its horn.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/214", normalKey: "pokedex/normal/214", shinyKey: "pokedex/shiny/214", silhouetteKey: "pokedex/silhouette/214")),
        PokedexSpeciesDefinition(nationalDexNumber: 215, generation: 2, slug: "sneasel", name: "Sneasel", genus: "Sharp Claw Pokémon", description: "Vicious in nature, it drives PIDGEY from their nests and feasts on the eggs that are left behind.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/215", normalKey: "pokedex/normal/215", shinyKey: "pokedex/shiny/215", silhouetteKey: "pokedex/silhouette/215")),
        PokedexSpeciesDefinition(nationalDexNumber: 216, generation: 2, slug: "teddiursa", name: "Teddiursa", genus: "Little Bear Pokémon", description: "Before food becomes scarce in wintertime, its habit is to hoard food in many hidden locations.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/216", normalKey: "pokedex/normal/216", shinyKey: "pokedex/shiny/216", silhouetteKey: "pokedex/silhouette/216")),
        PokedexSpeciesDefinition(nationalDexNumber: 217, generation: 2, slug: "ursaring", name: "Ursaring", genus: "Hibernator Pokémon", description: "With its ability to distinguish any smell, it unfailingly finds all food buried deep underground.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/217", normalKey: "pokedex/normal/217", shinyKey: "pokedex/shiny/217", silhouetteKey: "pokedex/silhouette/217")),
        PokedexSpeciesDefinition(nationalDexNumber: 218, generation: 2, slug: "slugma", name: "Slugma", genus: "Lava Pokémon", description: "A common sight in volcanic areas, it slowly slithers around in a constant search for warm places.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/218", normalKey: "pokedex/normal/218", shinyKey: "pokedex/shiny/218", silhouetteKey: "pokedex/silhouette/218")),
        PokedexSpeciesDefinition(nationalDexNumber: 219, generation: 2, slug: "magcargo", name: "Magcargo", genus: "Lava Pokémon", description: "Its brittle shell occasionally spouts intense flames that circulate throughout its body.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/219", normalKey: "pokedex/normal/219", shinyKey: "pokedex/shiny/219", silhouetteKey: "pokedex/silhouette/219")),
        PokedexSpeciesDefinition(nationalDexNumber: 220, generation: 2, slug: "swinub", name: "Swinub", genus: "Pig Pokémon", description: "If it smells something enticing, it dashes off headlong to find the source of the aroma.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/220", normalKey: "pokedex/normal/220", shinyKey: "pokedex/shiny/220", silhouetteKey: "pokedex/silhouette/220")),
        PokedexSpeciesDefinition(nationalDexNumber: 221, generation: 2, slug: "piloswine", name: "Piloswine", genus: "Swine Pokémon", description: "If it charges at an enemy, the hairs on its back stand up straight. It is very sensitive to sound.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/221", normalKey: "pokedex/normal/221", shinyKey: "pokedex/shiny/221", silhouetteKey: "pokedex/silhouette/221")),
        PokedexSpeciesDefinition(nationalDexNumber: 222, generation: 2, slug: "corsola", name: "Corsola", genus: "Coral Pokémon", description: "In a south sea nation, the people live in communities that are built on groups of these Pokémon.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/222", normalKey: "pokedex/normal/222", shinyKey: "pokedex/shiny/222", silhouetteKey: "pokedex/silhouette/222")),
        PokedexSpeciesDefinition(nationalDexNumber: 223, generation: 2, slug: "remoraid", name: "Remoraid", genus: "Jet Pokémon", description: "Using its dorsal fin as a suction pad, it clings to a MANTINE’s underside to scavenge for leftovers.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/223", normalKey: "pokedex/normal/223", shinyKey: "pokedex/shiny/223", silhouetteKey: "pokedex/silhouette/223")),
        PokedexSpeciesDefinition(nationalDexNumber: 224, generation: 2, slug: "octillery", name: "Octillery", genus: "Jet Pokémon", description: "It instinctively sneaks into rocky holes. If it gets sleepy, it steals the nest of a fellow OCTILLERY.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/224", normalKey: "pokedex/normal/224", shinyKey: "pokedex/shiny/224", silhouetteKey: "pokedex/silhouette/224")),
        PokedexSpeciesDefinition(nationalDexNumber: 225, generation: 2, slug: "delibird", name: "Delibird", genus: "Delivery Pokémon", description: "It nests at the edge of sharp cliffs. It spends all day carrying food to its awaiting chicks.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/225", normalKey: "pokedex/normal/225", shinyKey: "pokedex/shiny/225", silhouetteKey: "pokedex/silhouette/225")),
        PokedexSpeciesDefinition(nationalDexNumber: 226, generation: 2, slug: "mantine", name: "Mantine", genus: "Kite Pokémon", description: "Swimming freely in open seas, it may fly out of the water and over the waves if it builds up enough speed.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/226", normalKey: "pokedex/normal/226", shinyKey: "pokedex/shiny/226", silhouetteKey: "pokedex/silhouette/226")),
        PokedexSpeciesDefinition(nationalDexNumber: 227, generation: 2, slug: "skarmory", name: "Skarmory", genus: "Armor Bird Pokémon", description: "After nesting in bramble bushes, the wings of its chicks grow hard from scratches by thorns.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/227", normalKey: "pokedex/normal/227", shinyKey: "pokedex/shiny/227", silhouetteKey: "pokedex/silhouette/227")),
        PokedexSpeciesDefinition(nationalDexNumber: 228, generation: 2, slug: "houndour", name: "Houndour", genus: "Dark Pokémon", description: "To corner prey, they check each other’s location using barks that only they can understand.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/228", normalKey: "pokedex/normal/228", shinyKey: "pokedex/shiny/228", silhouetteKey: "pokedex/silhouette/228")),
        PokedexSpeciesDefinition(nationalDexNumber: 229, generation: 2, slug: "houndoom", name: "Houndoom", genus: "Dark Pokémon", description: "Upon hearing its eerie howls, other Pokémon get the shivers and head straight back to their nests.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/229", normalKey: "pokedex/normal/229", shinyKey: "pokedex/shiny/229", silhouetteKey: "pokedex/silhouette/229")),
        PokedexSpeciesDefinition(nationalDexNumber: 230, generation: 2, slug: "kingdra", name: "Kingdra", genus: "Dragon Pokémon", description: "It sleeps deep on the ocean floor to build its energy. It is said to cause tornadoes as it wakes.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/230", normalKey: "pokedex/normal/230", shinyKey: "pokedex/shiny/230", silhouetteKey: "pokedex/silhouette/230")),
        PokedexSpeciesDefinition(nationalDexNumber: 231, generation: 2, slug: "phanpy", name: "Phanpy", genus: "Long Nose Pokémon", description: "As a sign of affection, it bumps with its snout. However, it is so strong, it may send you flying.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/231", normalKey: "pokedex/normal/231", shinyKey: "pokedex/shiny/231", silhouetteKey: "pokedex/silhouette/231")),
        PokedexSpeciesDefinition(nationalDexNumber: 232, generation: 2, slug: "donphan", name: "Donphan", genus: "Armor Pokémon", description: "The longer and bigger its tusks, the higher its rank in its herd. The tusks take a long time to grow.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/232", normalKey: "pokedex/normal/232", shinyKey: "pokedex/shiny/232", silhouetteKey: "pokedex/silhouette/232")),
        PokedexSpeciesDefinition(nationalDexNumber: 233, generation: 2, slug: "porygon2", name: "Porygon2", genus: "Virtual Pokémon", description: "Further research enhanced its abilities. Sometimes, it may exhibit motions that were not programmed.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/233", normalKey: "pokedex/normal/233", shinyKey: "pokedex/shiny/233", silhouetteKey: "pokedex/silhouette/233")),
        PokedexSpeciesDefinition(nationalDexNumber: 234, generation: 2, slug: "stantler", name: "Stantler", genus: "Big Horn Pokémon", description: "Those who stare at its antlers will gradually lose control of their senses and be unable to stand.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/234", normalKey: "pokedex/normal/234", shinyKey: "pokedex/shiny/234", silhouetteKey: "pokedex/silhouette/234")),
        PokedexSpeciesDefinition(nationalDexNumber: 235, generation: 2, slug: "smeargle", name: "Smeargle", genus: "Painter Pokémon", description: "Once it becomes an adult, it has a tendency to let its comrades plant footprints on its back.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/235", normalKey: "pokedex/normal/235", shinyKey: "pokedex/shiny/235", silhouetteKey: "pokedex/silhouette/235")),
        PokedexSpeciesDefinition(nationalDexNumber: 236, generation: 2, slug: "tyrogue", name: "Tyrogue", genus: "Scuffle Pokémon", description: "Even though it is small, it can’t be ignored because it will slug any handy target without warning.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/236", normalKey: "pokedex/normal/236", shinyKey: "pokedex/shiny/236", silhouetteKey: "pokedex/silhouette/236")),
        PokedexSpeciesDefinition(nationalDexNumber: 237, generation: 2, slug: "hitmontop", name: "Hitmontop", genus: "Handstand Pokémon", description: "It launches kicks while spinning. If it spins at high speed, it may bore its way into the ground.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/237", normalKey: "pokedex/normal/237", shinyKey: "pokedex/shiny/237", silhouetteKey: "pokedex/silhouette/237")),
        PokedexSpeciesDefinition(nationalDexNumber: 238, generation: 2, slug: "smoochum", name: "Smoochum", genus: "Kiss Pokémon", description: "It always rocks its head slowly backwards and forwards as if it is trying to kiss someone.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/238", normalKey: "pokedex/normal/238", shinyKey: "pokedex/shiny/238", silhouetteKey: "pokedex/silhouette/238")),
        PokedexSpeciesDefinition(nationalDexNumber: 239, generation: 2, slug: "elekid", name: "Elekid", genus: "Electric Pokémon", description: "Even in the most vicious storm, this Pokémon plays happily if thunder rumbles in the sky.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/239", normalKey: "pokedex/normal/239", shinyKey: "pokedex/shiny/239", silhouetteKey: "pokedex/silhouette/239")),
        PokedexSpeciesDefinition(nationalDexNumber: 240, generation: 2, slug: "magby", name: "Magby", genus: "Live Coal Pokémon", description: "It is found in volcanic craters. Its body heat exceeds 1,100 degrees Fahrenheit, so don’t underestimate it.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/240", normalKey: "pokedex/normal/240", shinyKey: "pokedex/shiny/240", silhouetteKey: "pokedex/silhouette/240")),
        PokedexSpeciesDefinition(nationalDexNumber: 241, generation: 2, slug: "miltank", name: "Miltank", genus: "Milk Cow Pokémon", description: "If it has just had a baby, the milk it produces contains much more nutrition than usual.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/241", normalKey: "pokedex/normal/241", shinyKey: "pokedex/shiny/241", silhouetteKey: "pokedex/silhouette/241")),
        PokedexSpeciesDefinition(nationalDexNumber: 242, generation: 2, slug: "blissey", name: "Blissey", genus: "Happiness Pokémon", description: "It has a very compassionate nature. If it sees a sick Pokémon, it will nurse the sufferer back to health.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/242", normalKey: "pokedex/normal/242", shinyKey: "pokedex/shiny/242", silhouetteKey: "pokedex/silhouette/242")),
        PokedexSpeciesDefinition(nationalDexNumber: 243, generation: 2, slug: "raikou", name: "Raikou", genus: "Thunder Pokémon", description: "This Pokémon races across the land while barking a cry that sounds like crashing thunder.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/243", normalKey: "pokedex/normal/243", shinyKey: "pokedex/shiny/243", silhouetteKey: "pokedex/silhouette/243")),
        PokedexSpeciesDefinition(nationalDexNumber: 244, generation: 2, slug: "entei", name: "Entei", genus: "Volcano Pokémon", description: "A Pokémon that races across the land. It is said that one is born every time a new volcano appears.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/244", normalKey: "pokedex/normal/244", shinyKey: "pokedex/shiny/244", silhouetteKey: "pokedex/silhouette/244")),
        PokedexSpeciesDefinition(nationalDexNumber: 245, generation: 2, slug: "suicune", name: "Suicune", genus: "Aurora Pokémon", description: "This Pokémon races across the land. It is said that north winds will somehow blow whenever it appears.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/245", normalKey: "pokedex/normal/245", shinyKey: "pokedex/shiny/245", silhouetteKey: "pokedex/silhouette/245")),
        PokedexSpeciesDefinition(nationalDexNumber: 246, generation: 2, slug: "larvitar", name: "Larvitar", genus: "Rock Skin Pokémon", description: "It is born deep underground. It can’t emerge until it has entirely consumed the soil around it.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/246", normalKey: "pokedex/normal/246", shinyKey: "pokedex/shiny/246", silhouetteKey: "pokedex/silhouette/246")),
        PokedexSpeciesDefinition(nationalDexNumber: 247, generation: 2, slug: "pupitar", name: "Pupitar", genus: "Hard Shell Pokémon", description: "Even sealed in its shell, it can move freely. Hard and fast, it has outstanding destructive power.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/247", normalKey: "pokedex/normal/247", shinyKey: "pokedex/shiny/247", silhouetteKey: "pokedex/silhouette/247")),
        PokedexSpeciesDefinition(nationalDexNumber: 248, generation: 2, slug: "tyranitar", name: "Tyranitar", genus: "Armor Pokémon", description: "Its body can’t be harmed by any sort of attack, so it is very eager to make challenges against enemies.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/248", normalKey: "pokedex/normal/248", shinyKey: "pokedex/shiny/248", silhouetteKey: "pokedex/silhouette/248")),
        PokedexSpeciesDefinition(nationalDexNumber: 249, generation: 2, slug: "lugia", name: "Lugia", genus: "Diving Pokémon", description: "It is said to be the guardian of the seas. It is rumored to have been seen on the night of a storm.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/249", normalKey: "pokedex/normal/249", shinyKey: "pokedex/shiny/249", silhouetteKey: "pokedex/silhouette/249")),
        PokedexSpeciesDefinition(nationalDexNumber: 250, generation: 2, slug: "ho-oh", name: "Ho-Oh", genus: "Rainbow Pokémon", description: "A legend says that its body glows in seven colors. A rainbow is said to form behind it when it flies.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/250", normalKey: "pokedex/normal/250", shinyKey: "pokedex/shiny/250", silhouetteKey: "pokedex/silhouette/250")),
        PokedexSpeciesDefinition(nationalDexNumber: 251, generation: 2, slug: "celebi", name: "Celebi", genus: "Time Travel Pokémon", description: "When CELEBI disappears deep in a forest, it is said to leave behind an egg it brought from the future.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/251", normalKey: "pokedex/normal/251", shinyKey: "pokedex/shiny/251", silhouetteKey: "pokedex/silhouette/251")),
        PokedexSpeciesDefinition(nationalDexNumber: 252, generation: 3, slug: "treecko", name: "Treecko", genus: "Wood Gecko Pokémon", description: "It quickly scales even vertical walls. It senses humidity with its tail to predict the next day’s weather.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/252", normalKey: "pokedex/normal/252", shinyKey: "pokedex/shiny/252", silhouetteKey: "pokedex/silhouette/252")),
        PokedexSpeciesDefinition(nationalDexNumber: 253, generation: 3, slug: "grovyle", name: "Grovyle", genus: "Wood Gecko Pokémon", description: "Its strongly developed thigh muscles give it astounding agility and jumping performance.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/253", normalKey: "pokedex/normal/253", shinyKey: "pokedex/shiny/253", silhouetteKey: "pokedex/silhouette/253")),
        PokedexSpeciesDefinition(nationalDexNumber: 254, generation: 3, slug: "sceptile", name: "Sceptile", genus: "Forest Pokémon", description: "The leaves on its forelegs are as sharp as swords. It agilely leaps about the branches of trees to strike.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/254", normalKey: "pokedex/normal/254", shinyKey: "pokedex/shiny/254", silhouetteKey: "pokedex/silhouette/254")),
        PokedexSpeciesDefinition(nationalDexNumber: 255, generation: 3, slug: "torchic", name: "Torchic", genus: "Chick Pokémon", description: "It has a flame sac inside its belly that perpetually burns. It feels warm if it is hugged.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/255", normalKey: "pokedex/normal/255", shinyKey: "pokedex/shiny/255", silhouetteKey: "pokedex/silhouette/255")),
        PokedexSpeciesDefinition(nationalDexNumber: 256, generation: 3, slug: "combusken", name: "Combusken", genus: "Young Fowl Pokémon", description: "It boosts its concentration by emitting harsh cries. Its kicks have outstanding destructive power.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/256", normalKey: "pokedex/normal/256", shinyKey: "pokedex/shiny/256", silhouetteKey: "pokedex/silhouette/256")),
        PokedexSpeciesDefinition(nationalDexNumber: 257, generation: 3, slug: "blaziken", name: "Blaziken", genus: "Blaze Pokémon", description: "When facing a tough foe, it looses flames from its wrists. Its powerful legs let it jump clear over buildings.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/257", normalKey: "pokedex/normal/257", shinyKey: "pokedex/shiny/257", silhouetteKey: "pokedex/silhouette/257")),
        PokedexSpeciesDefinition(nationalDexNumber: 258, generation: 3, slug: "mudkip", name: "Mudkip", genus: "Mud Fish Pokémon", description: "Its large tail fin propels it through water with powerful acceleration. It is strong in spite of its size.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/258", normalKey: "pokedex/normal/258", shinyKey: "pokedex/shiny/258", silhouetteKey: "pokedex/silhouette/258")),
        PokedexSpeciesDefinition(nationalDexNumber: 259, generation: 3, slug: "marshtomp", name: "Marshtomp", genus: "Mud Fish Pokémon", description: "It is at its best when on muddy ground with poor footing. It quickly overwhelms foes struggling in mud.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/259", normalKey: "pokedex/normal/259", shinyKey: "pokedex/shiny/259", silhouetteKey: "pokedex/silhouette/259")),
        PokedexSpeciesDefinition(nationalDexNumber: 260, generation: 3, slug: "swampert", name: "Swampert", genus: "Mud Fish Pokémon", description: "Its arms are rock-hard. With one swing, they can batter down its foe. It makes its nest on beautiful beaches.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/260", normalKey: "pokedex/normal/260", shinyKey: "pokedex/shiny/260", silhouetteKey: "pokedex/silhouette/260")),
        PokedexSpeciesDefinition(nationalDexNumber: 261, generation: 3, slug: "poochyena", name: "Poochyena", genus: "Bite Pokémon", description: "It has a very tenacious nature. Its acute sense of smell lets it chase a chosen prey without ever losing track.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/261", normalKey: "pokedex/normal/261", shinyKey: "pokedex/shiny/261", silhouetteKey: "pokedex/silhouette/261")),
        PokedexSpeciesDefinition(nationalDexNumber: 262, generation: 3, slug: "mightyena", name: "Mightyena", genus: "Bite Pokémon", description: "It will always obey the commands of a skilled TRAINER. Its behavior arises from its living in packs in ancient times.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/262", normalKey: "pokedex/normal/262", shinyKey: "pokedex/shiny/262", silhouetteKey: "pokedex/silhouette/262")),
        PokedexSpeciesDefinition(nationalDexNumber: 263, generation: 3, slug: "zigzagoon", name: "Zigzagoon", genus: "Tiny Raccoon Pokémon", description: "A Pokémon with abundant curiosity. It shows an interest in everything, so it always zigs and zags.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/263", normalKey: "pokedex/normal/263", shinyKey: "pokedex/shiny/263", silhouetteKey: "pokedex/silhouette/263")),
        PokedexSpeciesDefinition(nationalDexNumber: 264, generation: 3, slug: "linoone", name: "Linoone", genus: "Rushing Pokémon", description: "When running in a straight line, it can top 60 miles per hour. However, it has a tough time with curved roads.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/264", normalKey: "pokedex/normal/264", shinyKey: "pokedex/shiny/264", silhouetteKey: "pokedex/silhouette/264")),
        PokedexSpeciesDefinition(nationalDexNumber: 265, generation: 3, slug: "wurmple", name: "Wurmple", genus: "Worm Pokémon", description: "It lives amidst tall grass and in forests. When attacked, it resists by pointing its venomous spikes at the foe.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/265", normalKey: "pokedex/normal/265", shinyKey: "pokedex/shiny/265", silhouetteKey: "pokedex/silhouette/265")),
        PokedexSpeciesDefinition(nationalDexNumber: 266, generation: 3, slug: "silcoon", name: "Silcoon", genus: "Cocoon Pokémon", description: "It conserves its energy by moving as little as possible. It awaits evolution while drinking only a little rainwater.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/266", normalKey: "pokedex/normal/266", shinyKey: "pokedex/shiny/266", silhouetteKey: "pokedex/silhouette/266")),
        PokedexSpeciesDefinition(nationalDexNumber: 267, generation: 3, slug: "beautifly", name: "Beautifly", genus: "Butterfly Pokémon", description: "Despite its appearance, it has an aggressive nature. It attacks by jabbing with its long, thin mouth.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/267", normalKey: "pokedex/normal/267", shinyKey: "pokedex/shiny/267", silhouetteKey: "pokedex/silhouette/267")),
        PokedexSpeciesDefinition(nationalDexNumber: 268, generation: 3, slug: "cascoon", name: "Cascoon", genus: "Cocoon Pokémon", description: "Its body, which is made of soft silk, hardens over time. When cracks appear, evolution is near.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/268", normalKey: "pokedex/normal/268", shinyKey: "pokedex/shiny/268", silhouetteKey: "pokedex/silhouette/268")),
        PokedexSpeciesDefinition(nationalDexNumber: 269, generation: 3, slug: "dustox", name: "Dustox", genus: "Poison Moth Pokémon", description: "It scatters horribly toxic dust when it senses danger. They tend to gather in the glow of streetlamps at night.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/269", normalKey: "pokedex/normal/269", shinyKey: "pokedex/shiny/269", silhouetteKey: "pokedex/silhouette/269")),
        PokedexSpeciesDefinition(nationalDexNumber: 270, generation: 3, slug: "lotad", name: "Lotad", genus: "Water Weed Pokémon", description: "It searches about for clean water. If it does not drink water for too long, the leaf on its head wilts.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/270", normalKey: "pokedex/normal/270", shinyKey: "pokedex/shiny/270", silhouetteKey: "pokedex/silhouette/270")),
        PokedexSpeciesDefinition(nationalDexNumber: 271, generation: 3, slug: "lombre", name: "Lombre", genus: "Jolly Pokémon", description: "It lives at the water’s edge where it is sunny. It sleeps on a bed of water grass by day and becomes active at night.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/271", normalKey: "pokedex/normal/271", shinyKey: "pokedex/shiny/271", silhouetteKey: "pokedex/silhouette/271")),
        PokedexSpeciesDefinition(nationalDexNumber: 272, generation: 3, slug: "ludicolo", name: "Ludicolo", genus: "Carefree Pokémon", description: "The rhythm of bright, festive music activates LUDICOLO’s cells, making it more powerful.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/272", normalKey: "pokedex/normal/272", shinyKey: "pokedex/shiny/272", silhouetteKey: "pokedex/silhouette/272")),
        PokedexSpeciesDefinition(nationalDexNumber: 273, generation: 3, slug: "seedot", name: "Seedot", genus: "Acorn Pokémon", description: "If it remains still, it becomes impossible to distinguish from real nuts. It delights in surprising foraging PIDGEY.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/273", normalKey: "pokedex/normal/273", shinyKey: "pokedex/shiny/273", silhouetteKey: "pokedex/silhouette/273")),
        PokedexSpeciesDefinition(nationalDexNumber: 274, generation: 3, slug: "nuzleaf", name: "Nuzleaf", genus: "Wily Pokémon", description: "They live in holes bored in large trees. The sound of NUZLEAF’s grass flute fills listeners with dread.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/274", normalKey: "pokedex/normal/274", shinyKey: "pokedex/shiny/274", silhouetteKey: "pokedex/silhouette/274")),
        PokedexSpeciesDefinition(nationalDexNumber: 275, generation: 3, slug: "shiftry", name: "Shiftry", genus: "Wicked Pokémon", description: "A Pokémon that was feared as a forest guardian. It can read the foe’s mind and take preemptive action.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/275", normalKey: "pokedex/normal/275", shinyKey: "pokedex/shiny/275", silhouetteKey: "pokedex/silhouette/275")),
        PokedexSpeciesDefinition(nationalDexNumber: 276, generation: 3, slug: "taillow", name: "Taillow", genus: "Tiny Swallow Pokémon", description: "It dislikes cold seasons. They migrate to other lands in search of warmth, flying over 180 miles a day.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/276", normalKey: "pokedex/normal/276", shinyKey: "pokedex/shiny/276", silhouetteKey: "pokedex/silhouette/276")),
        PokedexSpeciesDefinition(nationalDexNumber: 277, generation: 3, slug: "swellow", name: "Swellow", genus: "Swallow Pokémon", description: "If its two tail feathers are standing at attention, it is proof of good health. It soars elegantly in the sky.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/277", normalKey: "pokedex/normal/277", shinyKey: "pokedex/shiny/277", silhouetteKey: "pokedex/silhouette/277")),
        PokedexSpeciesDefinition(nationalDexNumber: 278, generation: 3, slug: "wingull", name: "Wingull", genus: "Seagull Pokémon", description: "It rides upon ocean winds as if it were a glider. In the winter, it hides food around its nest.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/278", normalKey: "pokedex/normal/278", shinyKey: "pokedex/shiny/278", silhouetteKey: "pokedex/silhouette/278")),
        PokedexSpeciesDefinition(nationalDexNumber: 279, generation: 3, slug: "pelipper", name: "Pelipper", genus: "Water Bird Pokémon", description: "It is a flying transporter that carries small Pokémon in its beak. It bobs on the waves to rest its wings.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/279", normalKey: "pokedex/normal/279", shinyKey: "pokedex/shiny/279", silhouetteKey: "pokedex/silhouette/279")),
        PokedexSpeciesDefinition(nationalDexNumber: 280, generation: 3, slug: "ralts", name: "Ralts", genus: "Feeling Pokémon", description: "It is highly attuned to the emotions of people and Pokémon. It hides if it senses hostility.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/280", normalKey: "pokedex/normal/280", shinyKey: "pokedex/shiny/280", silhouetteKey: "pokedex/silhouette/280")),
        PokedexSpeciesDefinition(nationalDexNumber: 281, generation: 3, slug: "kirlia", name: "Kirlia", genus: "Emotion Pokémon", description: "The cheerful spirit of its TRAINER gives it energy for its psychokinetic power. It spins and dances when happy.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/281", normalKey: "pokedex/normal/281", shinyKey: "pokedex/shiny/281", silhouetteKey: "pokedex/silhouette/281")),
        PokedexSpeciesDefinition(nationalDexNumber: 282, generation: 3, slug: "gardevoir", name: "Gardevoir", genus: "Embrace Pokémon", description: "It has the power to predict the future. Its power peaks when it is protecting its TRAINER.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/282", normalKey: "pokedex/normal/282", shinyKey: "pokedex/shiny/282", silhouetteKey: "pokedex/silhouette/282")),
        PokedexSpeciesDefinition(nationalDexNumber: 283, generation: 3, slug: "surskit", name: "Surskit", genus: "Pond Skater Pokémon", description: "They usually live on ponds, but after an evening shower, they may appear on puddles in towns.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/283", normalKey: "pokedex/normal/283", shinyKey: "pokedex/shiny/283", silhouetteKey: "pokedex/silhouette/283")),
        PokedexSpeciesDefinition(nationalDexNumber: 284, generation: 3, slug: "masquerain", name: "Masquerain", genus: "Eyeball Pokémon", description: "The antennae have distinctive patterns that look like eyes. When it rains, they grow heavy, making flight impossible.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/284", normalKey: "pokedex/normal/284", shinyKey: "pokedex/shiny/284", silhouetteKey: "pokedex/silhouette/284")),
        PokedexSpeciesDefinition(nationalDexNumber: 285, generation: 3, slug: "shroomish", name: "Shroomish", genus: "Mushroom Pokémon", description: "It prefers damp places. By day it remains still in the forest shade. It releases toxic powder from its head.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/285", normalKey: "pokedex/normal/285", shinyKey: "pokedex/shiny/285", silhouetteKey: "pokedex/silhouette/285")),
        PokedexSpeciesDefinition(nationalDexNumber: 286, generation: 3, slug: "breloom", name: "Breloom", genus: "Mushroom Pokémon", description: "The seeds on its tail are made of toxic spores. It knocks out foes with quick, virtually invisible punches.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/286", normalKey: "pokedex/normal/286", shinyKey: "pokedex/shiny/286", silhouetteKey: "pokedex/silhouette/286")),
        PokedexSpeciesDefinition(nationalDexNumber: 287, generation: 3, slug: "slakoth", name: "Slakoth", genus: "Slacker Pokémon", description: "It sleeps for 20 hours every day. Making drowsy those that see it is one of its abilities.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/287", normalKey: "pokedex/normal/287", shinyKey: "pokedex/shiny/287", silhouetteKey: "pokedex/silhouette/287")),
        PokedexSpeciesDefinition(nationalDexNumber: 288, generation: 3, slug: "vigoroth", name: "Vigoroth", genus: "Wild Monkey Pokémon", description: "It is always hungry because it won’t stop rampaging. Even while it is eating, it can’t keep still.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/288", normalKey: "pokedex/normal/288", shinyKey: "pokedex/shiny/288", silhouetteKey: "pokedex/silhouette/288")),
        PokedexSpeciesDefinition(nationalDexNumber: 289, generation: 3, slug: "slaking", name: "Slaking", genus: "Lazy Pokémon", description: "It is the world’s most slothful Pokémon. However, it can exert horrifying power by releasing pent-up energy all at once.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/289", normalKey: "pokedex/normal/289", shinyKey: "pokedex/shiny/289", silhouetteKey: "pokedex/silhouette/289")),
        PokedexSpeciesDefinition(nationalDexNumber: 290, generation: 3, slug: "nincada", name: "Nincada", genus: "Trainee Pokémon", description: "Because it lived almost entirely underground, it is nearly blind. It uses its antennae instead.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/290", normalKey: "pokedex/normal/290", shinyKey: "pokedex/shiny/290", silhouetteKey: "pokedex/silhouette/290")),
        PokedexSpeciesDefinition(nationalDexNumber: 291, generation: 3, slug: "ninjask", name: "Ninjask", genus: "Ninja Pokémon", description: "This Pokémon is so quick, it is said to be able to avoid any attack. It loves to feed on tree sap.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/291", normalKey: "pokedex/normal/291", shinyKey: "pokedex/shiny/291", silhouetteKey: "pokedex/silhouette/291")),
        PokedexSpeciesDefinition(nationalDexNumber: 292, generation: 3, slug: "shedinja", name: "Shedinja", genus: "Shed Pokémon", description: "A most peculiar Pokémon that somehow appears in a POKé BALL when a NINCADA evolves.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/292", normalKey: "pokedex/normal/292", shinyKey: "pokedex/shiny/292", silhouetteKey: "pokedex/silhouette/292")),
        PokedexSpeciesDefinition(nationalDexNumber: 293, generation: 3, slug: "whismur", name: "Whismur", genus: "Whisper Pokémon", description: "It usually murmurs, but starts crying loudly if it senses danger. It stops when its ear covers are shut.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/293", normalKey: "pokedex/normal/293", shinyKey: "pokedex/shiny/293", silhouetteKey: "pokedex/silhouette/293")),
        PokedexSpeciesDefinition(nationalDexNumber: 294, generation: 3, slug: "loudred", name: "Loudred", genus: "Big Voice Pokémon", description: "When it stamps its feet and bellows, it generates ultrasonic waves that can blow apart a house.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/294", normalKey: "pokedex/normal/294", shinyKey: "pokedex/shiny/294", silhouetteKey: "pokedex/silhouette/294")),
        PokedexSpeciesDefinition(nationalDexNumber: 295, generation: 3, slug: "exploud", name: "Exploud", genus: "Loud Noise Pokémon", description: "It emits a variety of sounds from the holes all over its body. Its loud cries can be heard from over six miles away.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/295", normalKey: "pokedex/normal/295", shinyKey: "pokedex/shiny/295", silhouetteKey: "pokedex/silhouette/295")),
        PokedexSpeciesDefinition(nationalDexNumber: 296, generation: 3, slug: "makuhita", name: "Makuhita", genus: "Guts Pokémon", description: "It grows stronger by enduring harsh training. It is a gutsy Pokémon that can withstand any attack.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/296", normalKey: "pokedex/normal/296", shinyKey: "pokedex/shiny/296", silhouetteKey: "pokedex/silhouette/296")),
        PokedexSpeciesDefinition(nationalDexNumber: 297, generation: 3, slug: "hariyama", name: "Hariyama", genus: "Arm Thrust Pokémon", description: "It stomps on the ground to build power. It can send a 10-ton truck flying with a straight-arm punch.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/297", normalKey: "pokedex/normal/297", shinyKey: "pokedex/shiny/297", silhouetteKey: "pokedex/silhouette/297")),
        PokedexSpeciesDefinition(nationalDexNumber: 298, generation: 3, slug: "azurill", name: "Azurill", genus: "Polka Dot Pokémon", description: "It battles by flinging around its tail, which is bigger than its body. The tail is a flotation device in water.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/298", normalKey: "pokedex/normal/298", shinyKey: "pokedex/shiny/298", silhouetteKey: "pokedex/silhouette/298")),
        PokedexSpeciesDefinition(nationalDexNumber: 299, generation: 3, slug: "nosepass", name: "Nosepass", genus: "Compass Pokémon", description: "Its magnetic nose consistently faces north. Travelers check NOSEPASS to get their bearings.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/299", normalKey: "pokedex/normal/299", shinyKey: "pokedex/shiny/299", silhouetteKey: "pokedex/silhouette/299")),
        PokedexSpeciesDefinition(nationalDexNumber: 300, generation: 3, slug: "skitty", name: "Skitty", genus: "Kitten Pokémon", description: "It is said to be difficult to earn its trust. However, it is extremely popular for its cute looks and behavior.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/300", normalKey: "pokedex/normal/300", shinyKey: "pokedex/shiny/300", silhouetteKey: "pokedex/silhouette/300")),
        PokedexSpeciesDefinition(nationalDexNumber: 301, generation: 3, slug: "delcatty", name: "Delcatty", genus: "Prim Pokémon", description: "The favorite of trend-conscious female TRAINERS, they are used in competition for their style and fur.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/301", normalKey: "pokedex/normal/301", shinyKey: "pokedex/shiny/301", silhouetteKey: "pokedex/silhouette/301")),
        PokedexSpeciesDefinition(nationalDexNumber: 302, generation: 3, slug: "sableye", name: "Sableye", genus: "Darkness Pokémon", description: "It feeds on gemstone crystals. In darkness, its eyes sparkle with the glitter of jewels.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/302", normalKey: "pokedex/normal/302", shinyKey: "pokedex/shiny/302", silhouetteKey: "pokedex/silhouette/302")),
        PokedexSpeciesDefinition(nationalDexNumber: 303, generation: 3, slug: "mawile", name: "Mawile", genus: "Deceiver Pokémon", description: "It uses its docile-looking face to lull foes into complacency, then bites with its huge, relentless jaws.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/303", normalKey: "pokedex/normal/303", shinyKey: "pokedex/shiny/303", silhouetteKey: "pokedex/silhouette/303")),
        PokedexSpeciesDefinition(nationalDexNumber: 304, generation: 3, slug: "aron", name: "Aron", genus: "Iron Armor Pokémon", description: "It eats iron to build its steel body. It is a pest that descends from mountains to eat bridges and train tracks.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/304", normalKey: "pokedex/normal/304", shinyKey: "pokedex/shiny/304", silhouetteKey: "pokedex/silhouette/304")),
        PokedexSpeciesDefinition(nationalDexNumber: 305, generation: 3, slug: "lairon", name: "Lairon", genus: "Iron Armor Pokémon", description: "It habitually shows off its strength with the size of sparks it creates by ramming its steel body into boulders.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/305", normalKey: "pokedex/normal/305", shinyKey: "pokedex/shiny/305", silhouetteKey: "pokedex/silhouette/305")),
        PokedexSpeciesDefinition(nationalDexNumber: 306, generation: 3, slug: "aggron", name: "Aggron", genus: "Iron Armor Pokémon", description: "It claims a large mountain as its sole territory. It mercilessly thrashes those that violate its space.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/306", normalKey: "pokedex/normal/306", shinyKey: "pokedex/shiny/306", silhouetteKey: "pokedex/silhouette/306")),
        PokedexSpeciesDefinition(nationalDexNumber: 307, generation: 3, slug: "meditite", name: "Meditite", genus: "Meditate Pokémon", description: "It never skips its daily yoga training. It heightens its inner strength through meditation.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/307", normalKey: "pokedex/normal/307", shinyKey: "pokedex/shiny/307", silhouetteKey: "pokedex/silhouette/307")),
        PokedexSpeciesDefinition(nationalDexNumber: 308, generation: 3, slug: "medicham", name: "Medicham", genus: "Meditate Pokémon", description: "It elegantly avoids attacks with dance- like steps, then launches a devastating blow in the same motion.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/308", normalKey: "pokedex/normal/308", shinyKey: "pokedex/shiny/308", silhouetteKey: "pokedex/silhouette/308")),
        PokedexSpeciesDefinition(nationalDexNumber: 309, generation: 3, slug: "electrike", name: "Electrike", genus: "Lightning Pokémon", description: "It stores static electricity in its fur for discharging. It gives off sparks if a storm approaches.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/309", normalKey: "pokedex/normal/309", shinyKey: "pokedex/shiny/309", silhouetteKey: "pokedex/silhouette/309")),
        PokedexSpeciesDefinition(nationalDexNumber: 310, generation: 3, slug: "manectric", name: "Manectric", genus: "Discharge Pokémon", description: "It rarely appears before people. It is said to nest where lightning has fallen.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/310", normalKey: "pokedex/normal/310", shinyKey: "pokedex/shiny/310", silhouetteKey: "pokedex/silhouette/310")),
        PokedexSpeciesDefinition(nationalDexNumber: 311, generation: 3, slug: "plusle", name: "Plusle", genus: "Cheering Pokémon", description: "It cheers on partners while scattering sparks from its body. It climbs telephone poles to absorb electricity.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/311", normalKey: "pokedex/normal/311", shinyKey: "pokedex/shiny/311", silhouetteKey: "pokedex/silhouette/311")),
        PokedexSpeciesDefinition(nationalDexNumber: 312, generation: 3, slug: "minun", name: "Minun", genus: "Cheering Pokémon", description: "Its dislike of water makes it take shelter under the eaves of houses in rain. It uses pom-poms made of sparks for cheering.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/312", normalKey: "pokedex/normal/312", shinyKey: "pokedex/shiny/312", silhouetteKey: "pokedex/silhouette/312")),
        PokedexSpeciesDefinition(nationalDexNumber: 313, generation: 3, slug: "volbeat", name: "Volbeat", genus: "Firefly Pokémon", description: "It lives around clean ponds. At night, its rear lights up. It converses with others by flashing its light.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/313", normalKey: "pokedex/normal/313", shinyKey: "pokedex/shiny/313", silhouetteKey: "pokedex/silhouette/313")),
        PokedexSpeciesDefinition(nationalDexNumber: 314, generation: 3, slug: "illumise", name: "Illumise", genus: "Firefly Pokémon", description: "It guides VOLBEAT to draw signs in night skies. There are scientists that study the patterns it creates.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/314", normalKey: "pokedex/normal/314", shinyKey: "pokedex/shiny/314", silhouetteKey: "pokedex/silhouette/314")),
        PokedexSpeciesDefinition(nationalDexNumber: 315, generation: 3, slug: "roselia", name: "Roselia", genus: "Thorn Pokémon", description: "Its flowers give off a relaxing fragrance. The stronger its aroma, the healthier the ROSELIA is.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/315", normalKey: "pokedex/normal/315", shinyKey: "pokedex/shiny/315", silhouetteKey: "pokedex/silhouette/315")),
        PokedexSpeciesDefinition(nationalDexNumber: 316, generation: 3, slug: "gulpin", name: "Gulpin", genus: "Stomach Pokémon", description: "There is nothing its stomach can’t digest. While it is digesting, vile, overpowering gases are expelled.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/316", normalKey: "pokedex/normal/316", shinyKey: "pokedex/shiny/316", silhouetteKey: "pokedex/silhouette/316")),
        PokedexSpeciesDefinition(nationalDexNumber: 317, generation: 3, slug: "swalot", name: "Swalot", genus: "Poison Bag Pokémon", description: "It can swallow a tire whole in one gulp. It secretes a horribly toxic fluid from the pores on its body.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/317", normalKey: "pokedex/normal/317", shinyKey: "pokedex/shiny/317", silhouetteKey: "pokedex/silhouette/317")),
        PokedexSpeciesDefinition(nationalDexNumber: 318, generation: 3, slug: "carvanha", name: "Carvanha", genus: "Savage Pokémon", description: "It lives in massive rivers that course through jungles. It swarms prey that enter its territory.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/318", normalKey: "pokedex/normal/318", shinyKey: "pokedex/shiny/318", silhouetteKey: "pokedex/silhouette/318")),
        PokedexSpeciesDefinition(nationalDexNumber: 319, generation: 3, slug: "sharpedo", name: "Sharpedo", genus: "Brutal Pokémon", description: "The ruffian of the seas, it has fangs that crunch through iron. It swims by jetting water from its rear.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/319", normalKey: "pokedex/normal/319", shinyKey: "pokedex/shiny/319", silhouetteKey: "pokedex/silhouette/319")),
        PokedexSpeciesDefinition(nationalDexNumber: 320, generation: 3, slug: "wailmer", name: "Wailmer", genus: "Ball Whale Pokémon", description: "When it sucks in a large volume of seawater, it becomes like a big, bouncy ball. It eats a ton of food daily.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/320", normalKey: "pokedex/normal/320", shinyKey: "pokedex/shiny/320", silhouetteKey: "pokedex/silhouette/320")),
        PokedexSpeciesDefinition(nationalDexNumber: 321, generation: 3, slug: "wailord", name: "Wailord", genus: "Float Whale Pokémon", description: "It is among the largest of all Pokémon. It herds prey in a pack then swallows the massed prey in one gulp.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/321", normalKey: "pokedex/normal/321", shinyKey: "pokedex/shiny/321", silhouetteKey: "pokedex/silhouette/321")),
        PokedexSpeciesDefinition(nationalDexNumber: 322, generation: 3, slug: "numel", name: "Numel", genus: "Numb Pokémon", description: "Magma of almost 2,200 degrees Fahrenheit courses through its body. When it grows cold, the magma hardens and slows it.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/322", normalKey: "pokedex/normal/322", shinyKey: "pokedex/shiny/322", silhouetteKey: "pokedex/silhouette/322")),
        PokedexSpeciesDefinition(nationalDexNumber: 323, generation: 3, slug: "camerupt", name: "Camerupt", genus: "Eruption Pokémon", description: "If angered, the humps on its back erupt in a shower of molten lava. It lives in the craters of volcanoes.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/323", normalKey: "pokedex/normal/323", shinyKey: "pokedex/shiny/323", silhouetteKey: "pokedex/silhouette/323")),
        PokedexSpeciesDefinition(nationalDexNumber: 324, generation: 3, slug: "torkoal", name: "Torkoal", genus: "Coal Pokémon", description: "It burns coal inside its shell. If it is attacked, it belches thick, black smoke and flees.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/324", normalKey: "pokedex/normal/324", shinyKey: "pokedex/shiny/324", silhouetteKey: "pokedex/silhouette/324")),
        PokedexSpeciesDefinition(nationalDexNumber: 325, generation: 3, slug: "spoink", name: "Spoink", genus: "Bounce Pokémon", description: "It apparently dies if it stops bouncing about. It carries a pearl from CLAMPERL on its head.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/325", normalKey: "pokedex/normal/325", shinyKey: "pokedex/shiny/325", silhouetteKey: "pokedex/silhouette/325")),
        PokedexSpeciesDefinition(nationalDexNumber: 326, generation: 3, slug: "grumpig", name: "Grumpig", genus: "Manipulate Pokémon", description: "It can gain control over foes by doing odd dance steps. The black pearls on its forehead are precious gems.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/326", normalKey: "pokedex/normal/326", shinyKey: "pokedex/shiny/326", silhouetteKey: "pokedex/silhouette/326")),
        PokedexSpeciesDefinition(nationalDexNumber: 327, generation: 3, slug: "spinda", name: "Spinda", genus: "Spot Panda Pokémon", description: "No two SPINDA are said to have identical patterns. It confuses foes with its stumbling motions.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/327", normalKey: "pokedex/normal/327", shinyKey: "pokedex/shiny/327", silhouetteKey: "pokedex/silhouette/327")),
        PokedexSpeciesDefinition(nationalDexNumber: 328, generation: 3, slug: "trapinch", name: "Trapinch", genus: "Ant Pit Pokémon", description: "It lives in arid deserts. It makes a sloping pit trap in sand where it patiently awaits prey.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/328", normalKey: "pokedex/normal/328", shinyKey: "pokedex/shiny/328", silhouetteKey: "pokedex/silhouette/328")),
        PokedexSpeciesDefinition(nationalDexNumber: 329, generation: 3, slug: "vibrava", name: "Vibrava", genus: "Vibration Pokémon", description: "It generates ultrasonic waves by violently flapping its wings. After making its prey faint, it melts the prey with acid.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/329", normalKey: "pokedex/normal/329", shinyKey: "pokedex/shiny/329", silhouetteKey: "pokedex/silhouette/329")),
        PokedexSpeciesDefinition(nationalDexNumber: 330, generation: 3, slug: "flygon", name: "Flygon", genus: "Mystic Pokémon", description: "It hides itself by kicking up desert sand with its wings. Red covers shield its eyes from sand.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/330", normalKey: "pokedex/normal/330", shinyKey: "pokedex/shiny/330", silhouetteKey: "pokedex/silhouette/330")),
        PokedexSpeciesDefinition(nationalDexNumber: 331, generation: 3, slug: "cacnea", name: "Cacnea", genus: "Cactus Pokémon", description: "It prefers harsh environments such as deserts. It can survive for 30 days on water stored in its body.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/331", normalKey: "pokedex/normal/331", shinyKey: "pokedex/shiny/331", silhouetteKey: "pokedex/silhouette/331")),
        PokedexSpeciesDefinition(nationalDexNumber: 332, generation: 3, slug: "cacturne", name: "Cacturne", genus: "Scarecrow Pokémon", description: "It lives in deserts. It becomes active at night when it hunts for prey exhausted from the desert’s heat.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/332", normalKey: "pokedex/normal/332", shinyKey: "pokedex/shiny/332", silhouetteKey: "pokedex/silhouette/332")),
        PokedexSpeciesDefinition(nationalDexNumber: 333, generation: 3, slug: "swablu", name: "Swablu", genus: "Cotton Bird Pokémon", description: "It constantly grooms its cotton-like wings. It takes a shower to clean itself if it becomes dirty.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/333", normalKey: "pokedex/normal/333", shinyKey: "pokedex/shiny/333", silhouetteKey: "pokedex/silhouette/333")),
        PokedexSpeciesDefinition(nationalDexNumber: 334, generation: 3, slug: "altaria", name: "Altaria", genus: "Humming Pokémon", description: "If you hear a beautiful melody trilling deep among mountains far from people, it is ALTARIA’s humming.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/334", normalKey: "pokedex/normal/334", shinyKey: "pokedex/shiny/334", silhouetteKey: "pokedex/silhouette/334")),
        PokedexSpeciesDefinition(nationalDexNumber: 335, generation: 3, slug: "zangoose", name: "Zangoose", genus: "Cat Ferret Pokémon", description: "If it comes across a SEVIPER, its fur bristles and it assumes its battle pose. Its sharp claws are its best weapon.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/335", normalKey: "pokedex/normal/335", shinyKey: "pokedex/shiny/335", silhouetteKey: "pokedex/silhouette/335")),
        PokedexSpeciesDefinition(nationalDexNumber: 336, generation: 3, slug: "seviper", name: "Seviper", genus: "Fang Snake Pokémon", description: "It sharpens its swordlike tail on hard rocks. It hides in tall grass and strikes unwary prey with venomous fangs.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/336", normalKey: "pokedex/normal/336", shinyKey: "pokedex/shiny/336", silhouetteKey: "pokedex/silhouette/336")),
        PokedexSpeciesDefinition(nationalDexNumber: 337, generation: 3, slug: "lunatone", name: "Lunatone", genus: "Meteorite Pokémon", description: "Its health ebbs and flows with the lunar cycle. It brims with power when exposed to the light of the full moon.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/337", normalKey: "pokedex/normal/337", shinyKey: "pokedex/shiny/337", silhouetteKey: "pokedex/silhouette/337")),
        PokedexSpeciesDefinition(nationalDexNumber: 338, generation: 3, slug: "solrock", name: "Solrock", genus: "Meteorite Pokémon", description: "It absorbs solar energy during the day. Always expressionless, it can sense what its foe is thinking.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/338", normalKey: "pokedex/normal/338", shinyKey: "pokedex/shiny/338", silhouetteKey: "pokedex/silhouette/338")),
        PokedexSpeciesDefinition(nationalDexNumber: 339, generation: 3, slug: "barboach", name: "Barboach", genus: "Whiskers Pokémon", description: "It probes muddy riverbeds with its two long whiskers. A slimy film protects its body.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/339", normalKey: "pokedex/normal/339", shinyKey: "pokedex/shiny/339", silhouetteKey: "pokedex/silhouette/339")),
        PokedexSpeciesDefinition(nationalDexNumber: 340, generation: 3, slug: "whiscash", name: "Whiscash", genus: "Whiskers Pokémon", description: "It makes its nest at the bottom of swamps. It will eat anything - if it is alive, WHISCASH will eat it.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/340", normalKey: "pokedex/normal/340", shinyKey: "pokedex/shiny/340", silhouetteKey: "pokedex/silhouette/340")),
        PokedexSpeciesDefinition(nationalDexNumber: 341, generation: 3, slug: "corphish", name: "Corphish", genus: "Ruffian Pokémon", description: "It came from overseas. It is a very hardy creature that will quickly proliferate, even in polluted streams.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/341", normalKey: "pokedex/normal/341", shinyKey: "pokedex/shiny/341", silhouetteKey: "pokedex/silhouette/341")),
        PokedexSpeciesDefinition(nationalDexNumber: 342, generation: 3, slug: "crawdaunt", name: "Crawdaunt", genus: "Rogue Pokémon", description: "A rough customer that wildly flails its giant claws. It is said to be extremely hard to raise.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/342", normalKey: "pokedex/normal/342", shinyKey: "pokedex/shiny/342", silhouetteKey: "pokedex/silhouette/342")),
        PokedexSpeciesDefinition(nationalDexNumber: 343, generation: 3, slug: "baltoy", name: "Baltoy", genus: "Clay Doll Pokémon", description: "It was discovered in ancient ruins. While moving, it constantly spins. It stands on one foot even when asleep.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/343", normalKey: "pokedex/normal/343", shinyKey: "pokedex/shiny/343", silhouetteKey: "pokedex/silhouette/343")),
        PokedexSpeciesDefinition(nationalDexNumber: 344, generation: 3, slug: "claydol", name: "Claydol", genus: "Clay Doll Pokémon", description: "It appears to have been born from clay dolls made by ancient people. It uses telekinesis to float and move.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/344", normalKey: "pokedex/normal/344", shinyKey: "pokedex/shiny/344", silhouetteKey: "pokedex/silhouette/344")),
        PokedexSpeciesDefinition(nationalDexNumber: 345, generation: 3, slug: "lileep", name: "Lileep", genus: "Sea Lily Pokémon", description: "It became extinct roughly 100 million years ago. It was regenerated from a fossil using advanced techniques.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/345", normalKey: "pokedex/normal/345", shinyKey: "pokedex/shiny/345", silhouetteKey: "pokedex/silhouette/345")),
        PokedexSpeciesDefinition(nationalDexNumber: 346, generation: 3, slug: "cradily", name: "Cradily", genus: "Barnacle Pokémon", description: "It ensnares prey with its eight tentacles. It then melts the prey with a strong acid before feeding.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/346", normalKey: "pokedex/normal/346", shinyKey: "pokedex/shiny/346", silhouetteKey: "pokedex/silhouette/346")),
        PokedexSpeciesDefinition(nationalDexNumber: 347, generation: 3, slug: "anorith", name: "Anorith", genus: "Old Shrimp Pokémon", description: "It is a kind of Pokémon progenitor. It uses its extending claws to catch prey hiding among rocks on the seafloor.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/347", normalKey: "pokedex/normal/347", shinyKey: "pokedex/shiny/347", silhouetteKey: "pokedex/silhouette/347")),
        PokedexSpeciesDefinition(nationalDexNumber: 348, generation: 3, slug: "armaldo", name: "Armaldo", genus: "Plate Pokémon", description: "Protected by a hard shell, its body is very sturdy. It skewers prey with its claws to feed.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/348", normalKey: "pokedex/normal/348", shinyKey: "pokedex/shiny/348", silhouetteKey: "pokedex/silhouette/348")),
        PokedexSpeciesDefinition(nationalDexNumber: 349, generation: 3, slug: "feebas", name: "Feebas", genus: "Fish Pokémon", description: "Ridiculed for its shabby appearance, it is ignored by researchers. It lives in ponds choked with weeds.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/349", normalKey: "pokedex/normal/349", shinyKey: "pokedex/shiny/349", silhouetteKey: "pokedex/silhouette/349")),
        PokedexSpeciesDefinition(nationalDexNumber: 350, generation: 3, slug: "milotic", name: "Milotic", genus: "Tender Pokémon", description: "MILOTIC is breathtakingly beautiful. Those that see it are said to forget their combative spirits.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/350", normalKey: "pokedex/normal/350", shinyKey: "pokedex/shiny/350", silhouetteKey: "pokedex/silhouette/350")),
        PokedexSpeciesDefinition(nationalDexNumber: 351, generation: 3, slug: "castform", name: "Castform", genus: "Weather Pokémon", description: "It has the ability to change its form into the sun, the rain, or a snow cloud, depending on the weather.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/351", normalKey: "pokedex/normal/351", shinyKey: "pokedex/shiny/351", silhouetteKey: "pokedex/silhouette/351")),
        PokedexSpeciesDefinition(nationalDexNumber: 352, generation: 3, slug: "kecleon", name: "Kecleon", genus: "Color Swap Pokémon", description: "It changes body color to blend in with its surroundings. It also changes color if it is happy or sad.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/352", normalKey: "pokedex/normal/352", shinyKey: "pokedex/shiny/352", silhouetteKey: "pokedex/silhouette/352")),
        PokedexSpeciesDefinition(nationalDexNumber: 353, generation: 3, slug: "shuppet", name: "Shuppet", genus: "Puppet Pokémon", description: "It loves to feed on feelings like envy and malice. Its upright horn catches the emotions of people.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/353", normalKey: "pokedex/normal/353", shinyKey: "pokedex/shiny/353", silhouetteKey: "pokedex/silhouette/353")),
        PokedexSpeciesDefinition(nationalDexNumber: 354, generation: 3, slug: "banette", name: "Banette", genus: "Marionette Pokémon", description: "Strong feelings of hatred turned a puppet into a Pokémon. If it opens its mouth, its cursed energy escapes.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/354", normalKey: "pokedex/normal/354", shinyKey: "pokedex/shiny/354", silhouetteKey: "pokedex/silhouette/354")),
        PokedexSpeciesDefinition(nationalDexNumber: 355, generation: 3, slug: "duskull", name: "Duskull", genus: "Requiem Pokémon", description: "Making itself invisible, it silently sneaks up to prey. It has the ability to slip through thick walls.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/355", normalKey: "pokedex/normal/355", shinyKey: "pokedex/shiny/355", silhouetteKey: "pokedex/silhouette/355")),
        PokedexSpeciesDefinition(nationalDexNumber: 356, generation: 3, slug: "dusclops", name: "Dusclops", genus: "Beckon Pokémon", description: "Its body is entirely hollow. When it opens its mouth, it sucks everything in as if it were a black hole.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/356", normalKey: "pokedex/normal/356", shinyKey: "pokedex/shiny/356", silhouetteKey: "pokedex/silhouette/356")),
        PokedexSpeciesDefinition(nationalDexNumber: 357, generation: 3, slug: "tropius", name: "Tropius", genus: "Fruit Pokémon", description: "It lives in tropical jungles. The bunch of fruit around its neck is delicious. The fruit grows twice a year.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/357", normalKey: "pokedex/normal/357", shinyKey: "pokedex/shiny/357", silhouetteKey: "pokedex/silhouette/357")),
        PokedexSpeciesDefinition(nationalDexNumber: 358, generation: 3, slug: "chimecho", name: "Chimecho", genus: "Wind Chime Pokémon", description: "It travels by riding on winds. It cleverly uses its long tail to pluck nuts and berries, which it loves to eat.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/358", normalKey: "pokedex/normal/358", shinyKey: "pokedex/shiny/358", silhouetteKey: "pokedex/silhouette/358")),
        PokedexSpeciesDefinition(nationalDexNumber: 359, generation: 3, slug: "absol", name: "Absol", genus: "Disaster Pokémon", description: "It appears when it senses an impending natural disaster. As a result, it was mistaken as a doom-bringer.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/359", normalKey: "pokedex/normal/359", shinyKey: "pokedex/shiny/359", silhouetteKey: "pokedex/silhouette/359")),
        PokedexSpeciesDefinition(nationalDexNumber: 360, generation: 3, slug: "wynaut", name: "Wynaut", genus: "Bright Pokémon", description: "It tends to move in a pack with others. They cluster in a tight group to sleep in a cave.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/360", normalKey: "pokedex/normal/360", shinyKey: "pokedex/shiny/360", silhouetteKey: "pokedex/silhouette/360")),
        PokedexSpeciesDefinition(nationalDexNumber: 361, generation: 3, slug: "snorunt", name: "Snorunt", genus: "Snow Hat Pokémon", description: "It is said that a home visited by a SNORUNT will prosper. It can withstand cold of minus 150 degrees Fahrenheit.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/361", normalKey: "pokedex/normal/361", shinyKey: "pokedex/shiny/361", silhouetteKey: "pokedex/silhouette/361")),
        PokedexSpeciesDefinition(nationalDexNumber: 362, generation: 3, slug: "glalie", name: "Glalie", genus: "Face Pokémon", description: "It has a body of ice that won’t melt, even with fire. It can instantly freeze moisture in the atmosphere.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/362", normalKey: "pokedex/normal/362", shinyKey: "pokedex/shiny/362", silhouetteKey: "pokedex/silhouette/362")),
        PokedexSpeciesDefinition(nationalDexNumber: 363, generation: 3, slug: "spheal", name: "Spheal", genus: "Clap Pokémon", description: "Its body is covered in fluffy fur. The fur keeps it from feeling cold while it is rolling on ice.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/363", normalKey: "pokedex/normal/363", shinyKey: "pokedex/shiny/363", silhouetteKey: "pokedex/silhouette/363")),
        PokedexSpeciesDefinition(nationalDexNumber: 364, generation: 3, slug: "sealeo", name: "Sealeo", genus: "Ball Roll Pokémon", description: "It touches new things with its nose to test for smell and feel. It plays by spinning SPHEAL on its nose.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/364", normalKey: "pokedex/normal/364", shinyKey: "pokedex/shiny/364", silhouetteKey: "pokedex/silhouette/364")),
        PokedexSpeciesDefinition(nationalDexNumber: 365, generation: 3, slug: "walrein", name: "Walrein", genus: "Ice Break Pokémon", description: "It swims through icy seas while shattering ice floes with its large tusks. It is protected by its thick blubber.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/365", normalKey: "pokedex/normal/365", shinyKey: "pokedex/shiny/365", silhouetteKey: "pokedex/silhouette/365")),
        PokedexSpeciesDefinition(nationalDexNumber: 366, generation: 3, slug: "clamperl", name: "Clamperl", genus: "Bivalve Pokémon", description: "It is protected by a sturdy shell. Once in a lifetime, it makes a magnificent pearl.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/366", normalKey: "pokedex/normal/366", shinyKey: "pokedex/shiny/366", silhouetteKey: "pokedex/silhouette/366")),
        PokedexSpeciesDefinition(nationalDexNumber: 367, generation: 3, slug: "huntail", name: "Huntail", genus: "Deep Sea Pokémon", description: "It lives deep in the sea where no light ever filters down. It lights up its small fishlike tail to attract prey.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/367", normalKey: "pokedex/normal/367", shinyKey: "pokedex/shiny/367", silhouetteKey: "pokedex/silhouette/367")),
        PokedexSpeciesDefinition(nationalDexNumber: 368, generation: 3, slug: "gorebyss", name: "Gorebyss", genus: "South Sea Pokémon", description: "Its swimming form is exquisitely elegant. With its thin mouth, it feeds on seaweed that grows between rocks.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/368", normalKey: "pokedex/normal/368", shinyKey: "pokedex/shiny/368", silhouetteKey: "pokedex/silhouette/368")),
        PokedexSpeciesDefinition(nationalDexNumber: 369, generation: 3, slug: "relicanth", name: "Relicanth", genus: "Longevity Pokémon", description: "It has remained unchanged for 100 million years. It was discovered during a deep-sea exploration.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/369", normalKey: "pokedex/normal/369", shinyKey: "pokedex/shiny/369", silhouetteKey: "pokedex/silhouette/369")),
        PokedexSpeciesDefinition(nationalDexNumber: 370, generation: 3, slug: "luvdisc", name: "Luvdisc", genus: "Rendezvous Pokémon", description: "During the spawning season, countless LUVDISC congregate at coral reefs, turning the waters pink.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/370", normalKey: "pokedex/normal/370", shinyKey: "pokedex/shiny/370", silhouetteKey: "pokedex/silhouette/370")),
        PokedexSpeciesDefinition(nationalDexNumber: 371, generation: 3, slug: "bagon", name: "Bagon", genus: "Rock Head Pokémon", description: "Its steel-hard head can shatter boulders. It longingly hopes for wings to grow so it can fly.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/371", normalKey: "pokedex/normal/371", shinyKey: "pokedex/shiny/371", silhouetteKey: "pokedex/silhouette/371")),
        PokedexSpeciesDefinition(nationalDexNumber: 372, generation: 3, slug: "shelgon", name: "Shelgon", genus: "Endurance Pokémon", description: "Its armored body makes all attacks bounce off. The armor is too tough, however, making it heavy and somewhat sluggish.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/372", normalKey: "pokedex/normal/372", shinyKey: "pokedex/shiny/372", silhouetteKey: "pokedex/silhouette/372")),
        PokedexSpeciesDefinition(nationalDexNumber: 373, generation: 3, slug: "salamence", name: "Salamence", genus: "Dragon Pokémon", description: "It becomes uncontrollable if it is enraged. It destroys everything with shredding claws and fire.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/373", normalKey: "pokedex/normal/373", shinyKey: "pokedex/shiny/373", silhouetteKey: "pokedex/silhouette/373")),
        PokedexSpeciesDefinition(nationalDexNumber: 374, generation: 3, slug: "beldum", name: "Beldum", genus: "Iron Ball Pokémon", description: "It uses magnetic waves to converse with its kind. All the cells in its body are magnetic.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/374", normalKey: "pokedex/normal/374", shinyKey: "pokedex/shiny/374", silhouetteKey: "pokedex/silhouette/374")),
        PokedexSpeciesDefinition(nationalDexNumber: 375, generation: 3, slug: "metang", name: "Metang", genus: "Iron Claw Pokémon", description: "It floats midair using magnetism. Its body is so tough, even a crash with a jet plane won’t leave a scratch.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/375", normalKey: "pokedex/normal/375", shinyKey: "pokedex/shiny/375", silhouetteKey: "pokedex/silhouette/375")),
        PokedexSpeciesDefinition(nationalDexNumber: 376, generation: 3, slug: "metagross", name: "Metagross", genus: "Iron Leg Pokémon", description: "It is formed by two METANG fusing. Its four brains are said to be superior to a supercomputer.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/376", normalKey: "pokedex/normal/376", shinyKey: "pokedex/shiny/376", silhouetteKey: "pokedex/silhouette/376")),
        PokedexSpeciesDefinition(nationalDexNumber: 377, generation: 3, slug: "regirock", name: "Regirock", genus: "Rock Peak Pokémon", description: "It is entirely composed of rocks with no sign of a brain or heart. It is a mystery even to modern scientists.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/377", normalKey: "pokedex/normal/377", shinyKey: "pokedex/shiny/377", silhouetteKey: "pokedex/silhouette/377")),
        PokedexSpeciesDefinition(nationalDexNumber: 378, generation: 3, slug: "regice", name: "Regice", genus: "Iceberg Pokémon", description: "Research revealed that its body is made of the same kind of ice that is found at the South Pole.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/378", normalKey: "pokedex/normal/378", shinyKey: "pokedex/shiny/378", silhouetteKey: "pokedex/silhouette/378")),
        PokedexSpeciesDefinition(nationalDexNumber: 379, generation: 3, slug: "registeel", name: "Registeel", genus: "Iron Pokémon", description: "It is sturdier than any kind of metal. It hardened due to pressure underground over tens of thousands of years.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/379", normalKey: "pokedex/normal/379", shinyKey: "pokedex/shiny/379", silhouetteKey: "pokedex/silhouette/379")),
        PokedexSpeciesDefinition(nationalDexNumber: 380, generation: 3, slug: "latias", name: "Latias", genus: "Eon Pokémon", description: "It can telepathically communicate with people. It changes its appearance using its down that refracts light.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/380", normalKey: "pokedex/normal/380", shinyKey: "pokedex/shiny/380", silhouetteKey: "pokedex/silhouette/380")),
        PokedexSpeciesDefinition(nationalDexNumber: 381, generation: 3, slug: "latios", name: "Latios", genus: "Eon Pokémon", description: "It has a docile temperament and dislikes fighting. Tucking in its forelegs, it can fly faster than a jet plane.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/381", normalKey: "pokedex/normal/381", shinyKey: "pokedex/shiny/381", silhouetteKey: "pokedex/silhouette/381")),
        PokedexSpeciesDefinition(nationalDexNumber: 382, generation: 3, slug: "kyogre", name: "Kyogre", genus: "Sea Basin Pokémon", description: "This Pokémon is said to have expanded the sea by bringing heavy rains. It has the power to control water.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/382", normalKey: "pokedex/normal/382", shinyKey: "pokedex/shiny/382", silhouetteKey: "pokedex/silhouette/382")),
        PokedexSpeciesDefinition(nationalDexNumber: 383, generation: 3, slug: "groudon", name: "Groudon", genus: "Continent Pokémon", description: "This legendary Pokémon is said to represent the land. It went to sleep after dueling KYOGRE.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/383", normalKey: "pokedex/normal/383", shinyKey: "pokedex/shiny/383", silhouetteKey: "pokedex/silhouette/383")),
        PokedexSpeciesDefinition(nationalDexNumber: 384, generation: 3, slug: "rayquaza", name: "Rayquaza", genus: "Sky High Pokémon", description: "It has lived for hundreds of millions of years in the ozone layer. Its flying form looks like a meteor.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/384", normalKey: "pokedex/normal/384", shinyKey: "pokedex/shiny/384", silhouetteKey: "pokedex/silhouette/384")),
        PokedexSpeciesDefinition(nationalDexNumber: 385, generation: 3, slug: "jirachi", name: "Jirachi", genus: "Wish Pokémon", description: "It is said to make any wish come true. It is awake for only seven days out of a thousand years.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/385", normalKey: "pokedex/normal/385", shinyKey: "pokedex/shiny/385", silhouetteKey: "pokedex/silhouette/385")),
        PokedexSpeciesDefinition(nationalDexNumber: 386, generation: 3, slug: "deoxys", name: "Deoxys", genus: "DNA Pokémon", description: "This DEOXYS has transformed into its aggressive guise. It can fool enemies by altering its appearance.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/386", normalKey: "pokedex/normal/386", shinyKey: "pokedex/shiny/386", silhouetteKey: "pokedex/silhouette/386")),
        PokedexSpeciesDefinition(nationalDexNumber: 387, generation: 4, slug: "turtwig", name: "Turtwig", genus: "Tiny Leaf Pokémon", description: "Photosynthesis occurs across its body under the sun. The shell on its back is actually hardened soil.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/387", normalKey: "pokedex/normal/387", shinyKey: "pokedex/shiny/387", silhouetteKey: "pokedex/silhouette/387")),
        PokedexSpeciesDefinition(nationalDexNumber: 388, generation: 4, slug: "grotle", name: "Grotle", genus: "Grove Pokémon", description: "It lives along water in forests. In the daytime, it leaves the forest to sunbathe its treed shell.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/388", normalKey: "pokedex/normal/388", shinyKey: "pokedex/shiny/388", silhouetteKey: "pokedex/silhouette/388")),
        PokedexSpeciesDefinition(nationalDexNumber: 389, generation: 4, slug: "torterra", name: "Torterra", genus: "Continent Pokémon", description: "Ancient people imagined that beneath the ground, a gigantic Torterra dwelled.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/389", normalKey: "pokedex/normal/389", shinyKey: "pokedex/shiny/389", silhouetteKey: "pokedex/silhouette/389")),
        PokedexSpeciesDefinition(nationalDexNumber: 390, generation: 4, slug: "chimchar", name: "Chimchar", genus: "Chimp Pokémon", description: "Its fiery rear end is fueled by gas made in its belly. Even rain can’t extinguish the fire.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/390", normalKey: "pokedex/normal/390", shinyKey: "pokedex/shiny/390", silhouetteKey: "pokedex/silhouette/390")),
        PokedexSpeciesDefinition(nationalDexNumber: 391, generation: 4, slug: "monferno", name: "Monferno", genus: "Playful Pokémon", description: "It skillfully controls the intensity of the fire on its tail to keep its foes at an ideal distance.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/391", normalKey: "pokedex/normal/391", shinyKey: "pokedex/shiny/391", silhouetteKey: "pokedex/silhouette/391")),
        PokedexSpeciesDefinition(nationalDexNumber: 392, generation: 4, slug: "infernape", name: "Infernape", genus: "Flame Pokémon", description: "Its crown of fire is indicative of its fiery nature. It is beaten by none in terms of quickness.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/392", normalKey: "pokedex/normal/392", shinyKey: "pokedex/shiny/392", silhouetteKey: "pokedex/silhouette/392")),
        PokedexSpeciesDefinition(nationalDexNumber: 393, generation: 4, slug: "piplup", name: "Piplup", genus: "Penguin Pokémon", description: "It doesn’t like to be taken care of. It’s difficult to bond with since it won’t listen to its Trainer.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/393", normalKey: "pokedex/normal/393", shinyKey: "pokedex/shiny/393", silhouetteKey: "pokedex/silhouette/393")),
        PokedexSpeciesDefinition(nationalDexNumber: 394, generation: 4, slug: "prinplup", name: "Prinplup", genus: "Penguin Pokémon", description: "It lives alone, away from others. Apparently, every one of them believes it is the most important.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/394", normalKey: "pokedex/normal/394", shinyKey: "pokedex/shiny/394", silhouetteKey: "pokedex/silhouette/394")),
        PokedexSpeciesDefinition(nationalDexNumber: 395, generation: 4, slug: "empoleon", name: "Empoleon", genus: "Emperor Pokémon", description: "It swims as fast as a jet boat. The edges of its wings are sharp and can slice apart drifting ice.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/395", normalKey: "pokedex/normal/395", shinyKey: "pokedex/shiny/395", silhouetteKey: "pokedex/silhouette/395")),
        PokedexSpeciesDefinition(nationalDexNumber: 396, generation: 4, slug: "starly", name: "Starly", genus: "Starling Pokémon", description: "They flock in great numbers. Though small, they flap their wings with great power.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/396", normalKey: "pokedex/normal/396", shinyKey: "pokedex/shiny/396", silhouetteKey: "pokedex/silhouette/396")),
        PokedexSpeciesDefinition(nationalDexNumber: 397, generation: 4, slug: "staravia", name: "Staravia", genus: "Starling Pokémon", description: "They maintain huge flocks, although fierce scuffles break out between various flocks.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/397", normalKey: "pokedex/normal/397", shinyKey: "pokedex/shiny/397", silhouetteKey: "pokedex/silhouette/397")),
        PokedexSpeciesDefinition(nationalDexNumber: 398, generation: 4, slug: "staraptor", name: "Staraptor", genus: "Predator Pokémon", description: "The muscles in its wings and legs are strong. It can easily fly while gripping a small Pokémon.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/398", normalKey: "pokedex/normal/398", shinyKey: "pokedex/shiny/398", silhouetteKey: "pokedex/silhouette/398")),
        PokedexSpeciesDefinition(nationalDexNumber: 399, generation: 4, slug: "bidoof", name: "Bidoof", genus: "Plump Mouse Pokémon", description: "With nerves of steel, nothing can perturb it. It is more agile and active than it appears.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/399", normalKey: "pokedex/normal/399", shinyKey: "pokedex/shiny/399", silhouetteKey: "pokedex/silhouette/399")),
        PokedexSpeciesDefinition(nationalDexNumber: 400, generation: 4, slug: "bibarel", name: "Bibarel", genus: "Beaver Pokémon", description: "It busily makes its nest with stacks of branches and roots it has cut up with its sharp incisors.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/400", normalKey: "pokedex/normal/400", shinyKey: "pokedex/shiny/400", silhouetteKey: "pokedex/silhouette/400")),
        PokedexSpeciesDefinition(nationalDexNumber: 401, generation: 4, slug: "kricketot", name: "Kricketot", genus: "Cricket Pokémon", description: "It chats with others using the sounds of its colliding antennae. These sounds are fall hallmarks.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/401", normalKey: "pokedex/normal/401", shinyKey: "pokedex/shiny/401", silhouetteKey: "pokedex/silhouette/401")),
        PokedexSpeciesDefinition(nationalDexNumber: 402, generation: 4, slug: "kricketune", name: "Kricketune", genus: "Cricket Pokémon", description: "It crosses its knifelike arms in front of its chest when it cries. It can compose melodies ad lib.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/402", normalKey: "pokedex/normal/402", shinyKey: "pokedex/shiny/402", silhouetteKey: "pokedex/silhouette/402")),
        PokedexSpeciesDefinition(nationalDexNumber: 403, generation: 4, slug: "shinx", name: "Shinx", genus: "Flash Pokémon", description: "The extension and contraction of its muscles generates electricity. It glows when in trouble.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/403", normalKey: "pokedex/normal/403", shinyKey: "pokedex/shiny/403", silhouetteKey: "pokedex/silhouette/403")),
        PokedexSpeciesDefinition(nationalDexNumber: 404, generation: 4, slug: "luxio", name: "Luxio", genus: "Spark Pokémon", description: "Its claws loose electricity with enough amperage to cause fainting. They live in small groups.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/404", normalKey: "pokedex/normal/404", shinyKey: "pokedex/shiny/404", silhouetteKey: "pokedex/silhouette/404")),
        PokedexSpeciesDefinition(nationalDexNumber: 405, generation: 4, slug: "luxray", name: "Luxray", genus: "Gleam Eyes Pokémon", description: "When its eyes gleam gold, it can spot hiding prey--even those taking shelter behind a wall.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/405", normalKey: "pokedex/normal/405", shinyKey: "pokedex/shiny/405", silhouetteKey: "pokedex/silhouette/405")),
        PokedexSpeciesDefinition(nationalDexNumber: 406, generation: 4, slug: "budew", name: "Budew", genus: "Bud Pokémon", description: "When it feels the sun’s warm touch, it opens its bud to release pollen. It lives alongside clear pools.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/406", normalKey: "pokedex/normal/406", shinyKey: "pokedex/shiny/406", silhouetteKey: "pokedex/silhouette/406")),
        PokedexSpeciesDefinition(nationalDexNumber: 407, generation: 4, slug: "roserade", name: "Roserade", genus: "Bouquet Pokémon", description: "Luring prey with a sweet scent, it uses poison whips on its arms to poison, bind, and finish off the prey.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/407", normalKey: "pokedex/normal/407", shinyKey: "pokedex/shiny/407", silhouetteKey: "pokedex/silhouette/407")),
        PokedexSpeciesDefinition(nationalDexNumber: 408, generation: 4, slug: "cranidos", name: "Cranidos", genus: "Head Butt Pokémon", description: "It was resurrected from an iron ball-like fossil. It downs prey with its headbutts.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/408", normalKey: "pokedex/normal/408", shinyKey: "pokedex/shiny/408", silhouetteKey: "pokedex/silhouette/408")),
        PokedexSpeciesDefinition(nationalDexNumber: 409, generation: 4, slug: "rampardos", name: "Rampardos", genus: "Head Butt Pokémon", description: "Its skull withstands impacts of any magnitude. As a result, its brain never gets the chance to grow.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/409", normalKey: "pokedex/normal/409", shinyKey: "pokedex/shiny/409", silhouetteKey: "pokedex/silhouette/409")),
        PokedexSpeciesDefinition(nationalDexNumber: 410, generation: 4, slug: "shieldon", name: "Shieldon", genus: "Shield Pokémon", description: "It habitually polishes its face by rubbing it against tree trunks. It is weak to attacks from behind.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/410", normalKey: "pokedex/normal/410", shinyKey: "pokedex/shiny/410", silhouetteKey: "pokedex/silhouette/410")),
        PokedexSpeciesDefinition(nationalDexNumber: 411, generation: 4, slug: "bastiodon", name: "Bastiodon", genus: "Shield Pokémon", description: "When they lined up side by side, no foe could break through. They shielded their young in that way.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/411", normalKey: "pokedex/normal/411", shinyKey: "pokedex/shiny/411", silhouetteKey: "pokedex/silhouette/411")),
        PokedexSpeciesDefinition(nationalDexNumber: 412, generation: 4, slug: "burmy", name: "Burmy", genus: "Bagworm Pokémon", description: "To shelter itself from cold, wintry winds, it covers itself with a cloak made of twigs and leaves.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/412", normalKey: "pokedex/normal/412", shinyKey: "pokedex/shiny/412", silhouetteKey: "pokedex/silhouette/412")),
        PokedexSpeciesDefinition(nationalDexNumber: 413, generation: 4, slug: "wormadam", name: "Wormadam", genus: "Bagworm Pokémon", description: "Its appearance changes depending on where it evolved. The materials on hand become a part of its body.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/413", normalKey: "pokedex/normal/413", shinyKey: "pokedex/shiny/413", silhouetteKey: "pokedex/silhouette/413")),
        PokedexSpeciesDefinition(nationalDexNumber: 414, generation: 4, slug: "mothim", name: "Mothim", genus: "Moth Pokémon", description: "It loves the honey of flowers and steals honey collected by Combee.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/414", normalKey: "pokedex/normal/414", shinyKey: "pokedex/shiny/414", silhouetteKey: "pokedex/silhouette/414")),
        PokedexSpeciesDefinition(nationalDexNumber: 415, generation: 4, slug: "combee", name: "Combee", genus: "Tiny Bee Pokémon", description: "The trio is together from birth. It constantly gathers honey from flowers to please Vespiquen.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/415", normalKey: "pokedex/normal/415", shinyKey: "pokedex/shiny/415", silhouetteKey: "pokedex/silhouette/415")),
        PokedexSpeciesDefinition(nationalDexNumber: 416, generation: 4, slug: "vespiquen", name: "Vespiquen", genus: "Beehive Pokémon", description: "It houses its colony in cells in its body and releases various pheromones to make those grubs do its bidding.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/416", normalKey: "pokedex/normal/416", shinyKey: "pokedex/shiny/416", silhouetteKey: "pokedex/silhouette/416")),
        PokedexSpeciesDefinition(nationalDexNumber: 417, generation: 4, slug: "pachirisu", name: "Pachirisu", genus: "EleSquirrel Pokémon", description: "It makes fur balls that crackle with static electricity. It stores them with berries in tree holes.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/417", normalKey: "pokedex/normal/417", shinyKey: "pokedex/shiny/417", silhouetteKey: "pokedex/silhouette/417")),
        PokedexSpeciesDefinition(nationalDexNumber: 418, generation: 4, slug: "buizel", name: "Buizel", genus: "Sea Weasel Pokémon", description: "It swims by rotating its two tails like a screw. When it dives, its flotation sac collapses.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/418", normalKey: "pokedex/normal/418", shinyKey: "pokedex/shiny/418", silhouetteKey: "pokedex/silhouette/418")),
        PokedexSpeciesDefinition(nationalDexNumber: 419, generation: 4, slug: "floatzel", name: "Floatzel", genus: "Sea Weasel Pokémon", description: "It floats using its well-developed flotation sac. It assists in the rescues of drowning people.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/419", normalKey: "pokedex/normal/419", shinyKey: "pokedex/shiny/419", silhouetteKey: "pokedex/silhouette/419")),
        PokedexSpeciesDefinition(nationalDexNumber: 420, generation: 4, slug: "cherubi", name: "Cherubi", genus: "Cherry Pokémon", description: "Sunlight colors it red. When the small ball is drained of nutrients, it shrivels to herald evolution.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/420", normalKey: "pokedex/normal/420", shinyKey: "pokedex/shiny/420", silhouetteKey: "pokedex/silhouette/420")),
        PokedexSpeciesDefinition(nationalDexNumber: 421, generation: 4, slug: "cherrim", name: "Cherrim", genus: "Blossom Pokémon", description: "During times of strong sunlight, its bud blooms, its petals open fully, and it becomes very active.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/421", normalKey: "pokedex/normal/421", shinyKey: "pokedex/shiny/421", silhouetteKey: "pokedex/silhouette/421")),
        PokedexSpeciesDefinition(nationalDexNumber: 422, generation: 4, slug: "shellos", name: "Shellos", genus: "Sea Slug Pokémon", description: "Beware of pushing strongly on its squishy body, as it makes a mysterious purple fluid ooze out.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/422", normalKey: "pokedex/normal/422", shinyKey: "pokedex/shiny/422", silhouetteKey: "pokedex/silhouette/422")),
        PokedexSpeciesDefinition(nationalDexNumber: 423, generation: 4, slug: "gastrodon", name: "Gastrodon", genus: "Sea Slug Pokémon", description: "When its natural enemy attacks, it oozes purple fluid and escapes.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/423", normalKey: "pokedex/normal/423", shinyKey: "pokedex/shiny/423", silhouetteKey: "pokedex/silhouette/423")),
        PokedexSpeciesDefinition(nationalDexNumber: 424, generation: 4, slug: "ambipom", name: "Ambipom", genus: "Long Tail Pokémon", description: "They work in large colonies and make rings by linking their tails, apparently in friendship.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/424", normalKey: "pokedex/normal/424", shinyKey: "pokedex/shiny/424", silhouetteKey: "pokedex/silhouette/424")),
        PokedexSpeciesDefinition(nationalDexNumber: 425, generation: 4, slug: "drifloon", name: "Drifloon", genus: "Balloon Pokémon", description: "A Pokémon formed by the spirits of people and Pokémon. It loves damp, humid seasons.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/425", normalKey: "pokedex/normal/425", shinyKey: "pokedex/shiny/425", silhouetteKey: "pokedex/silhouette/425")),
        PokedexSpeciesDefinition(nationalDexNumber: 426, generation: 4, slug: "drifblim", name: "Drifblim", genus: "Blimp Pokémon", description: "It carries people and Pokémon when it flies. But since it only drifts, it can end up anywhere.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/426", normalKey: "pokedex/normal/426", shinyKey: "pokedex/shiny/426", silhouetteKey: "pokedex/silhouette/426")),
        PokedexSpeciesDefinition(nationalDexNumber: 427, generation: 4, slug: "buneary", name: "Buneary", genus: "Rabbit Pokémon", description: "Its ears are always rolled up. They can be forcefully extended to shatter even a large boulder.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/427", normalKey: "pokedex/normal/427", shinyKey: "pokedex/shiny/427", silhouetteKey: "pokedex/silhouette/427")),
        PokedexSpeciesDefinition(nationalDexNumber: 428, generation: 4, slug: "lopunny", name: "Lopunny", genus: "Rabbit Pokémon", description: "Extremely cautious, it quickly bounds off when it senses danger.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/428", normalKey: "pokedex/normal/428", shinyKey: "pokedex/shiny/428", silhouetteKey: "pokedex/silhouette/428")),
        PokedexSpeciesDefinition(nationalDexNumber: 429, generation: 4, slug: "mismagius", name: "Mismagius", genus: "Magical Pokémon", description: "It chants incantations. While they usually torment targets, some chants bring happiness.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/429", normalKey: "pokedex/normal/429", shinyKey: "pokedex/shiny/429", silhouetteKey: "pokedex/silhouette/429")),
        PokedexSpeciesDefinition(nationalDexNumber: 430, generation: 4, slug: "honchkrow", name: "Honchkrow", genus: "Big Boss Pokémon", description: "If one utters a deep cry, many Murkrow gather quickly. For this, it is called “Summoner of Night.”", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/430", normalKey: "pokedex/normal/430", shinyKey: "pokedex/shiny/430", silhouetteKey: "pokedex/silhouette/430")),
        PokedexSpeciesDefinition(nationalDexNumber: 431, generation: 4, slug: "glameow", name: "Glameow", genus: "Catty Pokémon", description: "It claws if displeased and purrs when affectionate. Its fickleness is very popular among some.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/431", normalKey: "pokedex/normal/431", shinyKey: "pokedex/shiny/431", silhouetteKey: "pokedex/silhouette/431")),
        PokedexSpeciesDefinition(nationalDexNumber: 432, generation: 4, slug: "purugly", name: "Purugly", genus: "Tiger Cat Pokémon", description: "It would claim another Pokémon’s nest as its own if it finds a nest sufficiently comfortable.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/432", normalKey: "pokedex/normal/432", shinyKey: "pokedex/shiny/432", silhouetteKey: "pokedex/silhouette/432")),
        PokedexSpeciesDefinition(nationalDexNumber: 433, generation: 4, slug: "chingling", name: "Chingling", genus: "Bell Pokémon", description: "Each time it hops, it makes a ringing sound. It deafens foes by emitting high-frequency cries.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/433", normalKey: "pokedex/normal/433", shinyKey: "pokedex/shiny/433", silhouetteKey: "pokedex/silhouette/433")),
        PokedexSpeciesDefinition(nationalDexNumber: 434, generation: 4, slug: "stunky", name: "Stunky", genus: "Skunk Pokémon", description: "It sprays a foul fluid from its rear. Its stench spreads over a mile radius, driving Pokémon away.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/434", normalKey: "pokedex/normal/434", shinyKey: "pokedex/shiny/434", silhouetteKey: "pokedex/silhouette/434")),
        PokedexSpeciesDefinition(nationalDexNumber: 435, generation: 4, slug: "skuntank", name: "Skuntank", genus: "Skunk Pokémon", description: "It sprays a vile-smelling fluid from the tip of its tail to attack. Its range is over 160 feet.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/435", normalKey: "pokedex/normal/435", shinyKey: "pokedex/shiny/435", silhouetteKey: "pokedex/silhouette/435")),
        PokedexSpeciesDefinition(nationalDexNumber: 436, generation: 4, slug: "bronzor", name: "Bronzor", genus: "Bronze Pokémon", description: "Ancient people believed that the pattern on Bronzor’s back contained a mysterious power.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/436", normalKey: "pokedex/normal/436", shinyKey: "pokedex/shiny/436", silhouetteKey: "pokedex/silhouette/436")),
        PokedexSpeciesDefinition(nationalDexNumber: 437, generation: 4, slug: "bronzong", name: "Bronzong", genus: "Bronze Bell Pokémon", description: "In ages past, this Pokémon was revered as a bringer of rain. It was found buried in the ground.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/437", normalKey: "pokedex/normal/437", shinyKey: "pokedex/shiny/437", silhouetteKey: "pokedex/silhouette/437")),
        PokedexSpeciesDefinition(nationalDexNumber: 438, generation: 4, slug: "bonsly", name: "Bonsly", genus: "Bonsai Pokémon", description: "It prefers arid environments. It leaks water from its eyes to adjust its body’s fluid levels.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/438", normalKey: "pokedex/normal/438", shinyKey: "pokedex/shiny/438", silhouetteKey: "pokedex/silhouette/438")),
        PokedexSpeciesDefinition(nationalDexNumber: 439, generation: 4, slug: "mime-jr", name: "Mime Jr.", genus: "Mime Pokémon", description: "In an attempt to confuse its enemy, it mimics the enemy’s movements. Then it wastes no time in making itself scarce!", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/439", normalKey: "pokedex/normal/439", shinyKey: "pokedex/shiny/439", silhouetteKey: "pokedex/silhouette/439")),
        PokedexSpeciesDefinition(nationalDexNumber: 440, generation: 4, slug: "happiny", name: "Happiny", genus: "Playhouse Pokémon", description: "It carries a round, egg-shaped rock in its belly pouch and gives the rock to its friends.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/440", normalKey: "pokedex/normal/440", shinyKey: "pokedex/shiny/440", silhouetteKey: "pokedex/silhouette/440")),
        PokedexSpeciesDefinition(nationalDexNumber: 441, generation: 4, slug: "chatot", name: "Chatot", genus: "Music Note Pokémon", description: "It mimics the cries of other Pokémon to trick them into thinking it’s one of them. This way they won’t attack it.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/441", normalKey: "pokedex/normal/441", shinyKey: "pokedex/shiny/441", silhouetteKey: "pokedex/silhouette/441")),
        PokedexSpeciesDefinition(nationalDexNumber: 442, generation: 4, slug: "spiritomb", name: "Spiritomb", genus: "Forbidden Pokémon", description: "A Pokémon that was formed by 108 spirits. It is bound to a fissure in an odd keystone.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/442", normalKey: "pokedex/normal/442", shinyKey: "pokedex/shiny/442", silhouetteKey: "pokedex/silhouette/442")),
        PokedexSpeciesDefinition(nationalDexNumber: 443, generation: 4, slug: "gible", name: "Gible", genus: "Land Shark Pokémon", description: "It nests in horizontal holes warmed by geothermal heat. Foes who get too close can expect to be pounced on and bitten.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/443", normalKey: "pokedex/normal/443", shinyKey: "pokedex/shiny/443", silhouetteKey: "pokedex/silhouette/443")),
        PokedexSpeciesDefinition(nationalDexNumber: 444, generation: 4, slug: "gabite", name: "Gabite", genus: "Cave Pokémon", description: "It loves sparkly things. It seeks treasures in caves and hoards the loot in its nest.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/444", normalKey: "pokedex/normal/444", shinyKey: "pokedex/shiny/444", silhouetteKey: "pokedex/silhouette/444")),
        PokedexSpeciesDefinition(nationalDexNumber: 445, generation: 4, slug: "garchomp", name: "Garchomp", genus: "Mach Pokémon", description: "When it folds up its body and extends its wings, it looks like a jet plane. It flies at sonic speed.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/445", normalKey: "pokedex/normal/445", shinyKey: "pokedex/shiny/445", silhouetteKey: "pokedex/silhouette/445")),
        PokedexSpeciesDefinition(nationalDexNumber: 446, generation: 4, slug: "munchlax", name: "Munchlax", genus: "Big Eater Pokémon", description: "It hides food under its long body hair. However, it forgets it has hidden the food.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/446", normalKey: "pokedex/normal/446", shinyKey: "pokedex/shiny/446", silhouetteKey: "pokedex/silhouette/446")),
        PokedexSpeciesDefinition(nationalDexNumber: 447, generation: 4, slug: "riolu", name: "Riolu", genus: "Emanation Pokémon", description: "It uses the shapes of auras, which change according to emotion, to communicate with others.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/447", normalKey: "pokedex/normal/447", shinyKey: "pokedex/shiny/447", silhouetteKey: "pokedex/silhouette/447")),
        PokedexSpeciesDefinition(nationalDexNumber: 448, generation: 4, slug: "lucario", name: "Lucario", genus: "Aura Pokémon", description: "By catching the aura emanating from others, it can read their thoughts and movements.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/448", normalKey: "pokedex/normal/448", shinyKey: "pokedex/shiny/448", silhouetteKey: "pokedex/silhouette/448")),
        PokedexSpeciesDefinition(nationalDexNumber: 449, generation: 4, slug: "hippopotas", name: "Hippopotas", genus: "Hippo Pokémon", description: "It lives in arid places. Instead of perspiration, it expels grainy sand from its body.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/449", normalKey: "pokedex/normal/449", shinyKey: "pokedex/shiny/449", silhouetteKey: "pokedex/silhouette/449")),
        PokedexSpeciesDefinition(nationalDexNumber: 450, generation: 4, slug: "hippowdon", name: "Hippowdon", genus: "Heavyweight Pokémon", description: "It brandishes its gaping mouth in a display of fearsome strength. It raises vast quantities of sand while attacking.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/450", normalKey: "pokedex/normal/450", shinyKey: "pokedex/shiny/450", silhouetteKey: "pokedex/silhouette/450")),
        PokedexSpeciesDefinition(nationalDexNumber: 451, generation: 4, slug: "skorupi", name: "Skorupi", genus: "Scorpion Pokémon", description: "It grips prey with its tail claws and injects poison. It tenaciously hangs on until the poison takes.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/451", normalKey: "pokedex/normal/451", shinyKey: "pokedex/shiny/451", silhouetteKey: "pokedex/silhouette/451")),
        PokedexSpeciesDefinition(nationalDexNumber: 452, generation: 4, slug: "drapion", name: "Drapion", genus: "Ogre Scorpion Pokémon", description: "It takes pride in its strength. Even though it can tear foes apart, it finishes them off with powerful poison.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/452", normalKey: "pokedex/normal/452", shinyKey: "pokedex/shiny/452", silhouetteKey: "pokedex/silhouette/452")),
        PokedexSpeciesDefinition(nationalDexNumber: 453, generation: 4, slug: "croagunk", name: "Croagunk", genus: "Toxic Mouth Pokémon", description: "Its cheeks hold poison sacs. It tries to catch foes off guard to jab them with toxic fingers.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/453", normalKey: "pokedex/normal/453", shinyKey: "pokedex/shiny/453", silhouetteKey: "pokedex/silhouette/453")),
        PokedexSpeciesDefinition(nationalDexNumber: 454, generation: 4, slug: "toxicroak", name: "Toxicroak", genus: "Toxic Mouth Pokémon", description: "It has a poison sac at its throat. When it croaks, the stored poison is churned for greater potency.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/454", normalKey: "pokedex/normal/454", shinyKey: "pokedex/shiny/454", silhouetteKey: "pokedex/silhouette/454")),
        PokedexSpeciesDefinition(nationalDexNumber: 455, generation: 4, slug: "carnivine", name: "Carnivine", genus: "Bug Catcher Pokémon", description: "It attracts prey with its sweet-smelling saliva, then chomps down. It takes a whole day to eat prey.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/455", normalKey: "pokedex/normal/455", shinyKey: "pokedex/shiny/455", silhouetteKey: "pokedex/silhouette/455")),
        PokedexSpeciesDefinition(nationalDexNumber: 456, generation: 4, slug: "finneon", name: "Finneon", genus: "Wing Fish Pokémon", description: "The line running down its side can store sunlight. It shines vividly at night.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/456", normalKey: "pokedex/normal/456", shinyKey: "pokedex/shiny/456", silhouetteKey: "pokedex/silhouette/456")),
        PokedexSpeciesDefinition(nationalDexNumber: 457, generation: 4, slug: "lumineon", name: "Lumineon", genus: "Neon Pokémon", description: "It lives on the deep-sea floor. It attracts prey by flashing the patterns on its four tail fins.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/457", normalKey: "pokedex/normal/457", shinyKey: "pokedex/shiny/457", silhouetteKey: "pokedex/silhouette/457")),
        PokedexSpeciesDefinition(nationalDexNumber: 458, generation: 4, slug: "mantyke", name: "Mantyke", genus: "Kite Pokémon", description: "The pattern on its back varies by region. It often swims in a school of Remoraid.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/458", normalKey: "pokedex/normal/458", shinyKey: "pokedex/shiny/458", silhouetteKey: "pokedex/silhouette/458")),
        PokedexSpeciesDefinition(nationalDexNumber: 459, generation: 4, slug: "snover", name: "Snover", genus: "Frost Tree Pokémon", description: "During cold seasons, it migrates to the mountain’s lower reaches. It returns to the snow-covered summit in the spring.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/459", normalKey: "pokedex/normal/459", shinyKey: "pokedex/shiny/459", silhouetteKey: "pokedex/silhouette/459")),
        PokedexSpeciesDefinition(nationalDexNumber: 460, generation: 4, slug: "abomasnow", name: "Abomasnow", genus: "Frost Tree Pokémon", description: "It blankets wide areas in snow by whipping up blizzards. It is also known as “The Ice Monster.”", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/460", normalKey: "pokedex/normal/460", shinyKey: "pokedex/shiny/460", silhouetteKey: "pokedex/silhouette/460")),
        PokedexSpeciesDefinition(nationalDexNumber: 461, generation: 4, slug: "weavile", name: "Weavile", genus: "Sharp Claw Pokémon", description: "It lives in snowy regions. It carves patterns in trees with its claws as a signal to others.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/461", normalKey: "pokedex/normal/461", shinyKey: "pokedex/shiny/461", silhouetteKey: "pokedex/silhouette/461")),
        PokedexSpeciesDefinition(nationalDexNumber: 462, generation: 4, slug: "magnezone", name: "Magnezone", genus: "Magnet Area Pokémon", description: "Sometimes the magnetism emitted by Magnezone is too strong, making them attract each other so they cannot move.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/462", normalKey: "pokedex/normal/462", shinyKey: "pokedex/shiny/462", silhouetteKey: "pokedex/silhouette/462")),
        PokedexSpeciesDefinition(nationalDexNumber: 463, generation: 4, slug: "lickilicky", name: "Lickilicky", genus: "Licking Pokémon", description: "It wraps things with its extensible tongue. Getting too close to it will leave you soaked with drool.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/463", normalKey: "pokedex/normal/463", shinyKey: "pokedex/shiny/463", silhouetteKey: "pokedex/silhouette/463")),
        PokedexSpeciesDefinition(nationalDexNumber: 464, generation: 4, slug: "rhyperior", name: "Rhyperior", genus: "Drill Pokémon", description: "From holes in its palms, it fires out Geodude. Its carapace can withstand volcanic eruptions.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/464", normalKey: "pokedex/normal/464", shinyKey: "pokedex/shiny/464", silhouetteKey: "pokedex/silhouette/464")),
        PokedexSpeciesDefinition(nationalDexNumber: 465, generation: 4, slug: "tangrowth", name: "Tangrowth", genus: "Vine Pokémon", description: "It ensnares prey by extending arms made of vines. Losing arms to predators does not trouble it.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/465", normalKey: "pokedex/normal/465", shinyKey: "pokedex/shiny/465", silhouetteKey: "pokedex/silhouette/465")),
        PokedexSpeciesDefinition(nationalDexNumber: 466, generation: 4, slug: "electivire", name: "Electivire", genus: "Thunderbolt Pokémon", description: "As its electric charge amplifies, blue sparks begin to crackle between its horns.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/466", normalKey: "pokedex/normal/466", shinyKey: "pokedex/shiny/466", silhouetteKey: "pokedex/silhouette/466")),
        PokedexSpeciesDefinition(nationalDexNumber: 467, generation: 4, slug: "magmortar", name: "Magmortar", genus: "Blast Pokémon", description: "It blasts fireballs of over 3,600 degrees Fahrenheit from the ends of its arms. It lives in volcanic craters.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/467", normalKey: "pokedex/normal/467", shinyKey: "pokedex/shiny/467", silhouetteKey: "pokedex/silhouette/467")),
        PokedexSpeciesDefinition(nationalDexNumber: 468, generation: 4, slug: "togekiss", name: "Togekiss", genus: "Jubilee Pokémon", description: "As everyone knows, it visits peaceful regions, bringing them gifts of kindness and sweet blessings.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/468", normalKey: "pokedex/normal/468", shinyKey: "pokedex/shiny/468", silhouetteKey: "pokedex/silhouette/468")),
        PokedexSpeciesDefinition(nationalDexNumber: 469, generation: 4, slug: "yanmega", name: "Yanmega", genus: "Ogre Darner Pokémon", description: "It prefers to battle by biting apart foes’ heads instantly while flying by at high speed.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/469", normalKey: "pokedex/normal/469", shinyKey: "pokedex/shiny/469", silhouetteKey: "pokedex/silhouette/469")),
        PokedexSpeciesDefinition(nationalDexNumber: 470, generation: 4, slug: "leafeon", name: "Leafeon", genus: "Verdant Pokémon", description: "When you see Leafeon asleep in a patch of sunshine, you’ll know it is using photosynthesis to produce clean air.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/470", normalKey: "pokedex/normal/470", shinyKey: "pokedex/shiny/470", silhouetteKey: "pokedex/silhouette/470")),
        PokedexSpeciesDefinition(nationalDexNumber: 471, generation: 4, slug: "glaceon", name: "Glaceon", genus: "Fresh Snow Pokémon", description: "By controlling its body heat, it can freeze the atmosphere around it to make a diamond-dust flurry.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/471", normalKey: "pokedex/normal/471", shinyKey: "pokedex/shiny/471", silhouetteKey: "pokedex/silhouette/471")),
        PokedexSpeciesDefinition(nationalDexNumber: 472, generation: 4, slug: "gliscor", name: "Gliscor", genus: "Fang Scorpion Pokémon", description: "It observes prey while hanging inverted from branches. When the chance presents itself, it swoops!", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/472", normalKey: "pokedex/normal/472", shinyKey: "pokedex/shiny/472", silhouetteKey: "pokedex/silhouette/472")),
        PokedexSpeciesDefinition(nationalDexNumber: 473, generation: 4, slug: "mamoswine", name: "Mamoswine", genus: "Twin Tusk Pokémon", description: "A frozen Mamoswine was dug from ice dating back 10,000 years. This Pokémon has been around a long, long, long time.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/473", normalKey: "pokedex/normal/473", shinyKey: "pokedex/shiny/473", silhouetteKey: "pokedex/silhouette/473")),
        PokedexSpeciesDefinition(nationalDexNumber: 474, generation: 4, slug: "porygon-z", name: "Porygon-Z", genus: "Virtual Pokémon", description: "Additional software was installed to make it a better Pokémon. It began acting oddly, however.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/474", normalKey: "pokedex/normal/474", shinyKey: "pokedex/shiny/474", silhouetteKey: "pokedex/silhouette/474")),
        PokedexSpeciesDefinition(nationalDexNumber: 475, generation: 4, slug: "gallade", name: "Gallade", genus: "Blade Pokémon", description: "Because it can sense what its foe is thinking, its attacks burst out first, fast, and fierce.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/475", normalKey: "pokedex/normal/475", shinyKey: "pokedex/shiny/475", silhouetteKey: "pokedex/silhouette/475")),
        PokedexSpeciesDefinition(nationalDexNumber: 476, generation: 4, slug: "probopass", name: "Probopass", genus: "Compass Pokémon", description: "It exudes strong magnetism from all over. It controls three small units called Mini-Noses.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/476", normalKey: "pokedex/normal/476", shinyKey: "pokedex/shiny/476", silhouetteKey: "pokedex/silhouette/476")),
        PokedexSpeciesDefinition(nationalDexNumber: 477, generation: 4, slug: "dusknoir", name: "Dusknoir", genus: "Gripper Pokémon", description: "It is said to take lost spirits into its pliant body and guide them home.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/477", normalKey: "pokedex/normal/477", shinyKey: "pokedex/shiny/477", silhouetteKey: "pokedex/silhouette/477")),
        PokedexSpeciesDefinition(nationalDexNumber: 478, generation: 4, slug: "froslass", name: "Froslass", genus: "Snow Land Pokémon", description: "It freezes foes with an icy breath nearly -60 degrees Fahrenheit. What seems to be its body is actually hollow.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/478", normalKey: "pokedex/normal/478", shinyKey: "pokedex/shiny/478", silhouetteKey: "pokedex/silhouette/478")),
        PokedexSpeciesDefinition(nationalDexNumber: 479, generation: 4, slug: "rotom", name: "Rotom", genus: "Plasma Pokémon", description: "Research continues on this Pokémon, which could be the power source of a unique motor.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/479", normalKey: "pokedex/normal/479", shinyKey: "pokedex/shiny/479", silhouetteKey: "pokedex/silhouette/479")),
        PokedexSpeciesDefinition(nationalDexNumber: 480, generation: 4, slug: "uxie", name: "Uxie", genus: "Knowledge Pokémon", description: "Known as “The Being of Knowledge.” It is said that it can wipe out the memory of those who see its eyes.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/480", normalKey: "pokedex/normal/480", shinyKey: "pokedex/shiny/480", silhouetteKey: "pokedex/silhouette/480")),
        PokedexSpeciesDefinition(nationalDexNumber: 481, generation: 4, slug: "mesprit", name: "Mesprit", genus: "Emotion Pokémon", description: "Known as “The Being of Emotion.” It taught humans the nobility of sorrow, pain, and joy.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/481", normalKey: "pokedex/normal/481", shinyKey: "pokedex/shiny/481", silhouetteKey: "pokedex/silhouette/481")),
        PokedexSpeciesDefinition(nationalDexNumber: 482, generation: 4, slug: "azelf", name: "Azelf", genus: "Willpower Pokémon", description: "Known as “The Being of Willpower.” It sleeps at the bottom of a lake to keep the world in balance.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/482", normalKey: "pokedex/normal/482", shinyKey: "pokedex/shiny/482", silhouetteKey: "pokedex/silhouette/482")),
        PokedexSpeciesDefinition(nationalDexNumber: 483, generation: 4, slug: "dialga", name: "Dialga", genus: "Temporal Pokémon", description: "A Pokémon spoken of in legend. It is said that time began moving when Dialga was born.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/483", normalKey: "pokedex/normal/483", shinyKey: "pokedex/shiny/483", silhouetteKey: "pokedex/silhouette/483")),
        PokedexSpeciesDefinition(nationalDexNumber: 484, generation: 4, slug: "palkia", name: "Palkia", genus: "Spatial Pokémon", description: "It is said to live in a gap in the spatial dimension parallel to ours. It appears in mythology.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/484", normalKey: "pokedex/normal/484", shinyKey: "pokedex/shiny/484", silhouetteKey: "pokedex/silhouette/484")),
        PokedexSpeciesDefinition(nationalDexNumber: 485, generation: 4, slug: "heatran", name: "Heatran", genus: "Lava Dome Pokémon", description: "It dwells in volcanic caves. It digs in with its cross-shaped feet to crawl on ceilings and walls.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/485", normalKey: "pokedex/normal/485", shinyKey: "pokedex/shiny/485", silhouetteKey: "pokedex/silhouette/485")),
        PokedexSpeciesDefinition(nationalDexNumber: 486, generation: 4, slug: "regigigas", name: "Regigigas", genus: "Colossal Pokémon", description: "It is said to have made Pokémon that look like itself from a special ice mountain, rocks, and magma.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/486", normalKey: "pokedex/normal/486", shinyKey: "pokedex/shiny/486", silhouetteKey: "pokedex/silhouette/486")),
        PokedexSpeciesDefinition(nationalDexNumber: 487, generation: 4, slug: "giratina", name: "Giratina", genus: "Renegade Pokémon", description: "This Pokémon is said to live in a world on the reverse side of ours, where common knowledge is distorted and strange.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/487", normalKey: "pokedex/normal/487", shinyKey: "pokedex/shiny/487", silhouetteKey: "pokedex/silhouette/487")),
        PokedexSpeciesDefinition(nationalDexNumber: 488, generation: 4, slug: "cresselia", name: "Cresselia", genus: "Lunar Pokémon", description: "Shiny particles are released from its wings like a veil. It is said to represent the crescent moon.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/488", normalKey: "pokedex/normal/488", shinyKey: "pokedex/shiny/488", silhouetteKey: "pokedex/silhouette/488")),
        PokedexSpeciesDefinition(nationalDexNumber: 489, generation: 4, slug: "phione", name: "Phione", genus: "Sea Drifter Pokémon", description: "When the water warms, they inflate the flotation sac on their heads and drift languidly on the sea in packs.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/489", normalKey: "pokedex/normal/489", shinyKey: "pokedex/shiny/489", silhouetteKey: "pokedex/silhouette/489")),
        PokedexSpeciesDefinition(nationalDexNumber: 490, generation: 4, slug: "manaphy", name: "Manaphy", genus: "Seafaring Pokémon", description: "It is born with a wondrous power that lets it bond with any kind of Pokémon.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/490", normalKey: "pokedex/normal/490", shinyKey: "pokedex/shiny/490", silhouetteKey: "pokedex/silhouette/490")),
        PokedexSpeciesDefinition(nationalDexNumber: 491, generation: 4, slug: "darkrai", name: "Darkrai", genus: "Pitch-Black Pokémon", description: "It chases people and Pokémon from its territory by causing them to experience deep, nightmarish slumbers.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/491", normalKey: "pokedex/normal/491", shinyKey: "pokedex/shiny/491", silhouetteKey: "pokedex/silhouette/491")),
        PokedexSpeciesDefinition(nationalDexNumber: 492, generation: 4, slug: "shaymin", name: "Shaymin", genus: "Gratitude Pokémon", description: "It can dissolve toxins in the air to instantly transform ruined land into a lush field of flowers.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/492", normalKey: "pokedex/normal/492", shinyKey: "pokedex/shiny/492", silhouetteKey: "pokedex/silhouette/492")),
        PokedexSpeciesDefinition(nationalDexNumber: 493, generation: 4, slug: "arceus", name: "Arceus", genus: "Alpha Pokémon", description: "According to the legends of Sinnoh, this Pokémon emerged from an egg and shaped all there is in this world.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/493", normalKey: "pokedex/normal/493", shinyKey: "pokedex/shiny/493", silhouetteKey: "pokedex/silhouette/493")),
        PokedexSpeciesDefinition(nationalDexNumber: 494, generation: 5, slug: "victini", name: "Victini", genus: "Victory Pokémon", description: "This Pokémon brings victory. It is said that Trainers with Victini always win, regardless of the type of encounter.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/494", normalKey: "pokedex/normal/494", shinyKey: "pokedex/shiny/494", silhouetteKey: "pokedex/silhouette/494")),
        PokedexSpeciesDefinition(nationalDexNumber: 495, generation: 5, slug: "snivy", name: "Snivy", genus: "Grass Snake Pokémon", description: "Being exposed to sunlight makes its movements swifter. It uses vines more adeptly than its hands.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/495", normalKey: "pokedex/normal/495", shinyKey: "pokedex/shiny/495", silhouetteKey: "pokedex/silhouette/495")),
        PokedexSpeciesDefinition(nationalDexNumber: 496, generation: 5, slug: "servine", name: "Servine", genus: "Grass Snake Pokémon", description: "It moves along the ground as if sliding. Its swift movements befuddle its foes, and it then attacks with a vine whip.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/496", normalKey: "pokedex/normal/496", shinyKey: "pokedex/shiny/496", silhouetteKey: "pokedex/silhouette/496")),
        PokedexSpeciesDefinition(nationalDexNumber: 497, generation: 5, slug: "serperior", name: "Serperior", genus: "Regal Pokémon", description: "It only gives its all against strong opponents who are not fazed by the glare from Serperior’s noble eyes.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/497", normalKey: "pokedex/normal/497", shinyKey: "pokedex/shiny/497", silhouetteKey: "pokedex/silhouette/497")),
        PokedexSpeciesDefinition(nationalDexNumber: 498, generation: 5, slug: "tepig", name: "Tepig", genus: "Fire Pig Pokémon", description: "It can deftly dodge its foe’s attacks while shooting fireballs from its nose. It roasts berries before it eats them.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/498", normalKey: "pokedex/normal/498", shinyKey: "pokedex/shiny/498", silhouetteKey: "pokedex/silhouette/498")),
        PokedexSpeciesDefinition(nationalDexNumber: 499, generation: 5, slug: "pignite", name: "Pignite", genus: "Fire Pig Pokémon", description: "The more it eats, the more fuel it has to make the fire in its stomach stronger. This fills it with even more power.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/499", normalKey: "pokedex/normal/499", shinyKey: "pokedex/shiny/499", silhouetteKey: "pokedex/silhouette/499")),
        PokedexSpeciesDefinition(nationalDexNumber: 500, generation: 5, slug: "emboar", name: "Emboar", genus: "Mega Fire Pig Pokémon", description: "It can throw a fire punch by setting its fists on fire with its fiery chin. It cares deeply about its friends.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/500", normalKey: "pokedex/normal/500", shinyKey: "pokedex/shiny/500", silhouetteKey: "pokedex/silhouette/500")),
        PokedexSpeciesDefinition(nationalDexNumber: 501, generation: 5, slug: "oshawott", name: "Oshawott", genus: "Sea Otter Pokémon", description: "The scalchop on its stomach isn’t just used for battle--it can be used to break open hard berries as well.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/501", normalKey: "pokedex/normal/501", shinyKey: "pokedex/shiny/501", silhouetteKey: "pokedex/silhouette/501")),
        PokedexSpeciesDefinition(nationalDexNumber: 502, generation: 5, slug: "dewott", name: "Dewott", genus: "Discipline Pokémon", description: "Strict training is how it learns its flowing double-scalchop technique.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/502", normalKey: "pokedex/normal/502", shinyKey: "pokedex/shiny/502", silhouetteKey: "pokedex/silhouette/502")),
        PokedexSpeciesDefinition(nationalDexNumber: 503, generation: 5, slug: "samurott", name: "Samurott", genus: "Formidable Pokémon", description: "In the time it takes a foe to blink, it can draw and sheathe the seamitars attached to its front legs.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/503", normalKey: "pokedex/normal/503", shinyKey: "pokedex/shiny/503", silhouetteKey: "pokedex/silhouette/503")),
        PokedexSpeciesDefinition(nationalDexNumber: 504, generation: 5, slug: "patrat", name: "Patrat", genus: "Scout Pokémon", description: "Using food stored in cheek pouches, they can keep watch for days. They use their tails to communicate with others.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/504", normalKey: "pokedex/normal/504", shinyKey: "pokedex/shiny/504", silhouetteKey: "pokedex/silhouette/504")),
        PokedexSpeciesDefinition(nationalDexNumber: 505, generation: 5, slug: "watchog", name: "Watchog", genus: "Lookout Pokémon", description: "Using luminescent matter, it makes its eyes and body glow and stuns attacking opponents.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/505", normalKey: "pokedex/normal/505", shinyKey: "pokedex/shiny/505", silhouetteKey: "pokedex/silhouette/505")),
        PokedexSpeciesDefinition(nationalDexNumber: 506, generation: 5, slug: "lillipup", name: "Lillipup", genus: "Puppy Pokémon", description: "The long hair around its face provides an amazing radar that lets it sense subtle changes in its surroundings.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/506", normalKey: "pokedex/normal/506", shinyKey: "pokedex/shiny/506", silhouetteKey: "pokedex/silhouette/506")),
        PokedexSpeciesDefinition(nationalDexNumber: 507, generation: 5, slug: "herdier", name: "Herdier", genus: "Loyal Dog Pokémon", description: "This very loyal Pokémon helps Trainers, and it also takes care of other Pokémon.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/507", normalKey: "pokedex/normal/507", shinyKey: "pokedex/shiny/507", silhouetteKey: "pokedex/silhouette/507")),
        PokedexSpeciesDefinition(nationalDexNumber: 508, generation: 5, slug: "stoutland", name: "Stoutland", genus: "Big-Hearted Pokémon", description: "It rescues people stranded by blizzards in the mountains. Its shaggy fur shields it from the cold.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/508", normalKey: "pokedex/normal/508", shinyKey: "pokedex/shiny/508", silhouetteKey: "pokedex/silhouette/508")),
        PokedexSpeciesDefinition(nationalDexNumber: 509, generation: 5, slug: "purrloin", name: "Purrloin", genus: "Devious Pokémon", description: "Its cute act is a ruse. When victims let down their guard, they find their items taken. It attacks with sharp claws.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/509", normalKey: "pokedex/normal/509", shinyKey: "pokedex/shiny/509", silhouetteKey: "pokedex/silhouette/509")),
        PokedexSpeciesDefinition(nationalDexNumber: 510, generation: 5, slug: "liepard", name: "Liepard", genus: "Cruel Pokémon", description: "Their beautiful form comes from the muscles they have developed. They run silently in the night.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/510", normalKey: "pokedex/normal/510", shinyKey: "pokedex/shiny/510", silhouetteKey: "pokedex/silhouette/510")),
        PokedexSpeciesDefinition(nationalDexNumber: 511, generation: 5, slug: "pansage", name: "Pansage", genus: "Grass Monkey Pokémon", description: "It shares the leaf on its head with weary-looking Pokémon. These leaves are known to relieve stress.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/511", normalKey: "pokedex/normal/511", shinyKey: "pokedex/shiny/511", silhouetteKey: "pokedex/silhouette/511")),
        PokedexSpeciesDefinition(nationalDexNumber: 512, generation: 5, slug: "simisage", name: "Simisage", genus: "Thorn Monkey Pokémon", description: "It attacks enemies with strikes of its thorn-covered tail. This Pokémon is wild tempered.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/512", normalKey: "pokedex/normal/512", shinyKey: "pokedex/shiny/512", silhouetteKey: "pokedex/silhouette/512")),
        PokedexSpeciesDefinition(nationalDexNumber: 513, generation: 5, slug: "pansear", name: "Pansear", genus: "High Temp Pokémon", description: "Very intelligent, it roasts berries before eating them. It likes to help people.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/513", normalKey: "pokedex/normal/513", shinyKey: "pokedex/shiny/513", silhouetteKey: "pokedex/silhouette/513")),
        PokedexSpeciesDefinition(nationalDexNumber: 514, generation: 5, slug: "simisear", name: "Simisear", genus: "Ember Pokémon", description: "A flame burns inside its body. It scatters embers from its head and tail to sear its opponents.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/514", normalKey: "pokedex/normal/514", shinyKey: "pokedex/shiny/514", silhouetteKey: "pokedex/silhouette/514")),
        PokedexSpeciesDefinition(nationalDexNumber: 515, generation: 5, slug: "panpour", name: "Panpour", genus: "Spray Pokémon", description: "The water stored inside the tuft on its head is full of nutrients. It waters plants with it using its tail.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/515", normalKey: "pokedex/normal/515", shinyKey: "pokedex/shiny/515", silhouetteKey: "pokedex/silhouette/515")),
        PokedexSpeciesDefinition(nationalDexNumber: 516, generation: 5, slug: "simipour", name: "Simipour", genus: "Geyser Pokémon", description: "The high-pressure water expelled from its tail is so powerful, it can destroy a concrete wall.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/516", normalKey: "pokedex/normal/516", shinyKey: "pokedex/shiny/516", silhouetteKey: "pokedex/silhouette/516")),
        PokedexSpeciesDefinition(nationalDexNumber: 517, generation: 5, slug: "munna", name: "Munna", genus: "Dream Eater Pokémon", description: "This Pokémon appears before people and Pokémon who are having nightmares and eats those dreams.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/517", normalKey: "pokedex/normal/517", shinyKey: "pokedex/shiny/517", silhouetteKey: "pokedex/silhouette/517")),
        PokedexSpeciesDefinition(nationalDexNumber: 518, generation: 5, slug: "musharna", name: "Musharna", genus: "Drowsing Pokémon", description: "The mist emanating from their foreheads is packed with the dreams of people and Pokémon.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/518", normalKey: "pokedex/normal/518", shinyKey: "pokedex/shiny/518", silhouetteKey: "pokedex/silhouette/518")),
        PokedexSpeciesDefinition(nationalDexNumber: 519, generation: 5, slug: "pidove", name: "Pidove", genus: "Tiny Pigeon Pokémon", description: "This very forgetful Pokémon will wait for a new order from its Trainer even though it already has one.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/519", normalKey: "pokedex/normal/519", shinyKey: "pokedex/shiny/519", silhouetteKey: "pokedex/silhouette/519")),
        PokedexSpeciesDefinition(nationalDexNumber: 520, generation: 5, slug: "tranquill", name: "Tranquill", genus: "Wild Pigeon Pokémon", description: "Many people believe that, deep in the forest where Tranquill live, there is a peaceful place where there is no war.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/520", normalKey: "pokedex/normal/520", shinyKey: "pokedex/shiny/520", silhouetteKey: "pokedex/silhouette/520")),
        PokedexSpeciesDefinition(nationalDexNumber: 521, generation: 5, slug: "unfezant", name: "Unfezant", genus: "Proud Pokémon", description: "Males swing their head plumage to threaten opponents. The females’ flying abilities surpass those of the males.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/521", normalKey: "pokedex/normal/521", shinyKey: "pokedex/shiny/521", silhouetteKey: "pokedex/silhouette/521")),
        PokedexSpeciesDefinition(nationalDexNumber: 522, generation: 5, slug: "blitzle", name: "Blitzle", genus: "Electrified Pokémon", description: "When thunderclouds cover the sky, it will appear. It can catch lightning with its mane and store the electricity.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/522", normalKey: "pokedex/normal/522", shinyKey: "pokedex/shiny/522", silhouetteKey: "pokedex/silhouette/522")),
        PokedexSpeciesDefinition(nationalDexNumber: 523, generation: 5, slug: "zebstrika", name: "Zebstrika", genus: "Thunderbolt Pokémon", description: "When this ill-tempered Pokémon runs wild, it shoots lightning from its mane in all directions.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/523", normalKey: "pokedex/normal/523", shinyKey: "pokedex/shiny/523", silhouetteKey: "pokedex/silhouette/523")),
        PokedexSpeciesDefinition(nationalDexNumber: 524, generation: 5, slug: "roggenrola", name: "Roggenrola", genus: "Mantle Pokémon", description: "Its ear is hexagonal in shape. Compressed underground, its body is as hard as steel.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/524", normalKey: "pokedex/normal/524", shinyKey: "pokedex/shiny/524", silhouetteKey: "pokedex/silhouette/524")),
        PokedexSpeciesDefinition(nationalDexNumber: 525, generation: 5, slug: "boldore", name: "Boldore", genus: "Ore Pokémon", description: "Because its energy was too great to be contained, the energy leaked and formed orange crystals.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/525", normalKey: "pokedex/normal/525", shinyKey: "pokedex/shiny/525", silhouetteKey: "pokedex/silhouette/525")),
        PokedexSpeciesDefinition(nationalDexNumber: 526, generation: 5, slug: "gigalith", name: "Gigalith", genus: "Compressed Pokémon", description: "The solar rays it absorbs are processed in its energy core and fired as a ball of light.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/526", normalKey: "pokedex/normal/526", shinyKey: "pokedex/shiny/526", silhouetteKey: "pokedex/silhouette/526")),
        PokedexSpeciesDefinition(nationalDexNumber: 527, generation: 5, slug: "woobat", name: "Woobat", genus: "Bat Pokémon", description: "Its habitat is dark forests and caves. It emits ultrasonic waves from its nose to learn about its surroundings.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/527", normalKey: "pokedex/normal/527", shinyKey: "pokedex/shiny/527", silhouetteKey: "pokedex/silhouette/527")),
        PokedexSpeciesDefinition(nationalDexNumber: 528, generation: 5, slug: "swoobat", name: "Swoobat", genus: "Courting Pokémon", description: "It shakes its tail vigorously when it emits ultrasonic waves strong enough to reduce concrete to rubble.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/528", normalKey: "pokedex/normal/528", shinyKey: "pokedex/shiny/528", silhouetteKey: "pokedex/silhouette/528")),
        PokedexSpeciesDefinition(nationalDexNumber: 529, generation: 5, slug: "drilbur", name: "Drilbur", genus: "Mole Pokémon", description: "It makes its way swiftly through the soil by putting both claws together and rotating at high speed.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/529", normalKey: "pokedex/normal/529", shinyKey: "pokedex/shiny/529", silhouetteKey: "pokedex/silhouette/529")),
        PokedexSpeciesDefinition(nationalDexNumber: 530, generation: 5, slug: "excadrill", name: "Excadrill", genus: "Subterrene Pokémon", description: "It can help in tunnel construction. Its drill has evolved into steel strong enough to bore through iron plates.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/530", normalKey: "pokedex/normal/530", shinyKey: "pokedex/shiny/530", silhouetteKey: "pokedex/silhouette/530")),
        PokedexSpeciesDefinition(nationalDexNumber: 531, generation: 5, slug: "audino", name: "Audino", genus: "Hearing Pokémon", description: "Using the feelers on its ears, it can tell how someone is feeling or when an egg might hatch.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/531", normalKey: "pokedex/normal/531", shinyKey: "pokedex/shiny/531", silhouetteKey: "pokedex/silhouette/531")),
        PokedexSpeciesDefinition(nationalDexNumber: 532, generation: 5, slug: "timburr", name: "Timburr", genus: "Muscular Pokémon", description: "These Pokémon appear at building sites and help out with construction. They always carry squared logs.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/532", normalKey: "pokedex/normal/532", shinyKey: "pokedex/shiny/532", silhouetteKey: "pokedex/silhouette/532")),
        PokedexSpeciesDefinition(nationalDexNumber: 533, generation: 5, slug: "gurdurr", name: "Gurdurr", genus: "Muscular Pokémon", description: "With strengthened bodies, they skillfully wield steel beams to take down buildings.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/533", normalKey: "pokedex/normal/533", shinyKey: "pokedex/shiny/533", silhouetteKey: "pokedex/silhouette/533")),
        PokedexSpeciesDefinition(nationalDexNumber: 534, generation: 5, slug: "conkeldurr", name: "Conkeldurr", genus: "Muscular Pokémon", description: "It is thought that Conkeldurr taught humans how to make concrete more than 2,000 years ago.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/534", normalKey: "pokedex/normal/534", shinyKey: "pokedex/shiny/534", silhouetteKey: "pokedex/silhouette/534")),
        PokedexSpeciesDefinition(nationalDexNumber: 535, generation: 5, slug: "tympole", name: "Tympole", genus: "Tadpole Pokémon", description: "By vibrating its cheeks, it emits sound waves imperceptible to humans and warns others of danger.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/535", normalKey: "pokedex/normal/535", shinyKey: "pokedex/shiny/535", silhouetteKey: "pokedex/silhouette/535")),
        PokedexSpeciesDefinition(nationalDexNumber: 536, generation: 5, slug: "palpitoad", name: "Palpitoad", genus: "Vibration Pokémon", description: "When they vibrate the bumps on their heads, they can make waves in water or earthquake-like vibrations on land.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/536", normalKey: "pokedex/normal/536", shinyKey: "pokedex/shiny/536", silhouetteKey: "pokedex/silhouette/536")),
        PokedexSpeciesDefinition(nationalDexNumber: 537, generation: 5, slug: "seismitoad", name: "Seismitoad", genus: "Vibration Pokémon", description: "It increases the power of its punches by vibrating the bumps on its fists. It can turn a boulder to rubble with one punch.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/537", normalKey: "pokedex/normal/537", shinyKey: "pokedex/shiny/537", silhouetteKey: "pokedex/silhouette/537")),
        PokedexSpeciesDefinition(nationalDexNumber: 538, generation: 5, slug: "throh", name: "Throh", genus: "Judo Pokémon", description: "When it tightens its belt, it becomes stronger. Wild Throh use vines to weave their own belts.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/538", normalKey: "pokedex/normal/538", shinyKey: "pokedex/shiny/538", silhouetteKey: "pokedex/silhouette/538")),
        PokedexSpeciesDefinition(nationalDexNumber: 539, generation: 5, slug: "sawk", name: "Sawk", genus: "Karate Pokémon", description: "Desiring the strongest karate chop, they seclude themselves in mountains and train without sleeping.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/539", normalKey: "pokedex/normal/539", shinyKey: "pokedex/shiny/539", silhouetteKey: "pokedex/silhouette/539")),
        PokedexSpeciesDefinition(nationalDexNumber: 540, generation: 5, slug: "sewaddle", name: "Sewaddle", genus: "Sewing Pokémon", description: "This Pokémon makes clothes for itself. It chews up leaves and sews them with sticky thread extruded from its mouth.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/540", normalKey: "pokedex/normal/540", shinyKey: "pokedex/shiny/540", silhouetteKey: "pokedex/silhouette/540")),
        PokedexSpeciesDefinition(nationalDexNumber: 541, generation: 5, slug: "swadloon", name: "Swadloon", genus: "Leaf-Wrapped Pokémon", description: "Forests where Swadloon live have superb foliage because the nutrients they make from fallen leaves nourish the plant life.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/541", normalKey: "pokedex/normal/541", shinyKey: "pokedex/shiny/541", silhouetteKey: "pokedex/silhouette/541")),
        PokedexSpeciesDefinition(nationalDexNumber: 542, generation: 5, slug: "leavanny", name: "Leavanny", genus: "Nurturing Pokémon", description: "Upon finding a small Pokémon, it weaves clothing for it from leaves by using the sticky silk secreted from its mouth.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/542", normalKey: "pokedex/normal/542", shinyKey: "pokedex/shiny/542", silhouetteKey: "pokedex/silhouette/542")),
        PokedexSpeciesDefinition(nationalDexNumber: 543, generation: 5, slug: "venipede", name: "Venipede", genus: "Centipede Pokémon", description: "It discovers what is going on around it by using the feelers on its head and tail. It is brutally aggressive.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/543", normalKey: "pokedex/normal/543", shinyKey: "pokedex/shiny/543", silhouetteKey: "pokedex/silhouette/543")),
        PokedexSpeciesDefinition(nationalDexNumber: 544, generation: 5, slug: "whirlipede", name: "Whirlipede", genus: "Curlipede Pokémon", description: "Protected by a hard shell, it spins its body like a wheel and crashes furiously into its enemies.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/544", normalKey: "pokedex/normal/544", shinyKey: "pokedex/shiny/544", silhouetteKey: "pokedex/silhouette/544")),
        PokedexSpeciesDefinition(nationalDexNumber: 545, generation: 5, slug: "scolipede", name: "Scolipede", genus: "Megapede Pokémon", description: "It clasps its prey with the claws on its neck until it stops moving. Then it finishes it off with deadly poison.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/545", normalKey: "pokedex/normal/545", shinyKey: "pokedex/shiny/545", silhouetteKey: "pokedex/silhouette/545")),
        PokedexSpeciesDefinition(nationalDexNumber: 546, generation: 5, slug: "cottonee", name: "Cottonee", genus: "Cotton Puff Pokémon", description: "When attacked, it escapes by shooting cotton from its body. The cotton serves as a decoy to distract the attacker.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/546", normalKey: "pokedex/normal/546", shinyKey: "pokedex/shiny/546", silhouetteKey: "pokedex/silhouette/546")),
        PokedexSpeciesDefinition(nationalDexNumber: 547, generation: 5, slug: "whimsicott", name: "Whimsicott", genus: "Windveiled Pokémon", description: "They appear along with whirlwinds. They pull pranks, such as moving furniture and leaving balls of cotton in homes.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/547", normalKey: "pokedex/normal/547", shinyKey: "pokedex/shiny/547", silhouetteKey: "pokedex/silhouette/547")),
        PokedexSpeciesDefinition(nationalDexNumber: 548, generation: 5, slug: "petilil", name: "Petilil", genus: "Bulb Pokémon", description: "The leaves on its head are very bitter. Eating one of these leaves is known to refresh a tired body.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/548", normalKey: "pokedex/normal/548", shinyKey: "pokedex/shiny/548", silhouetteKey: "pokedex/silhouette/548")),
        PokedexSpeciesDefinition(nationalDexNumber: 549, generation: 5, slug: "lilligant", name: "Lilligant", genus: "Flowering Pokémon", description: "The fragrance of the garland on its head has a relaxing effect. It withers if a Trainer does not take good care of it.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/549", normalKey: "pokedex/normal/549", shinyKey: "pokedex/shiny/549", silhouetteKey: "pokedex/silhouette/549")),
        PokedexSpeciesDefinition(nationalDexNumber: 550, generation: 5, slug: "basculin", name: "Basculin", genus: "Hostile Pokémon", description: "Red- and blue-striped Basculin are very violent and always fighting. They are also remarkably tasty.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/550", normalKey: "pokedex/normal/550", shinyKey: "pokedex/shiny/550", silhouetteKey: "pokedex/silhouette/550")),
        PokedexSpeciesDefinition(nationalDexNumber: 551, generation: 5, slug: "sandile", name: "Sandile", genus: "Desert Croc Pokémon", description: "It moves along below the sand’s surface, except for its nose and eyes. A dark membrane shields its eyes from the sun.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/551", normalKey: "pokedex/normal/551", shinyKey: "pokedex/shiny/551", silhouetteKey: "pokedex/silhouette/551")),
        PokedexSpeciesDefinition(nationalDexNumber: 552, generation: 5, slug: "krokorok", name: "Krokorok", genus: "Desert Croc Pokémon", description: "They live in groups of a few individuals. Protective membranes shield their eyes from sandstorms.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/552", normalKey: "pokedex/normal/552", shinyKey: "pokedex/shiny/552", silhouetteKey: "pokedex/silhouette/552")),
        PokedexSpeciesDefinition(nationalDexNumber: 553, generation: 5, slug: "krookodile", name: "Krookodile", genus: "Intimidation Pokémon", description: "Very violent Pokémon, they try to clamp down on anything that moves in front of their eyes.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/553", normalKey: "pokedex/normal/553", shinyKey: "pokedex/shiny/553", silhouetteKey: "pokedex/silhouette/553")),
        PokedexSpeciesDefinition(nationalDexNumber: 554, generation: 5, slug: "darumaka", name: "Darumaka", genus: "Zen Charm Pokémon", description: "Darumaka’s droppings are hot, so people used to put them in their clothes to keep themselves warm.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/554", normalKey: "pokedex/normal/554", shinyKey: "pokedex/shiny/554", silhouetteKey: "pokedex/silhouette/554")),
        PokedexSpeciesDefinition(nationalDexNumber: 555, generation: 5, slug: "darmanitan", name: "Darmanitan", genus: "Blazing Pokémon", description: "When one is injured in a fierce battle, it hardens into a stone-like form. Then it meditates and sharpens its mind.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/555", normalKey: "pokedex/normal/555", shinyKey: "pokedex/shiny/555", silhouetteKey: "pokedex/silhouette/555")),
        PokedexSpeciesDefinition(nationalDexNumber: 556, generation: 5, slug: "maractus", name: "Maractus", genus: "Cactus Pokémon", description: "It uses an up-tempo song and dance to drive away the bird Pokémon that prey on its flower seeds.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/556", normalKey: "pokedex/normal/556", shinyKey: "pokedex/shiny/556", silhouetteKey: "pokedex/silhouette/556")),
        PokedexSpeciesDefinition(nationalDexNumber: 557, generation: 5, slug: "dwebble", name: "Dwebble", genus: "Rock Inn Pokémon", description: "It makes a hole in a suitable rock. If that rock breaks, the Pokémon remains agitated until it locates a replacement.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/557", normalKey: "pokedex/normal/557", shinyKey: "pokedex/shiny/557", silhouetteKey: "pokedex/silhouette/557")),
        PokedexSpeciesDefinition(nationalDexNumber: 558, generation: 5, slug: "crustle", name: "Crustle", genus: "Stone Home Pokémon", description: "It possesses legs of enormous strength, enabling it to carry heavy slabs for many days, even when crossing arid land.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/558", normalKey: "pokedex/normal/558", shinyKey: "pokedex/shiny/558", silhouetteKey: "pokedex/silhouette/558")),
        PokedexSpeciesDefinition(nationalDexNumber: 559, generation: 5, slug: "scraggy", name: "Scraggy", genus: "Shedding Pokémon", description: "Its skin has a rubbery elasticity, so it can reduce damage by defensively pulling its skin up to its neck.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/559", normalKey: "pokedex/normal/559", shinyKey: "pokedex/shiny/559", silhouetteKey: "pokedex/silhouette/559")),
        PokedexSpeciesDefinition(nationalDexNumber: 560, generation: 5, slug: "scrafty", name: "Scrafty", genus: "Hoodlum Pokémon", description: "It pulls up its shed skin to protect itself while it kicks. The bigger the crest, the more respected it is.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/560", normalKey: "pokedex/normal/560", shinyKey: "pokedex/shiny/560", silhouetteKey: "pokedex/silhouette/560")),
        PokedexSpeciesDefinition(nationalDexNumber: 561, generation: 5, slug: "sigilyph", name: "Sigilyph", genus: "Avianoid Pokémon", description: "The guardians of an ancient city, they use their psychic power to attack enemies that invade their territory.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/561", normalKey: "pokedex/normal/561", shinyKey: "pokedex/shiny/561", silhouetteKey: "pokedex/silhouette/561")),
        PokedexSpeciesDefinition(nationalDexNumber: 562, generation: 5, slug: "yamask", name: "Yamask", genus: "Spirit Pokémon", description: "These Pokémon arose from the spirits of people interred in graves. Each retains memories of its former life.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/562", normalKey: "pokedex/normal/562", shinyKey: "pokedex/shiny/562", silhouetteKey: "pokedex/silhouette/562")),
        PokedexSpeciesDefinition(nationalDexNumber: 563, generation: 5, slug: "cofagrigus", name: "Cofagrigus", genus: "Coffin Pokémon", description: "It has been said that they swallow those who get too close and turn them into mummies. They like to eat gold nuggets.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/563", normalKey: "pokedex/normal/563", shinyKey: "pokedex/shiny/563", silhouetteKey: "pokedex/silhouette/563")),
        PokedexSpeciesDefinition(nationalDexNumber: 564, generation: 5, slug: "tirtouga", name: "Tirtouga", genus: "Prototurtle Pokémon", description: "About 100 million years ago, these Pokémon swam in oceans. It is thought they also went on land to attack prey.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/564", normalKey: "pokedex/normal/564", shinyKey: "pokedex/shiny/564", silhouetteKey: "pokedex/silhouette/564")),
        PokedexSpeciesDefinition(nationalDexNumber: 565, generation: 5, slug: "carracosta", name: "Carracosta", genus: "Prototurtle Pokémon", description: "They can live both in the ocean and on land. A slap from one of them is enough to open a hole in the bottom of a tanker.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/565", normalKey: "pokedex/normal/565", shinyKey: "pokedex/shiny/565", silhouetteKey: "pokedex/silhouette/565")),
        PokedexSpeciesDefinition(nationalDexNumber: 566, generation: 5, slug: "archen", name: "Archen", genus: "First Bird Pokémon", description: "Revived from a fossil, this Pokémon is thought to be the ancestor of all bird Pokémon.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/566", normalKey: "pokedex/normal/566", shinyKey: "pokedex/shiny/566", silhouetteKey: "pokedex/silhouette/566")),
        PokedexSpeciesDefinition(nationalDexNumber: 567, generation: 5, slug: "archeops", name: "Archeops", genus: "First Bird Pokémon", description: "They are intelligent and will cooperate to catch prey. From the ground, they use a running start to take flight.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/567", normalKey: "pokedex/normal/567", shinyKey: "pokedex/shiny/567", silhouetteKey: "pokedex/silhouette/567")),
        PokedexSpeciesDefinition(nationalDexNumber: 568, generation: 5, slug: "trubbish", name: "Trubbish", genus: "Trash Bag Pokémon", description: "The combination of garbage bags and industrial waste caused the chemical reaction that created this Pokémon.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/568", normalKey: "pokedex/normal/568", shinyKey: "pokedex/shiny/568", silhouetteKey: "pokedex/silhouette/568")),
        PokedexSpeciesDefinition(nationalDexNumber: 569, generation: 5, slug: "garbodor", name: "Garbodor", genus: "Trash Heap Pokémon", description: "It clenches opponents with its left arm and finishes them off with foul-smelling poison gas belched from its mouth.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/569", normalKey: "pokedex/normal/569", shinyKey: "pokedex/shiny/569", silhouetteKey: "pokedex/silhouette/569")),
        PokedexSpeciesDefinition(nationalDexNumber: 570, generation: 5, slug: "zorua", name: "Zorua", genus: "Tricky Fox Pokémon", description: "It changes so it looks just like its foe, tricks it, and then uses that opportunity to flee.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/570", normalKey: "pokedex/normal/570", shinyKey: "pokedex/shiny/570", silhouetteKey: "pokedex/silhouette/570")),
        PokedexSpeciesDefinition(nationalDexNumber: 571, generation: 5, slug: "zoroark", name: "Zoroark", genus: "Illusion Fox Pokémon", description: "Each has the ability to fool a large group of people simultaneously. They protect their lair with illusory scenery.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/571", normalKey: "pokedex/normal/571", shinyKey: "pokedex/shiny/571", silhouetteKey: "pokedex/silhouette/571")),
        PokedexSpeciesDefinition(nationalDexNumber: 572, generation: 5, slug: "minccino", name: "Minccino", genus: "Chinchilla Pokémon", description: "Minccino greet each other by grooming one another thoroughly with their tails.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/572", normalKey: "pokedex/normal/572", shinyKey: "pokedex/shiny/572", silhouetteKey: "pokedex/silhouette/572")),
        PokedexSpeciesDefinition(nationalDexNumber: 573, generation: 5, slug: "cinccino", name: "Cinccino", genus: "Scarf Pokémon", description: "Their white fur feels amazing to touch. Their fur repels dust and prevents static electricity from building up.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/573", normalKey: "pokedex/normal/573", shinyKey: "pokedex/shiny/573", silhouetteKey: "pokedex/silhouette/573")),
        PokedexSpeciesDefinition(nationalDexNumber: 574, generation: 5, slug: "gothita", name: "Gothita", genus: "Fixation Pokémon", description: "Their ribbonlike feelers increase their psychic power. They are always staring at something.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/574", normalKey: "pokedex/normal/574", shinyKey: "pokedex/shiny/574", silhouetteKey: "pokedex/silhouette/574")),
        PokedexSpeciesDefinition(nationalDexNumber: 575, generation: 5, slug: "gothorita", name: "Gothorita", genus: "Manipulate Pokémon", description: "Starlight is the source of their power. At night, they mark star positions by using psychic power to float stones.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/575", normalKey: "pokedex/normal/575", shinyKey: "pokedex/shiny/575", silhouetteKey: "pokedex/silhouette/575")),
        PokedexSpeciesDefinition(nationalDexNumber: 576, generation: 5, slug: "gothitelle", name: "Gothitelle", genus: "Astral Body Pokémon", description: "Starry skies thousands of light-years away are visible in the space distorted by their intense psychic power.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/576", normalKey: "pokedex/normal/576", shinyKey: "pokedex/shiny/576", silhouetteKey: "pokedex/silhouette/576")),
        PokedexSpeciesDefinition(nationalDexNumber: 577, generation: 5, slug: "solosis", name: "Solosis", genus: "Cell Pokémon", description: "Because their bodies are enveloped in a special liquid, they are fine in any environment, no matter how severe.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/577", normalKey: "pokedex/normal/577", shinyKey: "pokedex/shiny/577", silhouetteKey: "pokedex/silhouette/577")),
        PokedexSpeciesDefinition(nationalDexNumber: 578, generation: 5, slug: "duosion", name: "Duosion", genus: "Mitosis Pokémon", description: "Since they have two divided brains, at times they suddenly try to take two different actions at once.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/578", normalKey: "pokedex/normal/578", shinyKey: "pokedex/shiny/578", silhouetteKey: "pokedex/silhouette/578")),
        PokedexSpeciesDefinition(nationalDexNumber: 579, generation: 5, slug: "reuniclus", name: "Reuniclus", genus: "Multiplying Pokémon", description: "They use psychic power to control their arms, which are made of a special liquid. They can crush boulders psychically.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/579", normalKey: "pokedex/normal/579", shinyKey: "pokedex/shiny/579", silhouetteKey: "pokedex/silhouette/579")),
        PokedexSpeciesDefinition(nationalDexNumber: 580, generation: 5, slug: "ducklett", name: "Ducklett", genus: "Water Bird Pokémon", description: "When attacked, it uses its feathers to splash water, escaping under cover of the spray.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/580", normalKey: "pokedex/normal/580", shinyKey: "pokedex/shiny/580", silhouetteKey: "pokedex/silhouette/580")),
        PokedexSpeciesDefinition(nationalDexNumber: 581, generation: 5, slug: "swanna", name: "Swanna", genus: "White Bird Pokémon", description: "Despite their elegant appearance, they can flap their wings strongly and fly for thousands of miles.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/581", normalKey: "pokedex/normal/581", shinyKey: "pokedex/shiny/581", silhouetteKey: "pokedex/silhouette/581")),
        PokedexSpeciesDefinition(nationalDexNumber: 582, generation: 5, slug: "vanillite", name: "Vanillite", genus: "Fresh Snow Pokémon", description: "The temperature of their breath is -58 degrees Fahrenheit. They create snow crystals and make snow fall in the areas around them.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/582", normalKey: "pokedex/normal/582", shinyKey: "pokedex/shiny/582", silhouetteKey: "pokedex/silhouette/582")),
        PokedexSpeciesDefinition(nationalDexNumber: 583, generation: 5, slug: "vanillish", name: "Vanillish", genus: "Icy Snow Pokémon", description: "They cool down the surrounding air and create ice particles, which they use to freeze their foes.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/583", normalKey: "pokedex/normal/583", shinyKey: "pokedex/shiny/583", silhouetteKey: "pokedex/silhouette/583")),
        PokedexSpeciesDefinition(nationalDexNumber: 584, generation: 5, slug: "vanilluxe", name: "Vanilluxe", genus: "Snowstorm Pokémon", description: "If both heads get angry simultaneously, this Pokémon expels a blizzard, burying everything in snow.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/584", normalKey: "pokedex/normal/584", shinyKey: "pokedex/shiny/584", silhouetteKey: "pokedex/silhouette/584")),
        PokedexSpeciesDefinition(nationalDexNumber: 585, generation: 5, slug: "deerling", name: "Deerling", genus: "Season Pokémon", description: "Their coloring changes according to the seasons and can be slightly affected by the temperature and humidity as well.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/585", normalKey: "pokedex/normal/585", shinyKey: "pokedex/shiny/585", silhouetteKey: "pokedex/silhouette/585")),
        PokedexSpeciesDefinition(nationalDexNumber: 586, generation: 5, slug: "sawsbuck", name: "Sawsbuck", genus: "Season Pokémon", description: "They migrate according to the seasons. People can tell the season by looking at Sawsbuck’s horns.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/586", normalKey: "pokedex/normal/586", shinyKey: "pokedex/shiny/586", silhouetteKey: "pokedex/silhouette/586")),
        PokedexSpeciesDefinition(nationalDexNumber: 587, generation: 5, slug: "emolga", name: "Emolga", genus: "Sky Squirrel Pokémon", description: "They live on treetops and glide using the inside of a cape-like membrane while discharging electricity.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/587", normalKey: "pokedex/normal/587", shinyKey: "pokedex/shiny/587", silhouetteKey: "pokedex/silhouette/587")),
        PokedexSpeciesDefinition(nationalDexNumber: 588, generation: 5, slug: "karrablast", name: "Karrablast", genus: "Clamping Pokémon", description: "These mysterious Pokémon evolve when they receive electrical stimulation while they are in the same place as Shelmet.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/588", normalKey: "pokedex/normal/588", shinyKey: "pokedex/shiny/588", silhouetteKey: "pokedex/silhouette/588")),
        PokedexSpeciesDefinition(nationalDexNumber: 589, generation: 5, slug: "escavalier", name: "Escavalier", genus: "Cavalry Pokémon", description: "Wearing the shell covering they stole from Shelmet, they defend themselves and attack with two lances.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/589", normalKey: "pokedex/normal/589", shinyKey: "pokedex/shiny/589", silhouetteKey: "pokedex/silhouette/589")),
        PokedexSpeciesDefinition(nationalDexNumber: 590, generation: 5, slug: "foongus", name: "Foongus", genus: "Mushroom Pokémon", description: "It lures people in with its Poké Ball pattern, then releases poison spores. Why it resembles a Poké Ball is unknown.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/590", normalKey: "pokedex/normal/590", shinyKey: "pokedex/shiny/590", silhouetteKey: "pokedex/silhouette/590")),
        PokedexSpeciesDefinition(nationalDexNumber: 591, generation: 5, slug: "amoonguss", name: "Amoonguss", genus: "Mushroom Pokémon", description: "They show off their Poké Ball caps to lure prey, but very few Pokémon are fooled by this.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/591", normalKey: "pokedex/normal/591", shinyKey: "pokedex/shiny/591", silhouetteKey: "pokedex/silhouette/591")),
        PokedexSpeciesDefinition(nationalDexNumber: 592, generation: 5, slug: "frillish", name: "Frillish", genus: "Floating Pokémon", description: "They paralyze prey with poison, then drag them down to their lairs, five miles below the surface.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/592", normalKey: "pokedex/normal/592", shinyKey: "pokedex/shiny/592", silhouetteKey: "pokedex/silhouette/592")),
        PokedexSpeciesDefinition(nationalDexNumber: 593, generation: 5, slug: "jellicent", name: "Jellicent", genus: "Floating Pokémon", description: "Its body is mostly seawater. It’s said there’s a castle of ships Jellicent have sunk on the seafloor.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/593", normalKey: "pokedex/normal/593", shinyKey: "pokedex/shiny/593", silhouetteKey: "pokedex/silhouette/593")),
        PokedexSpeciesDefinition(nationalDexNumber: 594, generation: 5, slug: "alomomola", name: "Alomomola", genus: "Caring Pokémon", description: "Floating in the open sea is how they live. When they find a wounded Pokémon, they embrace it and bring it to shore.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/594", normalKey: "pokedex/normal/594", shinyKey: "pokedex/shiny/594", silhouetteKey: "pokedex/silhouette/594")),
        PokedexSpeciesDefinition(nationalDexNumber: 595, generation: 5, slug: "joltik", name: "Joltik", genus: "Attaching Pokémon", description: "Since it can’t generate its own electricity, it sticks onto large-bodied Pokémon and absorbs static electricity.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/595", normalKey: "pokedex/normal/595", shinyKey: "pokedex/shiny/595", silhouetteKey: "pokedex/silhouette/595")),
        PokedexSpeciesDefinition(nationalDexNumber: 596, generation: 5, slug: "galvantula", name: "Galvantula", genus: "EleSpider Pokémon", description: "They employ an electrically charged web to trap their prey. While it is immobilized by shock, they leisurely consume it.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/596", normalKey: "pokedex/normal/596", shinyKey: "pokedex/shiny/596", silhouetteKey: "pokedex/silhouette/596")),
        PokedexSpeciesDefinition(nationalDexNumber: 597, generation: 5, slug: "ferroseed", name: "Ferroseed", genus: "Thorn Seed Pokémon", description: "When threatened, it attacks by shooting a barrage of spikes, which gives it a chance to escape by rolling away.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/597", normalKey: "pokedex/normal/597", shinyKey: "pokedex/shiny/597", silhouetteKey: "pokedex/silhouette/597")),
        PokedexSpeciesDefinition(nationalDexNumber: 598, generation: 5, slug: "ferrothorn", name: "Ferrothorn", genus: "Thorn Pod Pokémon", description: "By swinging around its three spiky feelers and shooting spikes, it can obliterate an opponent.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/598", normalKey: "pokedex/normal/598", shinyKey: "pokedex/shiny/598", silhouetteKey: "pokedex/silhouette/598")),
        PokedexSpeciesDefinition(nationalDexNumber: 599, generation: 5, slug: "klink", name: "Klink", genus: "Gear Pokémon", description: "Interlocking two bodies and spinning around generates the energy they need to live.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/599", normalKey: "pokedex/normal/599", shinyKey: "pokedex/shiny/599", silhouetteKey: "pokedex/silhouette/599")),
        PokedexSpeciesDefinition(nationalDexNumber: 600, generation: 5, slug: "klang", name: "Klang", genus: "Gear Pokémon", description: "By changing the direction in which it rotates, it communicates its feelings to others. When angry, it rotates faster.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/600", normalKey: "pokedex/normal/600", shinyKey: "pokedex/shiny/600", silhouetteKey: "pokedex/silhouette/600")),
        PokedexSpeciesDefinition(nationalDexNumber: 601, generation: 5, slug: "klinklang", name: "Klinklang", genus: "Gear Pokémon", description: "The gear with the red core is rotated at high speed for a rapid energy charge.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/601", normalKey: "pokedex/normal/601", shinyKey: "pokedex/shiny/601", silhouetteKey: "pokedex/silhouette/601")),
        PokedexSpeciesDefinition(nationalDexNumber: 602, generation: 5, slug: "tynamo", name: "Tynamo", genus: "EleFish Pokémon", description: "While one alone doesn’t have much power, a chain of many Tynamo can be as powerful as lightning.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/602", normalKey: "pokedex/normal/602", shinyKey: "pokedex/shiny/602", silhouetteKey: "pokedex/silhouette/602")),
        PokedexSpeciesDefinition(nationalDexNumber: 603, generation: 5, slug: "eelektrik", name: "Eelektrik", genus: "EleFish Pokémon", description: "It wraps itself around its prey and paralyzes it with electricity from the round spots on its sides. Then it chomps.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/603", normalKey: "pokedex/normal/603", shinyKey: "pokedex/shiny/603", silhouetteKey: "pokedex/silhouette/603")),
        PokedexSpeciesDefinition(nationalDexNumber: 604, generation: 5, slug: "eelektross", name: "Eelektross", genus: "EleFish Pokémon", description: "With their sucker mouths, they suck in prey. Then they use their fangs to shock the prey with electricity.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/604", normalKey: "pokedex/normal/604", shinyKey: "pokedex/shiny/604", silhouetteKey: "pokedex/silhouette/604")),
        PokedexSpeciesDefinition(nationalDexNumber: 605, generation: 5, slug: "elgyem", name: "Elgyem", genus: "Cerebral Pokémon", description: "It uses its strong psychic power to squeeze its opponent’s brain, causing unendurable headaches.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/605", normalKey: "pokedex/normal/605", shinyKey: "pokedex/shiny/605", silhouetteKey: "pokedex/silhouette/605")),
        PokedexSpeciesDefinition(nationalDexNumber: 606, generation: 5, slug: "beheeyem", name: "Beheeyem", genus: "Cerebral Pokémon", description: "Apparently, it communicates by flashing its three fingers, but those patterns haven’t been decoded.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/606", normalKey: "pokedex/normal/606", shinyKey: "pokedex/shiny/606", silhouetteKey: "pokedex/silhouette/606")),
        PokedexSpeciesDefinition(nationalDexNumber: 607, generation: 5, slug: "litwick", name: "Litwick", genus: "Candle Pokémon", description: "While shining a light and pretending to be a guide, it leeches off the life force of any who follow it.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/607", normalKey: "pokedex/normal/607", shinyKey: "pokedex/shiny/607", silhouetteKey: "pokedex/silhouette/607")),
        PokedexSpeciesDefinition(nationalDexNumber: 608, generation: 5, slug: "lampent", name: "Lampent", genus: "Lamp Pokémon", description: "The spirits it absorbs fuel its baleful fire. It hangs around hospitals waiting for people to pass on.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/608", normalKey: "pokedex/normal/608", shinyKey: "pokedex/shiny/608", silhouetteKey: "pokedex/silhouette/608")),
        PokedexSpeciesDefinition(nationalDexNumber: 609, generation: 5, slug: "chandelure", name: "Chandelure", genus: "Luring Pokémon", description: "Being consumed in Chandelure’s flame burns up the spirit, leaving the body behind.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/609", normalKey: "pokedex/normal/609", shinyKey: "pokedex/shiny/609", silhouetteKey: "pokedex/silhouette/609")),
        PokedexSpeciesDefinition(nationalDexNumber: 610, generation: 5, slug: "axew", name: "Axew", genus: "Tusk Pokémon", description: "They use their tusks to crush the berries they eat. Repeated regrowth makes their tusks strong and sharp.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/610", normalKey: "pokedex/normal/610", shinyKey: "pokedex/shiny/610", silhouetteKey: "pokedex/silhouette/610")),
        PokedexSpeciesDefinition(nationalDexNumber: 611, generation: 5, slug: "fraxure", name: "Fraxure", genus: "Axe Jaw Pokémon", description: "Their tusks can shatter rocks. Territory battles between Fraxure can be intensely violent.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/611", normalKey: "pokedex/normal/611", shinyKey: "pokedex/shiny/611", silhouetteKey: "pokedex/silhouette/611")),
        PokedexSpeciesDefinition(nationalDexNumber: 612, generation: 5, slug: "haxorus", name: "Haxorus", genus: "Axe Jaw Pokémon", description: "They are kind but can be relentless when defending territory. They challenge foes with tusks that can cut steel.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/612", normalKey: "pokedex/normal/612", shinyKey: "pokedex/shiny/612", silhouetteKey: "pokedex/silhouette/612")),
        PokedexSpeciesDefinition(nationalDexNumber: 613, generation: 5, slug: "cubchoo", name: "Cubchoo", genus: "Chill Pokémon", description: "Its nose is always running. It sniffs the snot back up because the mucus provides the raw material for its moves.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/613", normalKey: "pokedex/normal/613", shinyKey: "pokedex/shiny/613", silhouetteKey: "pokedex/silhouette/613")),
        PokedexSpeciesDefinition(nationalDexNumber: 614, generation: 5, slug: "beartic", name: "Beartic", genus: "Freezing Pokémon", description: "They love the cold seas of the north. They create pathways across the ocean waters by freezing their own breath.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/614", normalKey: "pokedex/normal/614", shinyKey: "pokedex/shiny/614", silhouetteKey: "pokedex/silhouette/614")),
        PokedexSpeciesDefinition(nationalDexNumber: 615, generation: 5, slug: "cryogonal", name: "Cryogonal", genus: "Crystallizing Pokémon", description: "They are born in snow clouds. They use chains made of ice crystals to capture prey.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/615", normalKey: "pokedex/normal/615", shinyKey: "pokedex/shiny/615", silhouetteKey: "pokedex/silhouette/615")),
        PokedexSpeciesDefinition(nationalDexNumber: 616, generation: 5, slug: "shelmet", name: "Shelmet", genus: "Snail Pokémon", description: "When it and Karrablast are together, and both receive electrical stimulation, they both evolve.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/616", normalKey: "pokedex/normal/616", shinyKey: "pokedex/shiny/616", silhouetteKey: "pokedex/silhouette/616")),
        PokedexSpeciesDefinition(nationalDexNumber: 617, generation: 5, slug: "accelgor", name: "Accelgor", genus: "Shell Out Pokémon", description: "Having removed its heavy shell, it becomes very light and can fight with ninja-like movements.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/617", normalKey: "pokedex/normal/617", shinyKey: "pokedex/shiny/617", silhouetteKey: "pokedex/silhouette/617")),
        PokedexSpeciesDefinition(nationalDexNumber: 618, generation: 5, slug: "stunfisk", name: "Stunfisk", genus: "Trap Pokémon", description: "Its skin is very hard, so it is unhurt even if stepped on by sumo wrestlers. It smiles when transmitting electricity.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/618", normalKey: "pokedex/normal/618", shinyKey: "pokedex/shiny/618", silhouetteKey: "pokedex/silhouette/618")),
        PokedexSpeciesDefinition(nationalDexNumber: 619, generation: 5, slug: "mienfoo", name: "Mienfoo", genus: "Martial Arts Pokémon", description: "It takes pride in the speed at which it can use moves. What it loses in power, it makes up for in quantity.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/619", normalKey: "pokedex/normal/619", shinyKey: "pokedex/shiny/619", silhouetteKey: "pokedex/silhouette/619")),
        PokedexSpeciesDefinition(nationalDexNumber: 620, generation: 5, slug: "mienshao", name: "Mienshao", genus: "Martial Arts Pokémon", description: "It wields the fur on its arms like a whip. Its arm attacks come with such rapidity that they cannot even be seen.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/620", normalKey: "pokedex/normal/620", shinyKey: "pokedex/shiny/620", silhouetteKey: "pokedex/silhouette/620")),
        PokedexSpeciesDefinition(nationalDexNumber: 621, generation: 5, slug: "druddigon", name: "Druddigon", genus: "Cave Pokémon", description: "It races through narrow caves, using its sharp claws to catch prey. The skin on its face is harder than a rock.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/621", normalKey: "pokedex/normal/621", shinyKey: "pokedex/shiny/621", silhouetteKey: "pokedex/silhouette/621")),
        PokedexSpeciesDefinition(nationalDexNumber: 622, generation: 5, slug: "golett", name: "Golett", genus: "Automaton Pokémon", description: "The energy that burns inside it enables it to move, but no one has yet been able to identify this energy.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/622", normalKey: "pokedex/normal/622", shinyKey: "pokedex/shiny/622", silhouetteKey: "pokedex/silhouette/622")),
        PokedexSpeciesDefinition(nationalDexNumber: 623, generation: 5, slug: "golurk", name: "Golurk", genus: "Automaton Pokémon", description: "It is said that Golurk were ordered to protect people and Pokémon by the ancient people who made them.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/623", normalKey: "pokedex/normal/623", shinyKey: "pokedex/shiny/623", silhouetteKey: "pokedex/silhouette/623")),
        PokedexSpeciesDefinition(nationalDexNumber: 624, generation: 5, slug: "pawniard", name: "Pawniard", genus: "Sharp Blade Pokémon", description: "Blades comprise this Pokémon’s entire body. If battling dulls the blades, it sharpens them on stones by the river.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/624", normalKey: "pokedex/normal/624", shinyKey: "pokedex/shiny/624", silhouetteKey: "pokedex/silhouette/624")),
        PokedexSpeciesDefinition(nationalDexNumber: 625, generation: 5, slug: "bisharp", name: "Bisharp", genus: "Sword Blade Pokémon", description: "This pitiless Pokémon commands a group of Pawniard to hound prey into immobility. It then moves in to finish the prey off.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/625", normalKey: "pokedex/normal/625", shinyKey: "pokedex/shiny/625", silhouetteKey: "pokedex/silhouette/625")),
        PokedexSpeciesDefinition(nationalDexNumber: 626, generation: 5, slug: "bouffalant", name: "Bouffalant", genus: "Bash Buffalo Pokémon", description: "They charge wildly and headbutt everything. Their headbutts have enough destructive force to derail a train.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/626", normalKey: "pokedex/normal/626", shinyKey: "pokedex/shiny/626", silhouetteKey: "pokedex/silhouette/626")),
        PokedexSpeciesDefinition(nationalDexNumber: 627, generation: 5, slug: "rufflet", name: "Rufflet", genus: "Eaglet Pokémon", description: "They crush berries with their talons. They bravely stand up to any opponent, no matter how strong it is.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/627", normalKey: "pokedex/normal/627", shinyKey: "pokedex/shiny/627", silhouetteKey: "pokedex/silhouette/627")),
        PokedexSpeciesDefinition(nationalDexNumber: 628, generation: 5, slug: "braviary", name: "Braviary", genus: "Valiant Pokémon", description: "For the sake of its friends, this brave warrior of the sky will not stop battling, even if injured.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/628", normalKey: "pokedex/normal/628", shinyKey: "pokedex/shiny/628", silhouetteKey: "pokedex/silhouette/628")),
        PokedexSpeciesDefinition(nationalDexNumber: 629, generation: 5, slug: "vullaby", name: "Vullaby", genus: "Diapered Pokémon", description: "Its wings are too tiny to allow it to fly. As the time approaches for it to evolve, it discards the bones it was wearing.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/629", normalKey: "pokedex/normal/629", shinyKey: "pokedex/shiny/629", silhouetteKey: "pokedex/silhouette/629")),
        PokedexSpeciesDefinition(nationalDexNumber: 630, generation: 5, slug: "mandibuzz", name: "Mandibuzz", genus: "Bone Vulture Pokémon", description: "They fly in circles around the sky. When they spot prey, they attack and carry it back to their nest with ease.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/630", normalKey: "pokedex/normal/630", shinyKey: "pokedex/shiny/630", silhouetteKey: "pokedex/silhouette/630")),
        PokedexSpeciesDefinition(nationalDexNumber: 631, generation: 5, slug: "heatmor", name: "Heatmor", genus: "Anteater Pokémon", description: "Using their very hot, flame-covered tongues, they burn through Durant’s steel bodies and consume their insides.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/631", normalKey: "pokedex/normal/631", shinyKey: "pokedex/shiny/631", silhouetteKey: "pokedex/silhouette/631")),
        PokedexSpeciesDefinition(nationalDexNumber: 632, generation: 5, slug: "durant", name: "Durant", genus: "Iron Ant Pokémon", description: "Individuals each play different roles in driving Heatmor, their natural predator, away from their colony.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/632", normalKey: "pokedex/normal/632", shinyKey: "pokedex/shiny/632", silhouetteKey: "pokedex/silhouette/632")),
        PokedexSpeciesDefinition(nationalDexNumber: 633, generation: 5, slug: "deino", name: "Deino", genus: "Irate Pokémon", description: "They cannot see, so they tackle and bite to learn about their surroundings. Their bodies are covered in wounds.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/633", normalKey: "pokedex/normal/633", shinyKey: "pokedex/shiny/633", silhouetteKey: "pokedex/silhouette/633")),
        PokedexSpeciesDefinition(nationalDexNumber: 634, generation: 5, slug: "zweilous", name: "Zweilous", genus: "Hostile Pokémon", description: "The two heads do not get along. Whichever head eats more than the other gets to be the leader.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/634", normalKey: "pokedex/normal/634", shinyKey: "pokedex/shiny/634", silhouetteKey: "pokedex/silhouette/634")),
        PokedexSpeciesDefinition(nationalDexNumber: 635, generation: 5, slug: "hydreigon", name: "Hydreigon", genus: "Brutal Pokémon", description: "The heads on their arms do not have brains. They use all three heads to consume and destroy everything.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/635", normalKey: "pokedex/normal/635", shinyKey: "pokedex/shiny/635", silhouetteKey: "pokedex/silhouette/635")),
        PokedexSpeciesDefinition(nationalDexNumber: 636, generation: 5, slug: "larvesta", name: "Larvesta", genus: "Torch Pokémon", description: "Said to have been born from the sun, it spews fire from its horns and encases itself in a cocoon of fire when it evolves.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/636", normalKey: "pokedex/normal/636", shinyKey: "pokedex/shiny/636", silhouetteKey: "pokedex/silhouette/636")),
        PokedexSpeciesDefinition(nationalDexNumber: 637, generation: 5, slug: "volcarona", name: "Volcarona", genus: "Sun Pokémon", description: "A sea of fire engulfs the surroundings of their battles, since they use their six wings to scatter their ember scales.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/637", normalKey: "pokedex/normal/637", shinyKey: "pokedex/shiny/637", silhouetteKey: "pokedex/silhouette/637")),
        PokedexSpeciesDefinition(nationalDexNumber: 638, generation: 5, slug: "cobalion", name: "Cobalion", genus: "Iron Will Pokémon", description: "It has a body and heart of steel. Its glare is sufficient to make even an unruly Pokémon obey it.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/638", normalKey: "pokedex/normal/638", shinyKey: "pokedex/shiny/638", silhouetteKey: "pokedex/silhouette/638")),
        PokedexSpeciesDefinition(nationalDexNumber: 639, generation: 5, slug: "terrakion", name: "Terrakion", genus: "Cavern Pokémon", description: "Its charge is strong enough to break through a giant castle wall in one blow. This Pokémon is spoken of in legends.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/639", normalKey: "pokedex/normal/639", shinyKey: "pokedex/shiny/639", silhouetteKey: "pokedex/silhouette/639")),
        PokedexSpeciesDefinition(nationalDexNumber: 640, generation: 5, slug: "virizion", name: "Virizion", genus: "Grassland Pokémon", description: "Its head sprouts horns as sharp as blades. Using whirlwind-like movements, it confounds and swiftly cuts opponents.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/640", normalKey: "pokedex/normal/640", shinyKey: "pokedex/shiny/640", silhouetteKey: "pokedex/silhouette/640")),
        PokedexSpeciesDefinition(nationalDexNumber: 641, generation: 5, slug: "tornadus", name: "Tornadus", genus: "Cyclone Pokémon", description: "The lower half of its body is wrapped in a cloud of energy. It zooms through the sky at 200 mph.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/641", normalKey: "pokedex/normal/641", shinyKey: "pokedex/shiny/641", silhouetteKey: "pokedex/silhouette/641")),
        PokedexSpeciesDefinition(nationalDexNumber: 642, generation: 5, slug: "thundurus", name: "Thundurus", genus: "Bolt Strike Pokémon", description: "The spikes on its tail discharge immense bolts of lightning. It flies around the Unova region firing off lightning bolts.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/642", normalKey: "pokedex/normal/642", shinyKey: "pokedex/shiny/642", silhouetteKey: "pokedex/silhouette/642")),
        PokedexSpeciesDefinition(nationalDexNumber: 643, generation: 5, slug: "reshiram", name: "Reshiram", genus: "Vast White Pokémon", description: "This legendary Pokémon can scorch the world with fire. It helps those who want to build a world of truth.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/643", normalKey: "pokedex/normal/643", shinyKey: "pokedex/shiny/643", silhouetteKey: "pokedex/silhouette/643")),
        PokedexSpeciesDefinition(nationalDexNumber: 644, generation: 5, slug: "zekrom", name: "Zekrom", genus: "Deep Black Pokémon", description: "This legendary Pokémon can scorch the world with lightning. It assists those who want to build an ideal world.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/644", normalKey: "pokedex/normal/644", shinyKey: "pokedex/shiny/644", silhouetteKey: "pokedex/silhouette/644")),
        PokedexSpeciesDefinition(nationalDexNumber: 645, generation: 5, slug: "landorus", name: "Landorus", genus: "Abundance Pokémon", description: "Lands visited by Landorus grant such bountiful crops that it has been hailed as “The Guardian of the Fields.”", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/645", normalKey: "pokedex/normal/645", shinyKey: "pokedex/shiny/645", silhouetteKey: "pokedex/silhouette/645")),
        PokedexSpeciesDefinition(nationalDexNumber: 646, generation: 5, slug: "kyurem", name: "Kyurem", genus: "Boundary Pokémon", description: "This legendary ice Pokémon waits for a hero to fill in the missing parts of its body with truth or ideals.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/646", normalKey: "pokedex/normal/646", shinyKey: "pokedex/shiny/646", silhouetteKey: "pokedex/silhouette/646")),
        PokedexSpeciesDefinition(nationalDexNumber: 647, generation: 5, slug: "keldeo", name: "Keldeo", genus: "Colt Pokémon", description: "It crosses the world, running over the surfaces of oceans and rivers. It appears at scenic waterfronts.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/647", normalKey: "pokedex/normal/647", shinyKey: "pokedex/shiny/647", silhouetteKey: "pokedex/silhouette/647")),
        PokedexSpeciesDefinition(nationalDexNumber: 648, generation: 5, slug: "meloetta", name: "Meloetta", genus: "Melody Pokémon", description: "The melodies sung by Meloetta have the power to make Pokémon that hear them happy or sad.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/648", normalKey: "pokedex/normal/648", shinyKey: "pokedex/shiny/648", silhouetteKey: "pokedex/silhouette/648")),
        PokedexSpeciesDefinition(nationalDexNumber: 649, generation: 5, slug: "genesect", name: "Genesect", genus: "Paleozoic Pokémon", description: "This ancient bug Pokémon was altered by Team Plasma. They upgraded the cannon on its back.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/649", normalKey: "pokedex/normal/649", shinyKey: "pokedex/shiny/649", silhouetteKey: "pokedex/silhouette/649")),
        PokedexSpeciesDefinition(nationalDexNumber: 650, generation: 6, slug: "chespin", name: "Chespin", genus: "Spiny Nut Pokémon", description: "The quills on its head are usually soft. When it flexes them, the points become so hard and sharp that they can pierce rock.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/650", normalKey: "pokedex/normal/650", shinyKey: "pokedex/shiny/650", silhouetteKey: "pokedex/silhouette/650")),
        PokedexSpeciesDefinition(nationalDexNumber: 651, generation: 6, slug: "quilladin", name: "Quilladin", genus: "Spiny Armor Pokémon", description: "It relies on its sturdy shell to deflect predators’ attacks. It counterattacks with its sharp quills.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/651", normalKey: "pokedex/normal/651", shinyKey: "pokedex/shiny/651", silhouetteKey: "pokedex/silhouette/651")),
        PokedexSpeciesDefinition(nationalDexNumber: 652, generation: 6, slug: "chesnaught", name: "Chesnaught", genus: "Spiny Armor Pokémon", description: "Its Tackle is forceful enough to flip a 50-ton tank. It shields its allies from danger with its own body.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/652", normalKey: "pokedex/normal/652", shinyKey: "pokedex/shiny/652", silhouetteKey: "pokedex/silhouette/652")),
        PokedexSpeciesDefinition(nationalDexNumber: 653, generation: 6, slug: "fennekin", name: "Fennekin", genus: "Fox Pokémon", description: "Eating a twig fills it with energy, and its roomy ears give vent to air hotter than 390 degrees Fahrenheit.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/653", normalKey: "pokedex/normal/653", shinyKey: "pokedex/shiny/653", silhouetteKey: "pokedex/silhouette/653")),
        PokedexSpeciesDefinition(nationalDexNumber: 654, generation: 6, slug: "braixen", name: "Braixen", genus: "Fox Pokémon", description: "It has a twig stuck in its tail. With friction from its tail fur, it sets the twig on fire and launches into battle.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/654", normalKey: "pokedex/normal/654", shinyKey: "pokedex/shiny/654", silhouetteKey: "pokedex/silhouette/654")),
        PokedexSpeciesDefinition(nationalDexNumber: 655, generation: 6, slug: "delphox", name: "Delphox", genus: "Fox Pokémon", description: "It gazes into the flame at the tip of its branch to achieve a focused state, which allows it to see into the future.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/655", normalKey: "pokedex/normal/655", shinyKey: "pokedex/shiny/655", silhouetteKey: "pokedex/silhouette/655")),
        PokedexSpeciesDefinition(nationalDexNumber: 656, generation: 6, slug: "froakie", name: "Froakie", genus: "Bubble Frog Pokémon", description: "It secretes flexible bubbles from its chest and back. The bubbles reduce the damage it would otherwise take when attacked.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/656", normalKey: "pokedex/normal/656", shinyKey: "pokedex/shiny/656", silhouetteKey: "pokedex/silhouette/656")),
        PokedexSpeciesDefinition(nationalDexNumber: 657, generation: 6, slug: "frogadier", name: "Frogadier", genus: "Bubble Frog Pokémon", description: "It can throw bubble-covered pebbles with precise control, hitting empty cans up to a hundred feet away.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/657", normalKey: "pokedex/normal/657", shinyKey: "pokedex/shiny/657", silhouetteKey: "pokedex/silhouette/657")),
        PokedexSpeciesDefinition(nationalDexNumber: 658, generation: 6, slug: "greninja", name: "Greninja", genus: "Ninja Pokémon", description: "It creates throwing stars out of compressed water. When it spins them and throws them at high speed, these stars can split metal in two.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/658", normalKey: "pokedex/normal/658", shinyKey: "pokedex/shiny/658", silhouetteKey: "pokedex/silhouette/658")),
        PokedexSpeciesDefinition(nationalDexNumber: 659, generation: 6, slug: "bunnelby", name: "Bunnelby", genus: "Digging Pokémon", description: "They use their large ears to dig burrows. They will dig the whole night through.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/659", normalKey: "pokedex/normal/659", shinyKey: "pokedex/shiny/659", silhouetteKey: "pokedex/silhouette/659")),
        PokedexSpeciesDefinition(nationalDexNumber: 660, generation: 6, slug: "diggersby", name: "Diggersby", genus: "Digging Pokémon", description: "With their powerful ears, they can heft boulders of a ton or more with ease. They can be a big help at construction sites.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/660", normalKey: "pokedex/normal/660", shinyKey: "pokedex/shiny/660", silhouetteKey: "pokedex/silhouette/660")),
        PokedexSpeciesDefinition(nationalDexNumber: 661, generation: 6, slug: "fletchling", name: "Fletchling", genus: "Tiny Robin Pokémon", description: "These friendly Pokémon send signals to one another with beautiful chirps and tail-feather movements.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/661", normalKey: "pokedex/normal/661", shinyKey: "pokedex/shiny/661", silhouetteKey: "pokedex/silhouette/661")),
        PokedexSpeciesDefinition(nationalDexNumber: 662, generation: 6, slug: "fletchinder", name: "Fletchinder", genus: "Ember Pokémon", description: "From its beak, it expels embers that set the tall grass on fire. Then it pounces on the bewildered prey that pop out of the grass.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/662", normalKey: "pokedex/normal/662", shinyKey: "pokedex/shiny/662", silhouetteKey: "pokedex/silhouette/662")),
        PokedexSpeciesDefinition(nationalDexNumber: 663, generation: 6, slug: "talonflame", name: "Talonflame", genus: "Scorching Pokémon", description: "In the fever of an exciting battle, it showers embers from the gaps between its feathers and takes to the air.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/663", normalKey: "pokedex/normal/663", shinyKey: "pokedex/shiny/663", silhouetteKey: "pokedex/silhouette/663")),
        PokedexSpeciesDefinition(nationalDexNumber: 664, generation: 6, slug: "scatterbug", name: "Scatterbug", genus: "Scatterdust Pokémon", description: "When under attack from bird Pokémon, it spews a poisonous black powder that causes paralysis on contact.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/664", normalKey: "pokedex/normal/664", shinyKey: "pokedex/shiny/664", silhouetteKey: "pokedex/silhouette/664")),
        PokedexSpeciesDefinition(nationalDexNumber: 665, generation: 6, slug: "spewpa", name: "Spewpa", genus: "Scatterdust Pokémon", description: "It lives hidden within thicket shadows. When predators attack, it quickly bristles the fur covering its body in an effort to threaten them.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/665", normalKey: "pokedex/normal/665", shinyKey: "pokedex/shiny/665", silhouetteKey: "pokedex/silhouette/665")),
        PokedexSpeciesDefinition(nationalDexNumber: 666, generation: 6, slug: "vivillon", name: "Vivillon", genus: "Scale Pokémon", description: "Vivillon with many different patterns are found all over the world. These patterns are affected by the climate of their habitat.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/666", normalKey: "pokedex/normal/666", shinyKey: "pokedex/shiny/666", silhouetteKey: "pokedex/silhouette/666")),
        PokedexSpeciesDefinition(nationalDexNumber: 667, generation: 6, slug: "litleo", name: "Litleo", genus: "Lion Cub Pokémon", description: "The stronger the opponent it faces, the more heat surges from its mane and the more power flows through its body.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/667", normalKey: "pokedex/normal/667", shinyKey: "pokedex/shiny/667", silhouetteKey: "pokedex/silhouette/667")),
        PokedexSpeciesDefinition(nationalDexNumber: 668, generation: 6, slug: "pyroar", name: "Pyroar", genus: "Royal Pokémon", description: "The male with the largest mane of fire is the leader of the pride.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/668", normalKey: "pokedex/normal/668", shinyKey: "pokedex/shiny/668", silhouetteKey: "pokedex/silhouette/668")),
        PokedexSpeciesDefinition(nationalDexNumber: 669, generation: 6, slug: "flabebe", name: "Flabébé", genus: "Single Bloom Pokémon", description: "It draws out and controls the hidden power of flowers. The flower Flabébé holds is most likely part of its body.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/669", normalKey: "pokedex/normal/669", shinyKey: "pokedex/shiny/669", silhouetteKey: "pokedex/silhouette/669")),
        PokedexSpeciesDefinition(nationalDexNumber: 670, generation: 6, slug: "floette", name: "Floette", genus: "Single Bloom Pokémon", description: "It flutters around fields of flowers and cares for flowers that are starting to wilt. It draws out the hidden power of flowers to battle.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/670", normalKey: "pokedex/normal/670", shinyKey: "pokedex/shiny/670", silhouetteKey: "pokedex/silhouette/670")),
        PokedexSpeciesDefinition(nationalDexNumber: 671, generation: 6, slug: "florges", name: "Florges", genus: "Garden Pokémon", description: "It claims exquisite flower gardens as its territory, and it obtains power from basking in the energy emitted by flowering plants.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/671", normalKey: "pokedex/normal/671", shinyKey: "pokedex/shiny/671", silhouetteKey: "pokedex/silhouette/671")),
        PokedexSpeciesDefinition(nationalDexNumber: 672, generation: 6, slug: "skiddo", name: "Skiddo", genus: "Mount Pokémon", description: "Thought to be one of the first Pokémon to live in harmony with humans, it has a placid disposition.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/672", normalKey: "pokedex/normal/672", shinyKey: "pokedex/shiny/672", silhouetteKey: "pokedex/silhouette/672")),
        PokedexSpeciesDefinition(nationalDexNumber: 673, generation: 6, slug: "gogoat", name: "Gogoat", genus: "Mount Pokémon", description: "It can tell how its Trainer is feeling by subtle shifts in the grip on its horns. This empathic sense lets them run as if one being.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/673", normalKey: "pokedex/normal/673", shinyKey: "pokedex/shiny/673", silhouetteKey: "pokedex/silhouette/673")),
        PokedexSpeciesDefinition(nationalDexNumber: 674, generation: 6, slug: "pancham", name: "Pancham", genus: "Playful Pokémon", description: "It does its best to be taken seriously by its enemies, but its glare is not sufficiently intimidating. Chewing on a leaf is its trademark.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/674", normalKey: "pokedex/normal/674", shinyKey: "pokedex/shiny/674", silhouetteKey: "pokedex/silhouette/674")),
        PokedexSpeciesDefinition(nationalDexNumber: 675, generation: 6, slug: "pangoro", name: "Pangoro", genus: "Daunting Pokémon", description: "Although it possesses a violent temperament, it won’t put up with bullying. It uses the leaf in its mouth to sense the movements of its enemies.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/675", normalKey: "pokedex/normal/675", shinyKey: "pokedex/shiny/675", silhouetteKey: "pokedex/silhouette/675")),
        PokedexSpeciesDefinition(nationalDexNumber: 676, generation: 6, slug: "furfrou", name: "Furfrou", genus: "Poodle Pokémon", description: "Trimming its fluffy fur not only makes it more elegant but also increases the swiftness of its movements.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/676", normalKey: "pokedex/normal/676", shinyKey: "pokedex/shiny/676", silhouetteKey: "pokedex/silhouette/676")),
        PokedexSpeciesDefinition(nationalDexNumber: 677, generation: 6, slug: "espurr", name: "Espurr", genus: "Restraint Pokémon", description: "The organ that emits its intense psychic power is sheltered by its ears to keep power from leaking out.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/677", normalKey: "pokedex/normal/677", shinyKey: "pokedex/shiny/677", silhouetteKey: "pokedex/silhouette/677")),
        PokedexSpeciesDefinition(nationalDexNumber: 678, generation: 6, slug: "meowstic", name: "Meowstic", genus: "Constraint Pokémon", description: "When in danger, it raises its ears and releases enough psychic power to grind a 10-ton truck into dust.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/678", normalKey: "pokedex/normal/678", shinyKey: "pokedex/shiny/678", silhouetteKey: "pokedex/silhouette/678")),
        PokedexSpeciesDefinition(nationalDexNumber: 679, generation: 6, slug: "honedge", name: "Honedge", genus: "Sword Pokémon", description: "Apparently this Pokémon is born when a departed spirit inhabits a sword. It attaches itself to people and drinks their life force.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/679", normalKey: "pokedex/normal/679", shinyKey: "pokedex/shiny/679", silhouetteKey: "pokedex/silhouette/679")),
        PokedexSpeciesDefinition(nationalDexNumber: 680, generation: 6, slug: "doublade", name: "Doublade", genus: "Sword Pokémon", description: "When Honedge evolves, it divides into two swords, which cooperate via telepathy to coordinate attacks and slash their enemies to ribbons.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/680", normalKey: "pokedex/normal/680", shinyKey: "pokedex/shiny/680", silhouetteKey: "pokedex/silhouette/680")),
        PokedexSpeciesDefinition(nationalDexNumber: 681, generation: 6, slug: "aegislash", name: "Aegislash", genus: "Royal Sword Pokémon", description: "Generations of kings were attended by these Pokémon, which used their spectral power to manipulate and control people and Pokémon.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/681", normalKey: "pokedex/normal/681", shinyKey: "pokedex/shiny/681", silhouetteKey: "pokedex/silhouette/681")),
        PokedexSpeciesDefinition(nationalDexNumber: 682, generation: 6, slug: "spritzee", name: "Spritzee", genus: "Perfume Pokémon", description: "It emits a scent that enraptures those who smell it. This fragrance changes depending on what it has eaten.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/682", normalKey: "pokedex/normal/682", shinyKey: "pokedex/shiny/682", silhouetteKey: "pokedex/silhouette/682")),
        PokedexSpeciesDefinition(nationalDexNumber: 683, generation: 6, slug: "aromatisse", name: "Aromatisse", genus: "Fragrance Pokémon", description: "It devises various scents, pleasant and unpleasant, and emits scents that its enemies dislike in order to gain an edge in battle.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/683", normalKey: "pokedex/normal/683", shinyKey: "pokedex/shiny/683", silhouetteKey: "pokedex/silhouette/683")),
        PokedexSpeciesDefinition(nationalDexNumber: 684, generation: 6, slug: "swirlix", name: "Swirlix", genus: "Cotton Candy Pokémon", description: "To entangle its opponents in battle, it extrudes white threads as sweet and sticky as cotton candy.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/684", normalKey: "pokedex/normal/684", shinyKey: "pokedex/shiny/684", silhouetteKey: "pokedex/silhouette/684")),
        PokedexSpeciesDefinition(nationalDexNumber: 685, generation: 6, slug: "slurpuff", name: "Slurpuff", genus: "Meringue Pokémon", description: "It can distinguish the faintest of scents. It puts its sensitive sense of smell to use by helping pastry chefs in their work.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/685", normalKey: "pokedex/normal/685", shinyKey: "pokedex/shiny/685", silhouetteKey: "pokedex/silhouette/685")),
        PokedexSpeciesDefinition(nationalDexNumber: 686, generation: 6, slug: "inkay", name: "Inkay", genus: "Revolving Pokémon", description: "Opponents who stare at the flashing of the light-emitting spots on its body become dazed and lose their will to fight.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/686", normalKey: "pokedex/normal/686", shinyKey: "pokedex/shiny/686", silhouetteKey: "pokedex/silhouette/686")),
        PokedexSpeciesDefinition(nationalDexNumber: 687, generation: 6, slug: "malamar", name: "Malamar", genus: "Overturning Pokémon", description: "It wields the most compelling hypnotic powers of any Pokémon, and it forces others to do whatever it wants.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/687", normalKey: "pokedex/normal/687", shinyKey: "pokedex/shiny/687", silhouetteKey: "pokedex/silhouette/687")),
        PokedexSpeciesDefinition(nationalDexNumber: 688, generation: 6, slug: "binacle", name: "Binacle", genus: "Two-Handed Pokémon", description: "Two Binacle live together on one rock. When they fight, one of them will move to a different rock.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/688", normalKey: "pokedex/normal/688", shinyKey: "pokedex/shiny/688", silhouetteKey: "pokedex/silhouette/688")),
        PokedexSpeciesDefinition(nationalDexNumber: 689, generation: 6, slug: "barbaracle", name: "Barbaracle", genus: "Collective Pokémon", description: "When they evolve, two Binacle multiply into seven. They fight with the power of seven Binacle.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/689", normalKey: "pokedex/normal/689", shinyKey: "pokedex/shiny/689", silhouetteKey: "pokedex/silhouette/689")),
        PokedexSpeciesDefinition(nationalDexNumber: 690, generation: 6, slug: "skrelp", name: "Skrelp", genus: "Mock Kelp Pokémon", description: "Camouflaged as rotten kelp, they spray liquid poison on prey that approaches unawares and then finish it off.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/690", normalKey: "pokedex/normal/690", shinyKey: "pokedex/shiny/690", silhouetteKey: "pokedex/silhouette/690")),
        PokedexSpeciesDefinition(nationalDexNumber: 691, generation: 6, slug: "dragalge", name: "Dragalge", genus: "Mock Kelp Pokémon", description: "Their poison is strong enough to eat through the hull of a tanker, and they spit it indiscriminately at anything that enters their territory.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/691", normalKey: "pokedex/normal/691", shinyKey: "pokedex/shiny/691", silhouetteKey: "pokedex/silhouette/691")),
        PokedexSpeciesDefinition(nationalDexNumber: 692, generation: 6, slug: "clauncher", name: "Clauncher", genus: "Water Gun Pokémon", description: "They knock down flying prey by firing compressed water from their massive claws like shooting a pistol.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/692", normalKey: "pokedex/normal/692", shinyKey: "pokedex/shiny/692", silhouetteKey: "pokedex/silhouette/692")),
        PokedexSpeciesDefinition(nationalDexNumber: 693, generation: 6, slug: "clawitzer", name: "Clawitzer", genus: "Howitzer Pokémon", description: "Their enormous claws launch cannonballs of water powerful enough to pierce tanker hulls.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/693", normalKey: "pokedex/normal/693", shinyKey: "pokedex/shiny/693", silhouetteKey: "pokedex/silhouette/693")),
        PokedexSpeciesDefinition(nationalDexNumber: 694, generation: 6, slug: "helioptile", name: "Helioptile", genus: "Generator Pokémon", description: "They make their home in deserts. They can generate their energy from basking in the sun, so eating food is not a requirement.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/694", normalKey: "pokedex/normal/694", shinyKey: "pokedex/shiny/694", silhouetteKey: "pokedex/silhouette/694")),
        PokedexSpeciesDefinition(nationalDexNumber: 695, generation: 6, slug: "heliolisk", name: "Heliolisk", genus: "Generator Pokémon", description: "They flare their frills and generate energy. A single Heliolisk can generate sufficient electricity to power a skyscraper.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/695", normalKey: "pokedex/normal/695", shinyKey: "pokedex/shiny/695", silhouetteKey: "pokedex/silhouette/695")),
        PokedexSpeciesDefinition(nationalDexNumber: 696, generation: 6, slug: "tyrunt", name: "Tyrunt", genus: "Royal Heir Pokémon", description: "This Pokémon was restored from a fossil. If something happens that it doesn’t like, it throws a tantrum and runs wild.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/696", normalKey: "pokedex/normal/696", shinyKey: "pokedex/shiny/696", silhouetteKey: "pokedex/silhouette/696")),
        PokedexSpeciesDefinition(nationalDexNumber: 697, generation: 6, slug: "tyrantrum", name: "Tyrantrum", genus: "Despot Pokémon", description: "Thanks to its gargantuan jaws, which could shred thick metal plates as if they were paper, it was invincible in the ancient world it once inhabited.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/697", normalKey: "pokedex/normal/697", shinyKey: "pokedex/shiny/697", silhouetteKey: "pokedex/silhouette/697")),
        PokedexSpeciesDefinition(nationalDexNumber: 698, generation: 6, slug: "amaura", name: "Amaura", genus: "Tundra Pokémon", description: "This ancient Pokémon was restored from part of its body that had been frozen in ice for over 100 million years.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/698", normalKey: "pokedex/normal/698", shinyKey: "pokedex/shiny/698", silhouetteKey: "pokedex/silhouette/698")),
        PokedexSpeciesDefinition(nationalDexNumber: 699, generation: 6, slug: "aurorus", name: "Aurorus", genus: "Tundra Pokémon", description: "The diamond-shaped crystals on its body expel air as cold as -240 degrees Fahrenheit, surrounding its enemies and encasing them in ice.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/699", normalKey: "pokedex/normal/699", shinyKey: "pokedex/shiny/699", silhouetteKey: "pokedex/silhouette/699")),
        PokedexSpeciesDefinition(nationalDexNumber: 700, generation: 6, slug: "sylveon", name: "Sylveon", genus: "Intertwining Pokémon", description: "It sends a soothing aura from its ribbonlike feelers to calm fights.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/700", normalKey: "pokedex/normal/700", shinyKey: "pokedex/shiny/700", silhouetteKey: "pokedex/silhouette/700")),
        PokedexSpeciesDefinition(nationalDexNumber: 701, generation: 6, slug: "hawlucha", name: "Hawlucha", genus: "Wrestling Pokémon", description: "Although its body is small, its proficient fighting skills enable it to keep up with big bruisers like Machamp and Hariyama.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/701", normalKey: "pokedex/normal/701", shinyKey: "pokedex/shiny/701", silhouetteKey: "pokedex/silhouette/701")),
        PokedexSpeciesDefinition(nationalDexNumber: 702, generation: 6, slug: "dedenne", name: "Dedenne", genus: "Antenna Pokémon", description: "Its whiskers serve as antennas. By sending and receiving electrical waves, it can communicate with others over vast distances.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/702", normalKey: "pokedex/normal/702", shinyKey: "pokedex/shiny/702", silhouetteKey: "pokedex/silhouette/702")),
        PokedexSpeciesDefinition(nationalDexNumber: 703, generation: 6, slug: "carbink", name: "Carbink", genus: "Jewel Pokémon", description: "Born from the temperatures and pressures deep underground, it fires beams from the stone in its head.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/703", normalKey: "pokedex/normal/703", shinyKey: "pokedex/shiny/703", silhouetteKey: "pokedex/silhouette/703")),
        PokedexSpeciesDefinition(nationalDexNumber: 704, generation: 6, slug: "goomy", name: "Goomy", genus: "Soft Tissue Pokémon", description: "The weakest Dragon-type Pokémon, it lives in damp, shady places, so its body doesn’t dry out.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/704", normalKey: "pokedex/normal/704", shinyKey: "pokedex/shiny/704", silhouetteKey: "pokedex/silhouette/704")),
        PokedexSpeciesDefinition(nationalDexNumber: 705, generation: 6, slug: "sliggoo", name: "Sliggoo", genus: "Soft Tissue Pokémon", description: "It drives away opponents by excreting a sticky liquid that can dissolve anything. Its eyes devolved, so it can’t see anything.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/705", normalKey: "pokedex/normal/705", shinyKey: "pokedex/shiny/705", silhouetteKey: "pokedex/silhouette/705")),
        PokedexSpeciesDefinition(nationalDexNumber: 706, generation: 6, slug: "goodra", name: "Goodra", genus: "Dragon Pokémon", description: "This very friendly Dragon-type Pokémon will hug its beloved Trainer, leaving that Trainer covered in sticky slime.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/706", normalKey: "pokedex/normal/706", shinyKey: "pokedex/shiny/706", silhouetteKey: "pokedex/silhouette/706")),
        PokedexSpeciesDefinition(nationalDexNumber: 707, generation: 6, slug: "klefki", name: "Klefki", genus: "Key Ring Pokémon", description: "These key collectors threaten any attackers by fiercely jingling their keys at them.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/707", normalKey: "pokedex/normal/707", shinyKey: "pokedex/shiny/707", silhouetteKey: "pokedex/silhouette/707")),
        PokedexSpeciesDefinition(nationalDexNumber: 708, generation: 6, slug: "phantump", name: "Phantump", genus: "Stump Pokémon", description: "These Pokémon are created when spirits possess rotten tree stumps. They prefer to live in abandoned forests.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/708", normalKey: "pokedex/normal/708", shinyKey: "pokedex/shiny/708", silhouetteKey: "pokedex/silhouette/708")),
        PokedexSpeciesDefinition(nationalDexNumber: 709, generation: 6, slug: "trevenant", name: "Trevenant", genus: "Elder Tree Pokémon", description: "It can control trees at will. It will trap people who harm the forest, so they can never leave.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/709", normalKey: "pokedex/normal/709", shinyKey: "pokedex/shiny/709", silhouetteKey: "pokedex/silhouette/709")),
        PokedexSpeciesDefinition(nationalDexNumber: 710, generation: 6, slug: "pumpkaboo", name: "Pumpkaboo", genus: "Pumpkin Pokémon", description: "The pumpkin body is inhabited by a spirit trapped in this world. As the sun sets, it becomes restless and active.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/710", normalKey: "pokedex/normal/710", shinyKey: "pokedex/shiny/710", silhouetteKey: "pokedex/silhouette/710")),
        PokedexSpeciesDefinition(nationalDexNumber: 711, generation: 6, slug: "gourgeist", name: "Gourgeist", genus: "Pumpkin Pokémon", description: "Singing in eerie voices, they wander town streets on the night of the new moon. Anyone who hears their song is cursed.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/711", normalKey: "pokedex/normal/711", shinyKey: "pokedex/shiny/711", silhouetteKey: "pokedex/silhouette/711")),
        PokedexSpeciesDefinition(nationalDexNumber: 712, generation: 6, slug: "bergmite", name: "Bergmite", genus: "Ice Chunk Pokémon", description: "It blocks opponents’ attacks with the ice that shields its body. It uses cold air to repair any cracks with new ice.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/712", normalKey: "pokedex/normal/712", shinyKey: "pokedex/shiny/712", silhouetteKey: "pokedex/silhouette/712")),
        PokedexSpeciesDefinition(nationalDexNumber: 713, generation: 6, slug: "avalugg", name: "Avalugg", genus: "Iceberg Pokémon", description: "Its ice-covered body is as hard as steel. Its cumbersome frame crushes anything that stands in its way.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/713", normalKey: "pokedex/normal/713", shinyKey: "pokedex/shiny/713", silhouetteKey: "pokedex/silhouette/713")),
        PokedexSpeciesDefinition(nationalDexNumber: 714, generation: 6, slug: "noibat", name: "Noibat", genus: "Sound Wave Pokémon", description: "They live in pitch-black caves. Their enormous ears can emit ultrasonic waves of 200,000 hertz.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/714", normalKey: "pokedex/normal/714", shinyKey: "pokedex/shiny/714", silhouetteKey: "pokedex/silhouette/714")),
        PokedexSpeciesDefinition(nationalDexNumber: 715, generation: 6, slug: "noivern", name: "Noivern", genus: "Sound Wave Pokémon", description: "They fly around on moonless nights and attack careless prey. Nothing can beat them in a battle in the dark.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/715", normalKey: "pokedex/normal/715", shinyKey: "pokedex/shiny/715", silhouetteKey: "pokedex/silhouette/715")),
        PokedexSpeciesDefinition(nationalDexNumber: 716, generation: 6, slug: "xerneas", name: "Xerneas", genus: "Life Pokémon", description: "Legends say it can share eternal life. It slept for a thousand years in the form of a tree before its revival.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/716", normalKey: "pokedex/normal/716", shinyKey: "pokedex/shiny/716", silhouetteKey: "pokedex/silhouette/716")),
        PokedexSpeciesDefinition(nationalDexNumber: 717, generation: 6, slug: "yveltal", name: "Yveltal", genus: "Destruction Pokémon", description: "When this legendary Pokémon’s wings and tail feathers spread wide and glow red, it absorbs the life force of living creatures.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/717", normalKey: "pokedex/normal/717", shinyKey: "pokedex/shiny/717", silhouetteKey: "pokedex/silhouette/717")),
        PokedexSpeciesDefinition(nationalDexNumber: 718, generation: 6, slug: "zygarde", name: "Zygarde", genus: "Order Pokémon", description: "When the Kalos region’s ecosystem falls into disarray, it appears and reveals its secret power.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/718", normalKey: "pokedex/normal/718", shinyKey: "pokedex/shiny/718", silhouetteKey: "pokedex/silhouette/718")),
        PokedexSpeciesDefinition(nationalDexNumber: 719, generation: 6, slug: "diancie", name: "Diancie", genus: "Jewel Pokémon", description: "A sudden transformation of Carbink, its pink, glimmering body is said to be the loveliest sight in the whole world.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/719", normalKey: "pokedex/normal/719", shinyKey: "pokedex/shiny/719", silhouetteKey: "pokedex/silhouette/719")),
        PokedexSpeciesDefinition(nationalDexNumber: 720, generation: 6, slug: "hoopa", name: "Hoopa", genus: "Mischief Pokémon", description: "This troublemaker sends anything and everything to faraway places using its loop, which can warp space.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/720", normalKey: "pokedex/normal/720", shinyKey: "pokedex/shiny/720", silhouetteKey: "pokedex/silhouette/720")),
        PokedexSpeciesDefinition(nationalDexNumber: 721, generation: 6, slug: "volcanion", name: "Volcanion", genus: "Steam Pokémon", description: "It lets out billows of steam and disappears into the dense fog. It’s said to live in mountains where humans do not tread.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/721", normalKey: "pokedex/normal/721", shinyKey: "pokedex/shiny/721", silhouetteKey: "pokedex/silhouette/721")),
        PokedexSpeciesDefinition(nationalDexNumber: 722, generation: 7, slug: "rowlet", name: "Rowlet", genus: "Grass Quill Pokémon", description: "This wary Pokémon uses photosynthesis to store up energy during the day, while becoming active at night.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/722", normalKey: "pokedex/normal/722", shinyKey: "pokedex/shiny/722", silhouetteKey: "pokedex/silhouette/722")),
        PokedexSpeciesDefinition(nationalDexNumber: 723, generation: 7, slug: "dartrix", name: "Dartrix", genus: "Blade Quill Pokémon", description: "A bit of a dandy, it spends its free time preening its wings. Its preoccupation with any dirt on its plumage can leave it unable to battle.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/723", normalKey: "pokedex/normal/723", shinyKey: "pokedex/shiny/723", silhouetteKey: "pokedex/silhouette/723")),
        PokedexSpeciesDefinition(nationalDexNumber: 724, generation: 7, slug: "decidueye", name: "Decidueye", genus: "Arrow Quill Pokémon", description: "It fires arrow quills from its wings with such precision, they can pierce a pebble at distances over a hundred yards.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/724", normalKey: "pokedex/normal/724", shinyKey: "pokedex/shiny/724", silhouetteKey: "pokedex/silhouette/724")),
        PokedexSpeciesDefinition(nationalDexNumber: 725, generation: 7, slug: "litten", name: "Litten", genus: "Fire Cat Pokémon", description: "While grooming itself, it builds up fur inside its stomach. It sets the fur alight and spews fiery attacks, which change based on how it coughs.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/725", normalKey: "pokedex/normal/725", shinyKey: "pokedex/shiny/725", silhouetteKey: "pokedex/silhouette/725")),
        PokedexSpeciesDefinition(nationalDexNumber: 726, generation: 7, slug: "torracat", name: "Torracat", genus: "Fire Cat Pokémon", description: "At its throat, it bears a bell of fire. The bell rings brightly whenever this Pokémon spits fire.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/726", normalKey: "pokedex/normal/726", shinyKey: "pokedex/shiny/726", silhouetteKey: "pokedex/silhouette/726")),
        PokedexSpeciesDefinition(nationalDexNumber: 727, generation: 7, slug: "incineroar", name: "Incineroar", genus: "Heel Pokémon", description: "This Pokémon has a violent, selfish disposition. If it’s not in the mood to listen, it will ignore its Trainer’s orders with complete nonchalance.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/727", normalKey: "pokedex/normal/727", shinyKey: "pokedex/shiny/727", silhouetteKey: "pokedex/silhouette/727")),
        PokedexSpeciesDefinition(nationalDexNumber: 728, generation: 7, slug: "popplio", name: "Popplio", genus: "Sea Lion Pokémon", description: "This Pokémon snorts body fluids from its nose, blowing balloons to smash into its foes. It’s famous for being a hard worker.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/728", normalKey: "pokedex/normal/728", shinyKey: "pokedex/shiny/728", silhouetteKey: "pokedex/silhouette/728")),
        PokedexSpeciesDefinition(nationalDexNumber: 729, generation: 7, slug: "brionne", name: "Brionne", genus: "Pop Star Pokémon", description: "A skillful dancer, it creates a sequence of water balloons as it dances, and briskly bombards its enemies.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/729", normalKey: "pokedex/normal/729", shinyKey: "pokedex/shiny/729", silhouetteKey: "pokedex/silhouette/729")),
        PokedexSpeciesDefinition(nationalDexNumber: 730, generation: 7, slug: "primarina", name: "Primarina", genus: "Soloist Pokémon", description: "It controls its water balloons with song. The melody is learned from others of its kind and is passed down from one generation to the next.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/730", normalKey: "pokedex/normal/730", shinyKey: "pokedex/shiny/730", silhouetteKey: "pokedex/silhouette/730")),
        PokedexSpeciesDefinition(nationalDexNumber: 731, generation: 7, slug: "pikipek", name: "Pikipek", genus: "Woodpecker Pokémon", description: "It can peck at a rate of 16 times a second to drill holes in trees. It uses the holes for food storage and for nesting.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/731", normalKey: "pokedex/normal/731", shinyKey: "pokedex/shiny/731", silhouetteKey: "pokedex/silhouette/731")),
        PokedexSpeciesDefinition(nationalDexNumber: 732, generation: 7, slug: "trumbeak", name: "Trumbeak", genus: "Bugle Beak Pokémon", description: "It eats berries and stores their seeds in its beak. When it encounters enemies or prey, it fires off all the seeds in a burst.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/732", normalKey: "pokedex/normal/732", shinyKey: "pokedex/shiny/732", silhouetteKey: "pokedex/silhouette/732")),
        PokedexSpeciesDefinition(nationalDexNumber: 733, generation: 7, slug: "toucannon", name: "Toucannon", genus: "Cannon Pokémon", description: "When it battles, its beak heats up. The temperature can easily exceed 212 degrees Fahrenheit, causing severe burns when it hits.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/733", normalKey: "pokedex/normal/733", shinyKey: "pokedex/shiny/733", silhouetteKey: "pokedex/silhouette/733")),
        PokedexSpeciesDefinition(nationalDexNumber: 734, generation: 7, slug: "yungoos", name: "Yungoos", genus: "Loitering Pokémon", description: "With its sharp fangs, it will bite anything. It did not originally live in Alola but was imported from another region.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/734", normalKey: "pokedex/normal/734", shinyKey: "pokedex/shiny/734", silhouetteKey: "pokedex/silhouette/734")),
        PokedexSpeciesDefinition(nationalDexNumber: 735, generation: 7, slug: "gumshoos", name: "Gumshoos", genus: "Stakeout Pokémon", description: "When it finds a trace of its prey, it patiently stakes out the location...but it’s always snoozing by nightfall.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/735", normalKey: "pokedex/normal/735", shinyKey: "pokedex/shiny/735", silhouetteKey: "pokedex/silhouette/735")),
        PokedexSpeciesDefinition(nationalDexNumber: 736, generation: 7, slug: "grubbin", name: "Grubbin", genus: "Larva Pokémon", description: "Its strong jaw enables it to scrape trees and slurp out the sap. It normally lives underground.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/736", normalKey: "pokedex/normal/736", shinyKey: "pokedex/shiny/736", silhouetteKey: "pokedex/silhouette/736")),
        PokedexSpeciesDefinition(nationalDexNumber: 737, generation: 7, slug: "charjabug", name: "Charjabug", genus: "Battery Pokémon", description: "Its body is capable of storing electricity. On camping trips, people are grateful to have one around.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/737", normalKey: "pokedex/normal/737", shinyKey: "pokedex/shiny/737", silhouetteKey: "pokedex/silhouette/737")),
        PokedexSpeciesDefinition(nationalDexNumber: 738, generation: 7, slug: "vikavolt", name: "Vikavolt", genus: "Stag Beetle Pokémon", description: "It zips around, on sharp lookout for an opening. It concentrates electrical energy within its large jaws and uses it to zap its enemies.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/738", normalKey: "pokedex/normal/738", shinyKey: "pokedex/shiny/738", silhouetteKey: "pokedex/silhouette/738")),
        PokedexSpeciesDefinition(nationalDexNumber: 739, generation: 7, slug: "crabrawler", name: "Crabrawler", genus: "Boxing Pokémon", description: "While guarding its weak points with its pincers, it looks for an opening and unleashes punches. When it loses, it foams at the mouth and faints.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/739", normalKey: "pokedex/normal/739", shinyKey: "pokedex/shiny/739", silhouetteKey: "pokedex/silhouette/739")),
        PokedexSpeciesDefinition(nationalDexNumber: 740, generation: 7, slug: "crabominable", name: "Crabominable", genus: "Woolly Crab Pokémon", description: "It aimed for the top but got lost and ended up on a snowy mountain. Being forced to endure the cold, this Pokémon evolved and grew fur.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/740", normalKey: "pokedex/normal/740", shinyKey: "pokedex/shiny/740", silhouetteKey: "pokedex/silhouette/740")),
        PokedexSpeciesDefinition(nationalDexNumber: 741, generation: 7, slug: "oricorio", name: "Oricorio", genus: "Dancing Pokémon", description: "It beats its wings together to create fire. As it moves in the steps of its beautiful dance, it bathes opponents in intense flames.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/741", normalKey: "pokedex/normal/741", shinyKey: "pokedex/shiny/741", silhouetteKey: "pokedex/silhouette/741")),
        PokedexSpeciesDefinition(nationalDexNumber: 742, generation: 7, slug: "cutiefly", name: "Cutiefly", genus: "Bee Fly Pokémon", description: "It feeds on the nectar and pollen of flowers. Because it’s able to sense auras, it can identify which flowers are about to bloom.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/742", normalKey: "pokedex/normal/742", shinyKey: "pokedex/shiny/742", silhouetteKey: "pokedex/silhouette/742")),
        PokedexSpeciesDefinition(nationalDexNumber: 743, generation: 7, slug: "ribombee", name: "Ribombee", genus: "Bee Fly Pokémon", description: "It rolls up pollen into puffs. It makes many different varieties, some used as food and others used in battle.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/743", normalKey: "pokedex/normal/743", shinyKey: "pokedex/shiny/743", silhouetteKey: "pokedex/silhouette/743")),
        PokedexSpeciesDefinition(nationalDexNumber: 744, generation: 7, slug: "rockruff", name: "Rockruff", genus: "Puppy Pokémon", description: "It’s considered to be a good Pokémon for beginners because of its friendliness, but its disposition grows rougher as it grows up.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/744", normalKey: "pokedex/normal/744", shinyKey: "pokedex/shiny/744", silhouetteKey: "pokedex/silhouette/744")),
        PokedexSpeciesDefinition(nationalDexNumber: 745, generation: 7, slug: "lycanroc", name: "Lycanroc", genus: "Wolf Pokémon", description: "Its quick movements confuse its enemies. Well equipped with claws and fangs, it also uses the sharp rocks in its mane as weapons.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/745", normalKey: "pokedex/normal/745", shinyKey: "pokedex/shiny/745", silhouetteKey: "pokedex/silhouette/745")),
        PokedexSpeciesDefinition(nationalDexNumber: 746, generation: 7, slug: "wishiwashi", name: "Wishiwashi", genus: "Small Fry Pokémon", description: "When it’s in trouble, its eyes moisten and begin to shine. The shining light attracts its comrades, and they stand together against their enemies.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/746", normalKey: "pokedex/normal/746", shinyKey: "pokedex/shiny/746", silhouetteKey: "pokedex/silhouette/746")),
        PokedexSpeciesDefinition(nationalDexNumber: 747, generation: 7, slug: "mareanie", name: "Mareanie", genus: "Brutal Star Pokémon", description: "It plunges the poison spike on its head into its prey. When the prey has weakened, Mareanie deals the finishing blow with its 10 tentacles.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/747", normalKey: "pokedex/normal/747", shinyKey: "pokedex/shiny/747", silhouetteKey: "pokedex/silhouette/747")),
        PokedexSpeciesDefinition(nationalDexNumber: 748, generation: 7, slug: "toxapex", name: "Toxapex", genus: "Brutal Star Pokémon", description: "Toxapex crawls along the ocean floor on its 12 legs. It leaves a trail of Corsola bits scattered in its wake.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/748", normalKey: "pokedex/normal/748", shinyKey: "pokedex/shiny/748", silhouetteKey: "pokedex/silhouette/748")),
        PokedexSpeciesDefinition(nationalDexNumber: 749, generation: 7, slug: "mudbray", name: "Mudbray", genus: "Donkey Pokémon", description: "The mud stuck to Mudbray’s hooves enhances its grip and its powerful running gait.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/749", normalKey: "pokedex/normal/749", shinyKey: "pokedex/shiny/749", silhouetteKey: "pokedex/silhouette/749")),
        PokedexSpeciesDefinition(nationalDexNumber: 750, generation: 7, slug: "mudsdale", name: "Mudsdale", genus: "Draft Horse Pokémon", description: "It spits a mud that provides resistance to both wind and rain, so the walls of old houses were often coated with it.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/750", normalKey: "pokedex/normal/750", shinyKey: "pokedex/shiny/750", silhouetteKey: "pokedex/silhouette/750")),
        PokedexSpeciesDefinition(nationalDexNumber: 751, generation: 7, slug: "dewpider", name: "Dewpider", genus: "Water Bubble Pokémon", description: "It crawls onto the land in search of food. Its water bubble allows it to breathe and protects its soft head.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/751", normalKey: "pokedex/normal/751", shinyKey: "pokedex/shiny/751", silhouetteKey: "pokedex/silhouette/751")),
        PokedexSpeciesDefinition(nationalDexNumber: 752, generation: 7, slug: "araquanid", name: "Araquanid", genus: "Water Bubble Pokémon", description: "It delivers headbutts with the water bubble on its head. Small Pokémon get sucked into the bubble, where they drown.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/752", normalKey: "pokedex/normal/752", shinyKey: "pokedex/shiny/752", silhouetteKey: "pokedex/silhouette/752")),
        PokedexSpeciesDefinition(nationalDexNumber: 753, generation: 7, slug: "fomantis", name: "Fomantis", genus: "Sickle Grass Pokémon", description: "During the day, it sleeps and soaks up light. When night falls, it walks around looking for a safer place to sleep.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/753", normalKey: "pokedex/normal/753", shinyKey: "pokedex/shiny/753", silhouetteKey: "pokedex/silhouette/753")),
        PokedexSpeciesDefinition(nationalDexNumber: 754, generation: 7, slug: "lurantis", name: "Lurantis", genus: "Bloom Sickle Pokémon", description: "It requires a lot of effort to maintain Lurantis’s vivid coloring, but some collectors enjoy this work and treat it as their hobby.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/754", normalKey: "pokedex/normal/754", shinyKey: "pokedex/shiny/754", silhouetteKey: "pokedex/silhouette/754")),
        PokedexSpeciesDefinition(nationalDexNumber: 755, generation: 7, slug: "morelull", name: "Morelull", genus: "Illuminating Pokémon", description: "It scatters spores that flicker and glow. Anyone seeing these lights falls into a deep slumber.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/755", normalKey: "pokedex/normal/755", shinyKey: "pokedex/shiny/755", silhouetteKey: "pokedex/silhouette/755")),
        PokedexSpeciesDefinition(nationalDexNumber: 756, generation: 7, slug: "shiinotic", name: "Shiinotic", genus: "Illuminating Pokémon", description: "Forests where Shiinotic live are treacherous to enter at night. People confused by its strange lights can never find their way home again.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/756", normalKey: "pokedex/normal/756", shinyKey: "pokedex/shiny/756", silhouetteKey: "pokedex/silhouette/756")),
        PokedexSpeciesDefinition(nationalDexNumber: 757, generation: 7, slug: "salandit", name: "Salandit", genus: "Toxic Lizard Pokémon", description: "It burns its bodily fluids to create a poisonous gas. When its enemies become disoriented from inhaling the gas, it attacks them.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/757", normalKey: "pokedex/normal/757", shinyKey: "pokedex/shiny/757", silhouetteKey: "pokedex/silhouette/757")),
        PokedexSpeciesDefinition(nationalDexNumber: 758, generation: 7, slug: "salazzle", name: "Salazzle", genus: "Toxic Lizard Pokémon", description: "For some reason, only females have been found. It creates a reverse harem of male Salandit that it lives with.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/758", normalKey: "pokedex/normal/758", shinyKey: "pokedex/shiny/758", silhouetteKey: "pokedex/silhouette/758")),
        PokedexSpeciesDefinition(nationalDexNumber: 759, generation: 7, slug: "stufful", name: "Stufful", genus: "Flailing Pokémon", description: "Despite its adorable appearance, when it gets angry and flails about, its arms and legs could knock a pro wrestler sprawling.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/759", normalKey: "pokedex/normal/759", shinyKey: "pokedex/shiny/759", silhouetteKey: "pokedex/silhouette/759")),
        PokedexSpeciesDefinition(nationalDexNumber: 760, generation: 7, slug: "bewear", name: "Bewear", genus: "Strong Arm Pokémon", description: "This immensely dangerous Pokémon possesses overwhelming physical strength. Its habitat is generally off-limits.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/760", normalKey: "pokedex/normal/760", shinyKey: "pokedex/shiny/760", silhouetteKey: "pokedex/silhouette/760")),
        PokedexSpeciesDefinition(nationalDexNumber: 761, generation: 7, slug: "bounsweet", name: "Bounsweet", genus: "Fruit Pokémon", description: "A delectable aroma pours from its body. They are often swallowed whole by Toucannon lured by that wafting deliciousness.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/761", normalKey: "pokedex/normal/761", shinyKey: "pokedex/shiny/761", silhouetteKey: "pokedex/silhouette/761")),
        PokedexSpeciesDefinition(nationalDexNumber: 762, generation: 7, slug: "steenee", name: "Steenee", genus: "Fruit Pokémon", description: "The sepals on its head developed to protect its body. These are quite hard, so even if pecked by bird Pokémon, this Pokémon is totally fine.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/762", normalKey: "pokedex/normal/762", shinyKey: "pokedex/shiny/762", silhouetteKey: "pokedex/silhouette/762")),
        PokedexSpeciesDefinition(nationalDexNumber: 763, generation: 7, slug: "tsareena", name: "Tsareena", genus: "Fruit Pokémon", description: "Its long, striking legs aren’t just for show but to be used to kick with skill. In victory, it shows off by kicking the defeated, laughing boisterously.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/763", normalKey: "pokedex/normal/763", shinyKey: "pokedex/shiny/763", silhouetteKey: "pokedex/silhouette/763")),
        PokedexSpeciesDefinition(nationalDexNumber: 764, generation: 7, slug: "comfey", name: "Comfey", genus: "Posy Picker Pokémon", description: "It attaches flowers to its highly nutritious vine. This revitalizes the flowers, and they give off an aromatic scent.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/764", normalKey: "pokedex/normal/764", shinyKey: "pokedex/shiny/764", silhouetteKey: "pokedex/silhouette/764")),
        PokedexSpeciesDefinition(nationalDexNumber: 765, generation: 7, slug: "oranguru", name: "Oranguru", genus: "Sage Pokémon", description: "Known for its extreme intelligence, this Pokémon will look down on inexperienced Trainers, so it’s best suited to veteran Trainers.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/765", normalKey: "pokedex/normal/765", shinyKey: "pokedex/shiny/765", silhouetteKey: "pokedex/silhouette/765")),
        PokedexSpeciesDefinition(nationalDexNumber: 766, generation: 7, slug: "passimian", name: "Passimian", genus: "Teamwork Pokémon", description: "They form groups of roughly 20 individuals. Their mutual bond is remarkable—they will never let down a comrade.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/766", normalKey: "pokedex/normal/766", shinyKey: "pokedex/shiny/766", silhouetteKey: "pokedex/silhouette/766")),
        PokedexSpeciesDefinition(nationalDexNumber: 767, generation: 7, slug: "wimpod", name: "Wimpod", genus: "Turn Tail Pokémon", description: "This Pokémon is a coward. As it desperately dashes off, the flailing of its many legs leaves a sparkling clean path in its wake.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/767", normalKey: "pokedex/normal/767", shinyKey: "pokedex/shiny/767", silhouetteKey: "pokedex/silhouette/767")),
        PokedexSpeciesDefinition(nationalDexNumber: 768, generation: 7, slug: "golisopod", name: "Golisopod", genus: "Hard Scale Pokémon", description: "With a flashing slash of its giant sharp claws, it cleaves seawater—or even air—right in two.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/768", normalKey: "pokedex/normal/768", shinyKey: "pokedex/shiny/768", silhouetteKey: "pokedex/silhouette/768")),
        PokedexSpeciesDefinition(nationalDexNumber: 769, generation: 7, slug: "sandygast", name: "Sandygast", genus: "Sand Heap Pokémon", description: "Born from a sand mound playfully built by a child, this Pokémon embodies the grudges of the departed.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/769", normalKey: "pokedex/normal/769", shinyKey: "pokedex/shiny/769", silhouetteKey: "pokedex/silhouette/769")),
        PokedexSpeciesDefinition(nationalDexNumber: 770, generation: 7, slug: "palossand", name: "Palossand", genus: "Sand Castle Pokémon", description: "Possessed people controlled by this Pokémon transformed its sand mound into a castle. As it evolved, its power to curse grew ever stronger.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/770", normalKey: "pokedex/normal/770", shinyKey: "pokedex/shiny/770", silhouetteKey: "pokedex/silhouette/770")),
        PokedexSpeciesDefinition(nationalDexNumber: 771, generation: 7, slug: "pyukumuku", name: "Pyukumuku", genus: "Sea Cucumber Pokémon", description: "It lives in shallow seas, such as areas near a beach. It can eject its internal organs, which it uses to engulf its prey or battle enemies.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/771", normalKey: "pokedex/normal/771", shinyKey: "pokedex/shiny/771", silhouetteKey: "pokedex/silhouette/771")),
        PokedexSpeciesDefinition(nationalDexNumber: 772, generation: 7, slug: "type-null", name: "Type: Null", genus: "Synthetic Pokémon", description: "The heavy control mask it wears suppresses its intrinsic capabilities. This Pokémon has some hidden special power.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/772", normalKey: "pokedex/normal/772", shinyKey: "pokedex/shiny/772", silhouetteKey: "pokedex/silhouette/772")),
        PokedexSpeciesDefinition(nationalDexNumber: 773, generation: 7, slug: "silvally", name: "Silvally", genus: "Synthetic Pokémon", description: "Its trust in its partner is what awakens it. This Pokémon is capable of changing its type, a flexibility that is well displayed in battle.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/773", normalKey: "pokedex/normal/773", shinyKey: "pokedex/shiny/773", silhouetteKey: "pokedex/silhouette/773")),
        PokedexSpeciesDefinition(nationalDexNumber: 774, generation: 7, slug: "minior", name: "Minior", genus: "Meteor Pokémon", description: "Originally making its home in the ozone layer, it hurtles to the ground when the shell enclosing its body grows too heavy.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/774", normalKey: "pokedex/normal/774", shinyKey: "pokedex/shiny/774", silhouetteKey: "pokedex/silhouette/774")),
        PokedexSpeciesDefinition(nationalDexNumber: 775, generation: 7, slug: "komala", name: "Komala", genus: "Drowsing Pokémon", description: "It is born asleep, and it dies asleep. All its movements are apparently no more than the results of it tossing and turning in its dreams.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/775", normalKey: "pokedex/normal/775", shinyKey: "pokedex/shiny/775", silhouetteKey: "pokedex/silhouette/775")),
        PokedexSpeciesDefinition(nationalDexNumber: 776, generation: 7, slug: "turtonator", name: "Turtonator", genus: "Blast Turtle Pokémon", description: "The shell on its back is chemically unstable and explodes violently if struck. The hole in its stomach is its weak point.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/776", normalKey: "pokedex/normal/776", shinyKey: "pokedex/shiny/776", silhouetteKey: "pokedex/silhouette/776")),
        PokedexSpeciesDefinition(nationalDexNumber: 777, generation: 7, slug: "togedemaru", name: "Togedemaru", genus: "Roly-Poly Pokémon", description: "The spiny fur on its back is normally at rest. When this Pokémon becomes agitated, its fur stands on end and stabs into its attackers.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/777", normalKey: "pokedex/normal/777", shinyKey: "pokedex/shiny/777", silhouetteKey: "pokedex/silhouette/777")),
        PokedexSpeciesDefinition(nationalDexNumber: 778, generation: 7, slug: "mimikyu", name: "Mimikyu", genus: "Disguise Pokémon", description: "Its actual appearance is unknown. A scholar who saw what was under its rag was overwhelmed by terror and died from the shock.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/778", normalKey: "pokedex/normal/778", shinyKey: "pokedex/shiny/778", silhouetteKey: "pokedex/silhouette/778")),
        PokedexSpeciesDefinition(nationalDexNumber: 779, generation: 7, slug: "bruxish", name: "Bruxish", genus: "Gnash Teeth Pokémon", description: "When it unleashes its psychic power from the protuberance on its head, the grating sound of grinding teeth echoes through the area.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/779", normalKey: "pokedex/normal/779", shinyKey: "pokedex/shiny/779", silhouetteKey: "pokedex/silhouette/779")),
        PokedexSpeciesDefinition(nationalDexNumber: 780, generation: 7, slug: "drampa", name: "Drampa", genus: "Placid Pokémon", description: "It has a compassionate personality, but if it is angered, it completely destroys its surroundings with its intense breath.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/780", normalKey: "pokedex/normal/780", shinyKey: "pokedex/shiny/780", silhouetteKey: "pokedex/silhouette/780")),
        PokedexSpeciesDefinition(nationalDexNumber: 781, generation: 7, slug: "dhelmise", name: "Dhelmise", genus: "Sea Creeper Pokémon", description: "Swinging its massive anchor, it can KO Wailord in a single blow. What appears to be green seaweed is actually its body.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/781", normalKey: "pokedex/normal/781", shinyKey: "pokedex/shiny/781", silhouetteKey: "pokedex/silhouette/781")),
        PokedexSpeciesDefinition(nationalDexNumber: 782, generation: 7, slug: "jangmo-o", name: "Jangmo-o", genus: "Scaly Pokémon", description: "It expresses its feelings by smacking its scales. Metallic sounds echo through the tall mountains where Jangmo-o lives.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/782", normalKey: "pokedex/normal/782", shinyKey: "pokedex/shiny/782", silhouetteKey: "pokedex/silhouette/782")),
        PokedexSpeciesDefinition(nationalDexNumber: 783, generation: 7, slug: "hakamo-o", name: "Hakamo-o", genus: "Scaly Pokémon", description: "It leaps at its prey with a courageous shout. Its scaly punches tear its opponents to shreds.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/783", normalKey: "pokedex/normal/783", shinyKey: "pokedex/shiny/783", silhouetteKey: "pokedex/silhouette/783")),
        PokedexSpeciesDefinition(nationalDexNumber: 784, generation: 7, slug: "kommo-o", name: "Kommo-o", genus: "Scaly Pokémon", description: "When it spots enemies, it threatens them by jingling the scales on its tail. Weak opponents will crack and flee in panic.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/784", normalKey: "pokedex/normal/784", shinyKey: "pokedex/shiny/784", silhouetteKey: "pokedex/silhouette/784")),
        PokedexSpeciesDefinition(nationalDexNumber: 785, generation: 7, slug: "tapu-koko", name: "Tapu Koko", genus: "Land Spirit Pokémon", description: "This guardian deity of Melemele is brimming with curiosity. It summons thunderclouds and stores their lightning inside its body.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/785", normalKey: "pokedex/normal/785", shinyKey: "pokedex/shiny/785", silhouetteKey: "pokedex/silhouette/785")),
        PokedexSpeciesDefinition(nationalDexNumber: 786, generation: 7, slug: "tapu-lele", name: "Tapu Lele", genus: "Land Spirit Pokémon", description: "This guardian deity of Akala is guilelessly cruel. The fragrant aroma of flowers is the source of its energy.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/786", normalKey: "pokedex/normal/786", shinyKey: "pokedex/shiny/786", silhouetteKey: "pokedex/silhouette/786")),
        PokedexSpeciesDefinition(nationalDexNumber: 787, generation: 7, slug: "tapu-bulu", name: "Tapu Bulu", genus: "Land Spirit Pokémon", description: "It pulls large trees up by the roots and swings them around. It causes vegetation to grow, and then it absorbs energy from the growth.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/787", normalKey: "pokedex/normal/787", shinyKey: "pokedex/shiny/787", silhouetteKey: "pokedex/silhouette/787")),
        PokedexSpeciesDefinition(nationalDexNumber: 788, generation: 7, slug: "tapu-fini", name: "Tapu Fini", genus: "Land Spirit Pokémon", description: "The dense fog it creates brings the downfall and destruction of its confused enemies. Ocean currents are the source of its energy.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/788", normalKey: "pokedex/normal/788", shinyKey: "pokedex/shiny/788", silhouetteKey: "pokedex/silhouette/788")),
        PokedexSpeciesDefinition(nationalDexNumber: 789, generation: 7, slug: "cosmog", name: "Cosmog", genus: "Nebula Pokémon", description: "Its body is gaseous and frail. It slowly grows as it collects dust from the atmosphere.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/789", normalKey: "pokedex/normal/789", shinyKey: "pokedex/shiny/789", silhouetteKey: "pokedex/silhouette/789")),
        PokedexSpeciesDefinition(nationalDexNumber: 790, generation: 7, slug: "cosmoem", name: "Cosmoem", genus: "Protostar Pokémon", description: "Motionless as if dead, its body is faintly warm to the touch. In the distant past, it was called the cocoon of the stars.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/790", normalKey: "pokedex/normal/790", shinyKey: "pokedex/shiny/790", silhouetteKey: "pokedex/silhouette/790")),
        PokedexSpeciesDefinition(nationalDexNumber: 791, generation: 7, slug: "solgaleo", name: "Solgaleo", genus: "Sunne Pokémon", description: "It is said to live in another world. The intense light it radiates from the surface of its body can make the darkest of nights light up like midday.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/791", normalKey: "pokedex/normal/791", shinyKey: "pokedex/shiny/791", silhouetteKey: "pokedex/silhouette/791")),
        PokedexSpeciesDefinition(nationalDexNumber: 792, generation: 7, slug: "lunala", name: "Lunala", genus: "Moone Pokémon", description: "It is said to be a female evolution of Cosmog. When its third eye activates, away it flies to another world.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/792", normalKey: "pokedex/normal/792", shinyKey: "pokedex/shiny/792", silhouetteKey: "pokedex/silhouette/792")),
        PokedexSpeciesDefinition(nationalDexNumber: 793, generation: 7, slug: "nihilego", name: "Nihilego", genus: "Parasite Pokémon", description: "One of several mysterious Ultra Beasts. People on the street report observing those infested by it suddenly becoming violent.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/793", normalKey: "pokedex/normal/793", shinyKey: "pokedex/shiny/793", silhouetteKey: "pokedex/silhouette/793")),
        PokedexSpeciesDefinition(nationalDexNumber: 794, generation: 7, slug: "buzzwole", name: "Buzzwole", genus: "Swollen Pokémon", description: "This Ultra Beast appeared from another world. It shows off its body, but whether that display is a boast or a threat remains unclear.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/794", normalKey: "pokedex/normal/794", shinyKey: "pokedex/shiny/794", silhouetteKey: "pokedex/silhouette/794")),
        PokedexSpeciesDefinition(nationalDexNumber: 795, generation: 7, slug: "pheromosa", name: "Pheromosa", genus: "Lissome Pokémon", description: "One of the dangerous Ultra Beasts, it has been spotted running across the land at terrific speeds.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/795", normalKey: "pokedex/normal/795", shinyKey: "pokedex/shiny/795", silhouetteKey: "pokedex/silhouette/795")),
        PokedexSpeciesDefinition(nationalDexNumber: 796, generation: 7, slug: "xurkitree", name: "Xurkitree", genus: "Glowing Pokémon", description: "One of the mysterious life-forms known as Ultra Beasts. Astonishing electric shocks emanate from its entire body, according to witnesses.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/796", normalKey: "pokedex/normal/796", shinyKey: "pokedex/shiny/796", silhouetteKey: "pokedex/silhouette/796")),
        PokedexSpeciesDefinition(nationalDexNumber: 797, generation: 7, slug: "celesteela", name: "Celesteela", genus: "Launch Pokémon", description: "It appeared from the Ultra Wormhole. Witnesses observed it flying across the sky at high speed.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/797", normalKey: "pokedex/normal/797", shinyKey: "pokedex/shiny/797", silhouetteKey: "pokedex/silhouette/797")),
        PokedexSpeciesDefinition(nationalDexNumber: 798, generation: 7, slug: "kartana", name: "Kartana", genus: "Drawn Sword Pokémon", description: "This Ultra Beast came from the Ultra Wormhole. It seems not to attack enemies on its own, but its sharp body is a dangerous weapon in itself.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/798", normalKey: "pokedex/normal/798", shinyKey: "pokedex/shiny/798", silhouetteKey: "pokedex/silhouette/798")),
        PokedexSpeciesDefinition(nationalDexNumber: 799, generation: 7, slug: "guzzlord", name: "Guzzlord", genus: "Junkivore Pokémon", description: "It has gobbled mountains and swallowed whole buildings, according to reports. It’s one of the Ultra Beasts.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/799", normalKey: "pokedex/normal/799", shinyKey: "pokedex/shiny/799", silhouetteKey: "pokedex/silhouette/799")),
        PokedexSpeciesDefinition(nationalDexNumber: 800, generation: 7, slug: "necrozma", name: "Necrozma", genus: "Prism Pokémon", description: "Reminiscent of the Ultra Beasts, this life-form, apparently asleep underground, is thought to have come from another world in ancient times.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/800", normalKey: "pokedex/normal/800", shinyKey: "pokedex/shiny/800", silhouetteKey: "pokedex/silhouette/800")),
        PokedexSpeciesDefinition(nationalDexNumber: 801, generation: 7, slug: "magearna", name: "Magearna", genus: "Artificial Pokémon", description: "This artificial Pokémon, constructed more than 500 years ago, can understand human speech but cannot itself speak.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/801", normalKey: "pokedex/normal/801", shinyKey: "pokedex/shiny/801", silhouetteKey: "pokedex/silhouette/801")),
        PokedexSpeciesDefinition(nationalDexNumber: 802, generation: 7, slug: "marshadow", name: "Marshadow", genus: "Gloomdweller Pokémon", description: "Able to conceal itself in shadows, it never appears before humans, so its very existence was the stuff of myth.", spriteAsset: PokedexSpriteAsset(activeKey: "pokedex/normal/802", normalKey: "pokedex/normal/802", shinyKey: "pokedex/shiny/802", silhouetteKey: "pokedex/silhouette/802")),
    ]
}
